urement p₁ (S.pointMeasExp p₁.side .Z xz.2)) +    (S.placedMeasurement p₂ (S.pointMeasExp p₂.side .Z xz.2)) +    (S.placedMeasurement_isProjective p₁ _ (S.pointMeasExp_isProjective _ _ _)) +    (S.placedMeasurement_isProjective p₂ _ (S.pointMeasExp_isProjective _ _ _)) +    (S.placedMeasurement_isProjective p₁ _ (S.pointMeasExp_isProjective _ _ _)) +    (S.placedMeasurement_isProjective p₂ _ (S.pointMeasExp_isProjective _ _ _)) +    (fun a b => S.place_comm p₁ p₂ hopp _ _) +    (fun a b => S.place_comm p₁ p₂ hopp _ _) +    (fun b => S.place_comm p₁ p₂ hopp _ _) +  simp only [placedMeasurement_effect, psiHat_norm] at hkey +  unfold sandwichDefectBound +  simp only [sandwichPoint_effect, place_mul] +  simpa only [place_mul] using hkey + +/-- The average over the point pair of the pointwise bound is polynomially +small: at most a universal constant times `ε + √ε`.  The `X`- and +`Z`-distances are the self-consistency of item 1 of `lem:qld-comm-cons`, and +the two commutator sums are the field-valued commutation estimate. -/ +theorem avg_sandwichDefectBound_le : +    ∃ C : ℝ, 1 ≤ C ∧ +      ∀ (P : AdmissibleParams) (ε : ℝ) (S : ProjectiveSetting P ε) +        (p₁ p₂ : Placement), p₁.IsOpposite p₂ → +        avgOver (uniformDistribution (PointPair P)) (S.sandwichDefectBound p₁ p₂) ≤ +          C * (ε + Real.sqrt ε) := by +  obtain ⟨C₁, hC₁, h₁⟩ := expPoint_self_cons +  obtain ⟨C₂, hC₂, h₂⟩ := expPoint_comm +  refine ⟨2 * C₁ + 3 * C₂, by linarith, ?_⟩ +  intro P ε S p₁ p₂ hopp +  have hε : (0 : ℝ) ≤ ε := by +    have hv := WinImplications.strategy_value_le_one S.toStrategy +    have hw := S.win +    linarith +  have hZ : avgOver (uniformDistribution (PointPair P)) (fun xz => +      ∑ b : PauliScalar P, ‖applyOperatorToState +        (S.place p₁ ((S.pointMeasExp p₁.side .Z xz.2).effect b) - +          S.place p₂ ((S.pointMeasExp p₂.side .Z xz.2).effect b)) S.psiHat‖ ^ 2) ≤ +      C₁ * ε := by +    rw [avgOver_uniform_snd (α := Fin P.m → PauliScalar P) +      (fun z => ∑ b 