fun i => (i, k₀)) (fun i => (i, k₀))) +    (fun a => Matrix.nonneg_iff_posSemidef.mpr +      ((Matrix.nonneg_iff_posSemidef.mp (M.pos a)).submatrix (fun i => (i, k₀)))) +    (by +      classical +      ext i j +      simpa only [Matrix.sum_apply, Matrix.submatrix_apply, Matrix.one_apply, +        Prod.mk.injEq, and_true] +        using congrFun (congrFun M.sum_eq_one (i, k₀)) (j, k₀)) + +@[simp] theorem compressAt_effect +    {Outcome I κ : Type*} +    [Fintype Outcome] [Fintype I] [DecidableEq I] +    [Fintype κ] [DecidableEq κ] +    (k₀ : κ) (M : MIPStarRE.Quantum.Measurement Outcome (I × κ)) (a : Outcome) : +    (M.compressAt k₀).effect a = +      (M.effect a).submatrix (fun i => (i, k₀)) (fun i => (i, k₀)) := +  rfl + +/-- Restricting a POVM to a fixed ancillary coordinate commutes with +deterministic relabeling of its outcomes. -/ +theorem compressAt_postprocess +    {A B I κ : Type*} +    [Fintype A] [DecidableEq A] [Fintype B] [DecidableEq B] +    [Fintype I] [DecidableEq I] [Fintype κ] [DecidableEq κ] +    (k₀ : κ) (M : MIPStarRE.Quantum.Measurement A (I × κ)) (f : A → B) : +    (M.postprocess f).compressAt k₀ = (M.compressAt k₀).postprocess f := by +  classical +  apply MIPStarRE.Quantum.Measurement.ext +  intro b +  ext i j +  simp only [compressAt_effect, MIPStarRE.Quantum.Measurement.postprocess_effect, +    Matrix.submatrix_apply, Matrix.sum_apply] + +end MIPStarRE.Quantum.Measurement + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT MIPStarRE.Quantum + +namespace Measurement + +/-- Compressing the completed one-measurement Naimark dilation at its +distinguished `none` coordinate recovers the original POVM. -/ +theorem compressAt_dilatedMeasurement +    {A I : Type} [Fintype A] [DecidableEq A] +    [Fintype I] [DecidableEq I] +    (a₀ : A) (M : MIPStarRE.Quantum.Measurement A I) : +    (dilatedMeasurement a₀ M).compressAt none = M := by +  apply MIPStarRE.Quantum.Measurement.ext +  intro a +  ext i j +  exact dilatedMeasurement_compression a₀ a M i j + 