E/QPBT/Games/MeasurementCompression.lean b/MIPStarRE/QPBT/Games/MeasurementCompression.lean new file mode 100644 index 00000000..8f8b5d4c --- /dev/null +++ b/MIPStarRE/QPBT/Games/MeasurementCompression.lean @@ -0,0 +1,132 @@ +import MIPStarRE.QPBT.Games.StrategyClasses + +/-! +# Ground-slice compression of measurements + +This module restricts a POVM on a product space to one distinguished ancillary +coordinate. It also records that this restriction commutes with deterministic +outcome postprocessing, recovers a POVM from its one-measurement Naimark +dilation, and preserves consistency defects evaluated on the correspondingly +padded bipartite state. + +The construction supports the pullback after the first paragraph of the proof +of paper `lem:qld-4-7`, +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1279-1289`. +-/ + +open scoped BigOperators Matrix MatrixOrder ComplexOrder + +namespace MIPStarRE.Quantum.Measurement + +/-- Restrict every effect of a POVM to the matrix block at one fixed ancillary +coordinate. The principal submatrix of a positive semidefinite effect remains +positive semidefinite, and restricting the sum of the effects restricts the +identity to the identity. -/ +noncomputable def compressAt +    {Outcome I κ : Type*} +    [Fintype Outcome] [Fintype I] [DecidableEq I] +    [Fintype κ] [DecidableEq κ] +    (k₀ : κ) (M : MIPStarRE.Quantum.Measurement Outcome (I × κ)) : +    MIPStarRE.Quantum.Measurement Outcome I := +  MIPStarRE.Quantum.Measurement.ofSumEqOne +    (fun a => (M.effect a).submatrix (fun i => (i, k₀)) (fun i => (i, k₀))) +    (fun a => Matrix.nonneg_iff_posSemidef.mpr +      ((Matrix.nonneg_iff_posSemidef.mp (M.pos a)).submatrix (fun i => (i, k₀)))) +    (by +      classical +      ext i j +      simpa only [Matrix.sum_apply, Matrix.submatrix_apply, Matrix.one_apply, +        Prod.mk.injEq, and_true] +        using congrFun (congrFun M.sum_eq_one (i, k₀)) (j, k₀)) + +@[simp] theorem compressAt_effect +    {Outcome I κ : Type*} +    [Fintype Outcome] [Fintype I] [DecidableEq I] +    [Fintype κ] [DecidableEq κ] +    (k₀ : κ) (M : MIPStarRE.Quantum.Measurement Outcome (I × κ)) (a : Outcome) : +    (M.compressAt k₀).effect a = +      (M.effect a).submatrix (fun i => (i, k₀)) (fun i => (i, k₀)) := +  rfl + +/-- Restricting a POVM to a fixed ancillary coordinate commutes with +deterministic relabeling of its outcomes. -/ +theorem compressAt_postprocess +    {A B I κ : Type*} +    [Fintype A] [DecidableEq A] [Fintype B] [DecidableEq B] +    [Fintype I] [DecidableEq I] [Fintype κ] [DecidableEq κ] +    (k₀ : κ) (M : MIPStarRE.Quantum.Measurement A (I × κ)) (f : A → B) : +    (M.postprocess f).compressAt k₀ = (M.compressAt k₀).postprocess f := by +  classical +  apply MIPStarRE.Quantum.Measurement.ext +  intro b +  ext i j +  simp only [compressAt_effect, MIPStarRE.Quantum.Measurement.postprocess_effect, +    Matrix.submatrix_apply, Matrix.sum_apply] + +end MIPStarRE.Quantum.Measurement + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT MIPStarRE.Quantum + +namespace Measurement + +/-- Compressing the completed one-measurement Naimark dilation at its +distinguished `none` coordinate recovers the original POVM. -/ +theorem compressAt_dilatedMeasurement +    {A I : Type} [Fintype A] [DecidableEq A] +    [Fintype I] [DecidableEq I] +    (a₀ : A) (M : MIPStarRE.Quantum.Measurement A I) : +    (dilatedMeasurement a₀ M).compressAt none = M := by +  apply MIPStarRE.Quantum.Measurement.ext +  intro a +  ext i j +  exact dilatedMeasurement_compression a₀ a M i j + +end Measurement + +/-- Ground-slice compression preserves exactly the off-diagonal consistency +defect when the bipartite state is padded at the same two ancillary +coordinates. This is an equality of POVM correlations and does not assert that +the compressed measurements are projective. -/ +theorem consistencyDefect_padState_compressAt +    {X Outcome I J κA κB : Type*} +    [Fintype X] [DecidableEq X] +    [Fintype Outcome] [DecidableEq 