 every question. -/\n +theorem opFamilyDistSq_uniform_le_four {X α ι : Type*} [Fintype X] [DecidableEq X]\n +    [Nonempty X] [Fintype α] [Fintype ι] [DecidableEq ι]\n +    (A B : X → α → Op ι) (ψ : EuclideanSpace ℂ ι) (hψ : ‖ψ‖ = 1)\n +    (hA : ∀ x, ∑ a, (A x a)ᴴ * A x a ≤ 1) (hB : ∀ x, ∑ a, (B x a)ᴴ * B x a ≤ 1) :\n +    opFamilyDistSq (uniformDistribution X) A B ψ ≤ 4 := by\n +  unfold opFamilyDistSq\n +  calc avgOver (uniformDistribution X) (fun x =>\n +        ∑ a, ‖applyOperatorToState (A x a - B x a) ψ‖ ^ 2)\n +      ≤ avgOver (uniformDistribution X) (fun _ => (4 : ℝ)) := by\n +        refine avgOver_mono _ _ _ fun x => ?_\n +        have hA' := sum_norm_apply_sq_le_one (A x) ψ hψ (hA x)\n +        have hB' := sum_norm_apply_sq_le_one (B x) ψ hψ (hB x)\n +        have hpt : ∀ a, ‖applyOperatorToState (A x a - B x a) ψ‖ ^ 2 ≤\n +            2 * ‖applyOperatorToState (A x a) ψ‖ ^ 2 +\n +              2 * ‖applyOperatorToState (B x a) ψ‖ ^ 2 := by\n +          intro a\n +          have hsub : applyOperatorToState (A x a - B x a) ψ =\n +              applyOperatorToState (A x a) ψ - applyOperatorToState (B x a) ψ := by\n +            simp [applyOperatorToState]\n +          rw [hsub]\n +          have := norm_sub_le (applyOperatorToState (A x a) ψ)\n +            (applyOperatorToState (B x a) ψ)\n +          nlinarith [norm_nonneg (applyOperatorToState (A x a) ψ),\n +            norm_nonneg (applyOperatorToState (B x a) ψ),\n +            norm_nonneg (applyOperatorToState (A x a) ψ -\n +              applyOperatorToState (B x a) ψ),\n +            sq_nonneg (‖applyOperatorToState (A x a) ψ‖ -\n +              ‖applyOperatorToState (B x a) ψ‖)]\n +        calc ∑ a, ‖applyOperatorToState (A x a - B x a) ψ‖ ^ 2\n +            ≤ ∑ a, (2 * ‖applyOperatorToState (A x a) ψ‖ ^ 2 +\n +                2 * ‖applyOperatorToState (B x a) ψ‖ ^ 2) :=\n +              Finset.sum_le_sum fun a _ => hpt a\n +          _ = 2 * ∑ a, ‖applyOperatorToState (A x a) ψ‖ ^ 2 +\n +                2 * ∑ a, ‖applyOperatorToState (B x a) ψ‖ ^ 2 := by\n +              rw [Finset.sum_add_distrib, Finset.mul_sum, Finset.mul_sum]\n +          _ ≤ 4 := by linarith\n +    _ = 4 := avgOver_uniform_const _\n +\n +/-- The sum of adjoint products of the effects of a projective measurement,\n +placed on a register pair, is at most the identity. -/\n +theorem ProjectiveSetting.sum_place_effect_conjTranspose_mul_self_le_one\n +    {P : AdmissibleParams} {ε : ℝ} (S : ProjectiveSetting P ε) (p : Placement)\n +    {α : Type*} [Fintype α] (M : Measurement α (S.ExpandedLocalSpace p.side))\n +    (hM : MIPStarRE.QPBT.Measurement.IsProjective M) :\n +    ∑ a, (S.place p (M.effect a))ᴴ * S.place p (M.effect a) ≤ 1 := by\n +  refine le_of_eq ?_\n +  calc ∑ a, (S.place p (M.effect a))ᴴ * S.place p (M.effect a)\n +      = ∑ a, S.place p (M.effect a) := by\n +        refine Finset.sum_congr rfl fun a _ => ?_\n +        rw [← S.place_conjTranspose, ← S.place_mul,\n +          (hM a).isSelfAdjoint.isHermitian.eq, (hM a).isIdempotentElem.eq]\n +    _ = 1 := by rw [← S.place_finsetSum, M.sum_eq_one, S.place_one]\n +\n +/-- The products `A_a B_b` of the effects of two projective measurements on a\n +common space satisfy `∑ a b, (A_a B_b)ᴴ * (A_a B_b) = 1`. -/\n +theorem sum_mul_conjTranspose_mul_self_eq_one {α β ι : Type*} [Fintype α]\n +    [Fintype β] [Fintype ι] [DecidableEq ι]\n +    (A : Measurement α ι) (B : Measurement β ι)\n +    (hA : MIPStarRE.QPBT.Measurement.IsProjective A)\n +    (hB : MIPStarRE.QPBT.Measurement.IsProjective B) :\n +    ∑ ab : α × β, (A.effect ab.1 * B.effect ab.2)ᴴ * (A.effect ab.1 * B.effect ab.2) =\n +      1 := by\n +  have hpt : ∀ (a : α) (b : β),\n +      (A.effect a * B.effect b)ᴴ * (A.effect a * B.effect b) =\n +        B.effect b * A.effect a * B.effect b := by\n +    intro a b\n +    rw [Matrix.conjTranspose_mul, (hA a).isSelfAdjoint.isHermitian.eq,\n +      (hB b).isSelfAdjoint.isHermitian.eq, Matrix.mul_assoc _ _ (A.effect a * B.effect b),\n +      ← Matrix.mul_assoc (A.effect a) (A.effect a), (hA a).isIdempotentElem.eq,\n +      ← Matrix.mul_assoc]\n +  rw [Fintype.sum_prod_type_right]\n +  calc ∑ b : β, ∑ a : α, (A.effect a * B.effect b)ᴴ * (A.effect a * B.effect b)\n +      = ∑ b : β, B.effect b * (∑ a : α, A.effect a) * B.effect b := by\n +        refine Finset.sum_congr rfl fun b _ => ?_\n +        rw [Finset.mul_sum, Finset.sum_mul]\n +        exact Finset.sum_congr rfl fun a _ => hpt a b\n +    _ = 1 := by\n +        simp_rw [A.sum_eq_one, mul_one]\n +        rw [Finset.sum_congr rfl fun b _ => (hB b).isIdempotentElem.eq]\n +        exact B.sum_eq_one\n +\n +/-- The products `B_b A_a` of the effects of two projective measurements on a\n +common space, indexed by the pair `(a, b)`, satisfy\n +`∑ a b, (B_b A_a)ᴴ * (B_b A_a) = 1`. -/\n +theorem sum_mul_conjTranspose_mul_self_eq_one' {α β ι : Type*} [Fintype α]\n +    [Fintype β] [Fintype ι] [DecidableEq ι]\n +    (A : Measurement α ι) (B : Measurement β ι)\n +    (hA : MIPStarRE.QPBT.Measurement.IsProjective A)\n +    (hB : MIPStarRE.QPBT.Measurement.IsProjective B) :\n +    ∑ ab : α × β, (B.effect ab.2 * A.effect ab.1)ᴴ * (B.effect ab.2 * A.effect ab.1) =\n +      1 := by\n +  have hpt : ∀ (a : α) (b : β),\n +      (B.effect b * A.effect a)ᴴ * (B.effect b * A.effect a) =\n +        A.effect a * B.effect b * A.effect a := by\n +    intro a b\n +    rw [Matrix.conjTranspose_mul, (hA a).isSelfAdjoint.isHermitian.eq,\n +      (hB b).isSelfAdjoint.isHermitian.eq, Matrix.mul_assoc _ _ (B.effect b * A.effect a),\n +      ← Matrix.mul_assoc (B.effect b) (B.effect b), (hB b).isIdempotentElem.eq,\n +      ← Matrix.mul_assoc]\n +  rw [Fintype.sum_prod_type]\n +  calc ∑ a : α, ∑ b : β, (B.effect b * A.effect a)ᴴ * (B.effect b * A.effect a)\n +      = ∑ a : α, A.effect a * (∑ b : β, B.effect b) * A.effect a := by\n +        refine Finset.sum_congr rfl fun a _ => ?_\n +        rw [Finset.mul_sum, Finset.sum_mul]\n +        exact Finset.sum_congr rfl fun b _ => hpt a b\n +    _ = 1 := by\n +        simp_rw [B.sum_eq_one, mul_one]\n +        rw [Finset.sum_congr rfl fun a _ => (hA a).isIdempotentElem.eq]\n +        exact A.sum_eq_one\n +\n +/-! ## The chain of closeness estimates -/\n +\n +namespace ProjectiveSetting\n +\n +variable {P : AdmissibleParams} {ε : ℝ}\n +\n +/-- The three closeness conclusions of `lem:qld-4-10` for a pair of projective\n +families close to the placed sandwiches: with `η` the closeness of `Q` to `R`\n +on every placement, `C₁ √ε` the closeness of `R` to the ordered product,\n +`C₂ √ε` the commutation error, and `C₃ ε` the cross-placement consistency of\n +the ordered products, the distances from `Q` on one placement to the two\n +ordered products and to `Q` on the opposite placement are bounded by explicit\n +combinations.  Paper\n +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:838-881`. -/\n +theorem chain_bounds (S : ProjectiveSetting P ε)\n +    (Q : (side : PlayerSide) → PointPair P →\n +      Measurement (PauliScalar P × PauliScalar P) (S.ExpandedLocalSpace side))\n +    (η C₁ C₂ C₃ : ℝ)\n +    (hQR : ∀ p : Placement, opFamilyDistSq (uniformDistribution (PointPair P))\n +      (fun xz (ab : PauliScalar P × PauliScalar P) =>\n +        S.place p ((Q p.side xz).effect ab))\n +      (fun xz ab => S.place p ((S.sandwichPoint p.side xz.1 xz.2).effect ab))\n +      S.psiHat ≤ η)\n +    (h₁ : ∀ p : Placement, opFamilyDistSq (uniformDistribution (PointPair P))\n +      (fun xz (ab : PauliScalar P × PauliScalar P) =>\n +        S.place p ((S.sandwichPoint p.side xz.1 xz.2).effect ab))\n +      (fun xz ab => S.place p\n +        ((S.pointMeasExp p.side .Z xz.2).effect ab.2 *\n +          (S.pointMeasExp p.side .X xz.1).effect ab.1))\n +      S.psiHat ≤ C₁ * Real.sqrt ε)\n +    (h₂ : ∀ p : Placement, opFamilyDistSq (uniformDistribution (PointPair P))\n +      (fun xz (ab : PauliScalar P × PauliScalar P) => S.place p\n +        ((S.pointMeasExp p.side .X xz.1).effect ab.1 *\n +          (S.pointMeasExp p.side .Z xz.2).effect ab.2))\n +      (fun xz ab => S.place p\n +        ((S.pointMeasExp p.side .Z xz.2).effect ab.2 *\n +          (S.pointMeasExp p.side .X xz.1).effect ab.1))\n +      S.psiHat ≤ C₂ * Real.sqrt ε)\n +    (h₃ : ∀ p₁ p₂ : Placement, p₁.IsOpposite p₂ →\n +      opFamilyDistSq (uniformDistribution (PointPair P))\n +        (fun xz (ab : PauliScalar P × PauliScalar P) => S.place p₁\n +          ((S.pointMeasExp p₁.side .Z xz.2).effect ab.2 *\n +            (S.pointMeasExp p₁.side .X xz.1).effect ab.1))\n +        (fun xz ab => S.place p₂\n +          ((S.pointMeasExp p₂.side .X xz.1).effect ab.1 *\n +            (S.pointMeasExp p₂.side .Z xz.2).effect ab.2))\n +        S.psiHat ≤ C₃ * ε)\n +    (p₁ p₂ : Placement) (hopp : p₁.IsOpposite p₂) :\n +    opFamilyDistSq (uniformDistribution (PointPair P))\n +        (fun xz (ab : PauliScalar P × PauliScalar P) =>\n +          S.place p₁ ((Q p₁.side xz).effect ab))\n +        (fun xz ab => S.place p₂\n +          ((S.pointMeasExp p₂.side .X xz.1).effect ab.1 *\n +            (S.pointMeasExp p₂.side .Z xz.2).effect ab.2))\n +        S.psiHat ≤ 2 * η + 4 * (C₁ * Real.sqrt ε) + 4 * (C₃ * ε) ∧\n +      opFamilyDistSq (uniformDistribution (PointPair P))\n +        (fun xz (ab : PauliScalar P × PauliScalar P) =>\n +          S.place p₁ ((Q p₁.side xz).effect ab))\n +        (fun xz ab => S.place p₂\n +          ((S.pointMeasExp p₂.side .Z xz.2).effect ab.2 *\n +            (S.pointMeasExp p₂.side .X xz.1).effect ab.1))\n +        S.psiHat ≤ 4 * η + 8 * (C₁ * Real.sqrt ε) + 8 * (C₃ * ε) +\n +          2 * (C₂ * Real.sqrt ε) ∧\n +      opFamilyDistSq (uniformDistribution (PointPair P))\n +        (fun xz (ab : PauliScalar P × PauliScalar P) =>\n +          S.place p₁ ((Q p₁.side xz).effect ab))\n +        (fun xz ab => S.place p₂ ((Q p₂.side xz).effect ab))\n +        S.psiHat ≤ 12 * η + 20 * (C₁ * Real.sqrt ε) + 16 * (C₃ * ε) +\n +          4 * (C₂ * Real.sqrt ε) := by\n +  -- `R_1 ≈ M^X M^Z` on the opposite placement\n +  have hRXZ := opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P))\n +    _ _ _ S.psiHat _ _ (h₁ p₁) (h₃ p₁ p₂ hopp)\n +  -- `Q_1 ≈ M^X M^Z` on the opposite placement\n +  have hQXZ := opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P))\n +    _ _ _ S.psiHat _ _ (hQR p₁) hRXZ\n +  -- `Q_1 ≈ M^Z M^X` on the opposite placement\n +  have hQZX := opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P))\n +    _ _ _ S.psiHat _ _ hQXZ (h₂ p₂)\n +  -- `M^Z M^X ≈ Q_2` on the opposite placement\n +  have hZXQ : opFamilyDistSq (uniformDistribution (PointPair P))\n +      (fun xz (ab : PauliScalar P × PauliScalar P) => S.place p₂\n +        ((S.pointMeasExp p₂.side .Z xz.2).effect ab.2 *\n +          (S.pointMeasExp p₂.side .X xz.1).effect ab.1))\n +      (fun xz ab => S.place p₂ ((Q p₂.side xz).effect ab))\n +      S.psiHat ≤ 2 * η + 2 * (C₁ * Real.sqrt ε) := by\n +    rw [opFamilyDistSq_symm]\n +    exact opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P))\n +      _ _ _ S.psiHat _ _ (hQR p₂) (h₁ p₂)\n +  have hQQ := opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P))\n +    _ _ _ S.psiHat _ _ hQZX hZXQ\n +  refine ⟨by linarith, by linarith, by linarith⟩\n +\n +end ProjectiveSetting\n +\n +/-! ## Collapsing the error terms into one power -/\n +\n +/-- For `0 ≤ ε ≤ 1`, the error terms `ε`, `√ε`, and `(C₀ (ε + √ε))^{1/4}`\n +with `C₀ ≥ 1` are all bounded by multiples of `ε^{1/8}`. -/\n +theorem error_terms_le_rpow_eighth {ε C₀ : ℝ} (hε : 0 ≤ ε) (hε1 : ε ≤ 1)\n +    (hC₀ : 1 ≤ C₀) :\n +    ε ≤ Real.rpow ε (1 / 8 : ℝ) ∧ Real.sqrt ε ≤ Real.rpow ε (1 / 8 : ℝ) ∧\n +      Real.rpow (C₀ * (ε + Real.sqrt ε)) (1 / 4 : ℝ) ≤\n +        2 * C₀ * Real.rpow ε (1 / 8 : ℝ) := by\n +  rcases eq_or_lt_of_le hε with h0 | hpos\n +  · subst h0\n +    have h8 : Real.rpow (0 : ℝ) (1 / 8 : ℝ) = 0 := Real.zero_rpow (by norm_num)\n +    have h4 : Real.rpow (C₀ * (0 + Real.sqrt 0)) (1 / 4 : ℝ) = 0 := by\n +      rw [Real.sqrt_zero, add_zero, mul_zero]\n +      exact Real.zero_rpow (by norm_num)\n +    rw [h8, h4, Real.sqrt_zero]\n +    refine ⟨le_rfl, le_rfl, ?_⟩\n +    positivity\n +  · have hsqrt : Real.sqrt ε = Real.rpow ε (1 / 2 : ℝ) := Real.sqrt_eq_rpow ε\n +    have hε1' : Real.rpow ε 1 = ε := Real.rpow_one ε\n +    have hmono : ∀ y z : ℝ, z ≤ y → Real.rpow ε y ≤ Real.rpow ε z := fun y z hyz =>\n +      Real.rpow_le_rpow_of_exponent_ge hpos hε1 hyz\n +    refine ⟨?_, ?_, ?_⟩\n +    · exact le_of_eq_of_le hε1'.symm (hmono 1 (1 / 8) (by norm_num))\n +    · rw [hsqrt]\n +      exact hmono (1 / 2) (1 / 8) (by norm_num)\n +    · have hsum : ε + Real.sqrt ε ≤ 2 * Real.sqrt ε := by\n +        have : ε ≤ Real.sqrt ε := by\n +          rw [hsqrt]\n +          exact le_of_eq_of_le hε1'.symm (hmono 1 (1 / 2) (by norm_num))\n +        linarith\n +      have hC : 0 ≤ 2 * C₀ := by linarith\n +      calc Real.rpow (C₀ * (ε + Real.sqrt ε)) (1 / 4 : ℝ)\n +          ≤ Real.rpow (2 * C₀ * Real.sqrt ε) (1 / 4 : ℝ) := by\n +            apply Real.rpow_le_rpow (by positivity) _ (by norm_num)\n +            nlinarith [Real.sqrt_nonneg ε]\n +        _ = Real.rpow (2 * C₀) (1 / 4 : ℝ) * Real.rpow ε (1 / 8 : ℝ) := by\n +            change (2 * C₀ * Real.sqrt ε) ^ (1 / 4 : ℝ) =\n +              (2 * C₀) ^ (1 / 4 : ℝ) * ε ^ (1 / 8 : ℝ)\n +            rw [Real.mul_rpow hC (Real.sqrt_nonneg ε), Real.sqrt_eq_rpow,\n +              ← Real.rpow_mul hε]\n +            norm_num\n +        _ ≤ 2 * C₀ * Real.rpow ε (1 / 8 : ℝ) := by\n +            refine mul_le_mul_of_nonneg_right ?_ (Real.rpow_nonneg hε _)\n +            calc Real.rpow (2 * C₀) (1 / 4 : ℝ) ≤ Real.rpow (2 * C₀) 1 :=\n +                  Real.rpow_le_rpow_of_exponent_le (by linarith) (by norm_num)\n +              _ = 2 * C₀ := Real.rpow_one _\n +\n +end\n +\n +end MIPStarRE.QPBT\n++||||||| 1c5d5c16\n++=======\n+ import MIPStarRE.QPBT.Combining.Points.Orthonormalization\n+ \n+ /-!\n+ # Closeness estimates for the combined point measurements\n+ \n+ Given projective measurements `Q^{x,z}` on each player's expanded local space\n+ that are close to the sandwich POVMs on the placements where they were\n+ constructed, this file assembles the three conclusions of `lem:qld-4-10` on\n+ every pair of opposite placements by the triangle inequality along\n+ `Q ≈ R ≈ M^Z M^X ≈ M^X M^Z` and the cross-placement consistency of the\n+ ordered products.  It also records the trivial bound `4` on the state-dependent\n+ distance of two square-summable families, used when the test error exceeds\n+ one, and the elementary estimate collapsing the error terms `ε`, `√ε`, and\n+ `(ε + √ε)^{1/4}` into a single power `ε^{1/8}` when `ε ≤ 1`.\n+ \n+ ## References\n+ \n+ Paper `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:838-881`\n+ (self-consistency and consistency with `M̂` in the proof of `lem:qld-4-10`),\n+ blueprint `blueprint/src/chapter/ch15_qpbt_combining.tex:803-960`; the route\n+ is explained in `docs/paper-gaps/qpbt_combined-points-direct.tex`.\n+ -/\n+ \n+ open scoped BigOperators Matrix MatrixOrder ComplexOrder\n+ \n+ namespace MIPStarRE.QPBT\n+ \n+ open MIPStarRE.LDT hiding Measurement\n+ open MIPStarRE.Quantum DistanceCalculus\n+ \n+ noncomputable section\n+ \n+ /-! ## The trivial bound -/\n+ \n+ /-- A square-summable family of operators has total squared norm at most one on\n+ a unit vector. -/\n+ theorem sum_norm_apply_sq_le_one {α ι : Type*} [Fintype α] [Fintype ι]\n+     [DecidableEq ι] (A : α → Op ι) (ψ : EuclideanSpace ℂ ι) (hψ : ‖ψ‖ = 1)\n+     (hA : ∑ a, (A a)ᴴ * A a ≤ 1) :\n+     ∑ a, ‖applyOperatorToState (A a) ψ‖ ^ 2 ≤ 1 := by\n+   have h := sum_norm_mul_apply_le A 1 ψ hA\n+   simp only [mul_one, WinImplications.applyOperatorToState_one, hψ] at h\n+   simpa using h\n+ \n+ /-- The state-dependent distance of two square-summable families is at most\n+ `4` on a unit vector, under a uniform distribution. -/\n+ theorem opFamilyDistSq_uniform_le_four {X α ι : Type*} [Fintype X] [DecidableEq X]\n+     [Nonempty X] [Fintype α] [Fintype ι] [DecidableEq ι]\n+     (A B : X → α → Op ι) (ψ : EuclideanSpace ℂ ι) (hψ : ‖ψ‖ = 1)\n+     (hA : ∀ x, ∑ a, (A x a)ᴴ * A x a ≤ 1) (hB : ∀ x, ∑ a, (B x a)ᴴ * B x a ≤ 1) :\n+     opFamilyDistSq (uniformDistribution X) A B ψ ≤ 4 := by\n+   unfold opFamilyDistSq\n+   calc avgOver (uniformDistribution X) (fun x =>\n+         ∑ a, ‖applyOperatorToState (A x a - B x a) ψ‖ ^ 2)\n+       ≤ avgOver (uniformDistribution X) (fun _ => (4 : ℝ)) := by\n+         refine avgOver_mono _ _ _ fun x => ?_\n+         have hA' := sum_norm_apply_sq_le_one (A x) ψ hψ (hA x)\n+         have hB' := sum_norm_apply_sq_le_one (B x) ψ hψ (hB x)\n+         have hpt : ∀ a, ‖applyOperatorToState (A x a - B x a) ψ‖ ^ 2 ≤\n+             2 * ‖applyOperatorToState (A x a) ψ‖ ^ 2 +\n+               2 * ‖applyOperatorToState (B x a) ψ‖ ^ 2 := by\n+           intro a\n+           have hsub : applyOperatorToState (A x a - B x a) ψ =\n+               applyOperatorToState (A x a) ψ - applyOperatorToState (B x a) ψ := by\n+             simp [applyOperatorToState]\n+           rw [hsub]\n+           have := norm_sub_le (applyOperatorToState (A x a) ψ)\n+             (applyOperatorToState (B x a) ψ)\n+           nlinarith [norm_nonneg (applyOperatorToState (A x a) ψ),\n+             norm_nonneg (applyOperatorToState (B x a) ψ),\n+             norm_nonneg (applyOperatorToState (A x a) ψ -\n+               applyOperatorToState (B x a) ψ),\n+             sq_nonneg (‖applyOperatorToState (A x a) ψ‖ -\n+               ‖applyOperatorToState (B x a) ψ‖)]\n+         calc ∑ a, ‖applyOperatorToState (A x a - B x a) ψ‖ ^ 2\n+             ≤ ∑ a, (2 * ‖applyOperatorToState (A x a) ψ‖ ^ 2 +\n+                 2 * ‖applyOperatorToState (B x a) ψ‖ ^ 2) :=\n+               Finset.sum_le_sum fun a _ => hpt a\n+           _ = 2 * ∑ a, ‖applyOperatorToState (A x a) ψ‖ ^ 2 +\n+                 2 * ∑ a, ‖applyOperatorToState (B x a) ψ‖ ^ 2 := by\n+               rw [Finset.sum_add_distrib, Finset.mul_sum, Finset.mul_sum]\n+           _ ≤ 4 := by linarith\n+     _ = 4 := avgOver_uniform_const _\n+ \n+ /-- The effects of a projective measurement, placed on a register pair, are\n+ square-summable to the identity. -/\n+ theorem ProjectiveSetting.sum_place_effect_conjTranspose_mul_self_le_one\n+     {P : AdmissibleParams} {ε : ℝ} (S : ProjectiveSetting P ε) (p : Placement)\n+     {α : Type*} [Fintype α] (M : Measurement α (S.ExpandedLocalSpace p.side))\n+     (hM : MIPStarRE.QPBT.Measurement.IsProjective M) :\n+     ∑ a, (S.place p (M.effect a))ᴴ * S.place p (M.effect a) ≤ 1 := by\n+   refine le_of_eq ?_\n+   calc ∑ a, (S.place p (M.effect a))ᴴ * S.place p (M.effect a)\n+       = ∑ a, S.place p (M.effect a) := by\n+         refine Finset.sum_congr rfl fun a _ => ?_\n+         rw [← S.place_conjTranspose, ← S.place_mul,\n+           (hM a).isSelfAdjoint.isHermitian.eq, (hM a).isIdempotentElem.eq]\n+     _ = 1 := by rw [← S.place_finsetSum, M.sum_eq_one, S.place_one]\n+ \n+ /-- The products `A_a B_b` of the effects of two projective measurements on a\n+ common space are square-summable to the identity. -/\n+ theorem sum_mul_conjTranspose_mul_self_eq_one {α β ι : Type*} [Fintype α]\n+     [Fintype β] [Fintype ι] [DecidableEq ι]\n+     (A : Measurement α ι) (B : Measurement β ι)\n+     (hA : MIPStarRE.QPBT.Measurement.IsProjective A)\n+     (hB : MIPStarRE.QPBT.Measurement.IsProjective B) :\n+     ∑ ab : α × β, (A.effect ab.1 * B.effect ab.2)ᴴ * (A.effect ab.1 * B.effect ab.2) =\n+       1 := by\n+   have hpt : ∀ (a : α) (b : β),\n+       (A.effect a * B.effect b)ᴴ * (A.effect a * B.effect b) =\n+         B.effect b * A.effect a * B.effect b := by\n+     intro a b\n+     rw [Matrix.conjTranspose_mul, (hA a).isSelfAdjoint.isHermitian.eq,\n+       (hB b).isSelfAdjoint.isHermitian.eq, Matrix.mul_assoc _ _ (A.effect a * B.effect b),\n+       ← Matrix.mul_assoc (A.effect a) (A.effect a), (hA a).isIdempotentElem.eq,\n+       ← Matrix.mul_assoc]\n+   rw [Fintype.sum_prod_type_right]\n+   calc ∑ b : β, ∑ a : α, (A.effect a * B.effect b)ᴴ * (A.effect a * B.effect b)\n+       = ∑ b : β, B.effect b * (∑ a : α, A.effect a) * B.effect b := by\n+         refine Finset.sum_congr rfl fun b _ => ?_\n+         rw [Finset.mul_sum, Finset.sum_mul]\n+         exact Finset.sum_congr rfl fun a _ => hpt a b\n+     _ = 1 := by\n+         simp_rw [A.sum_eq_one, mul_one]\n+         rw [Finset.sum_congr rfl fun b _ => (hB b).isIdempotentElem.eq]\n+         exact B.sum_eq_one\n+ \n+ /-- The products `B_b A_a` of the effects of two projective measurements on a\n+ common space, indexed by the pair `(a, b)`, are square-summable to the\n+ identity. -/\n+ theorem sum_mul_conjTranspose_mul_self_eq_one' {α β ι : Type*} [Fintype α]\n+     [Fintype β] [Fintype ι] [DecidableEq ι]\n+     (A : Measurement α ι) (B : Measurement β ι)\n+     (hA : MIPStarRE.QPBT.Measurement.IsProjective A)\n+     (hB : MIPStarRE.QPBT.Measurement.IsProjective B) :\n+     ∑ ab : α × β, (B.effect ab.2 * A.effect ab.1)ᴴ * (B.effect ab.2 * A.effect ab.1) =\n+       1 := by\n+   have hpt : ∀ (a : α) (b : β),\n+       (B.effect b * A.effect a)ᴴ * (B.effect b * A.effect a) =\n+         A.effect a * B.effect b * A.effect a := by\n+     intro a b\n+     rw [Matrix.conjTranspose_mul, (hA a).isSelfAdjoint.isHermitian.eq,\n+       (hB b).isSelfAdjoint.isHermitian.eq, Matrix.mul_assoc _ _ (B.effect b * A.effect a),\n+       ← Matrix.mul_assoc (B.effect b) (B.effect b), (hB b).isIdempotentElem.eq,\n+       ← Matrix.mul_assoc]\n+   rw [Fintype.sum_prod_type]\n+   calc ∑ a : α, ∑ b : β, (B.effect b * A.effect a)ᴴ * (B.effect b * A.effect a)\n+       = ∑ a : α, A.effect a * (∑ b : β, B.effect b) * A.effect a := by\n+         refine Finset.sum_congr rfl fun a _ => ?_\n+         rw [Finset.mul_sum, Finset.sum_mul]\n+         exact Finset.sum_congr rfl fun b _ => hpt a b\n+     _ = 1 := by\n+         simp_rw [B.sum_eq_one, mul_one]\n+         rw [Finset.sum_congr rfl fun a _ => (hA a).isIdempotentElem.eq]\n+         exact A.sum_eq_one\n+ \n+ /-! ## The chain of closeness estimates -/\n+ \n+ namespace ProjectiveSetting\n+ \n+ variable {P : AdmissibleParams} {ε : ℝ}\n+ \n+ /-- The three closeness conclusions of `lem:qld-4-10` for a pair of projective\n+ families close to the placed sandwiches: with `η` the closeness of `Q` to `R`\n+ on every placement, `C₁ √ε` the closeness of `R` to the ordered product,\n+ `C₂ √ε` the commutation error, and `C₃ ε` the cross-placement consistency of\n+ the ordered products, the distances from `Q` on one placement to the two\n+ ordered products and to `Q` on the opposite placement are bounded by explicit\n+ combinations.  Paper\n+ `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:838-881`. -/\n+ theorem chain_bounds (S : ProjectiveSetting P ε)\n+     (Q : (side : PlayerSide) → PointPair P →\n+       Measurement (PauliScalar P × PauliScalar P) (S.ExpandedLocalSpace side))\n+     (η C₁ C₂ C₃ : ℝ)\n+     (hQR : ∀ p : Placement, opFamilyDistSq (uniformDistribution (PointPair P))\n+       (fun xz (ab : PauliScalar P × PauliScalar P) =>\n+         S.place p ((Q p.side xz).effect ab))\n+       (fun xz ab => S.place p ((S.sandwichPoint p.side xz.1 xz.2).effect ab))\n+       S.psiHat ≤ η)\n+     (h₁ : ∀ p : Placement, opFamilyDistSq (uniformDistribution (PointPair P))\n+       (fun xz (ab : PauliScalar P × PauliScalar P) =>\n+         S.place p ((S.sandwichPoint p.side xz.1 xz.2).effect ab))\n+       (fun xz ab => S.place p\n+         ((S.pointMeasExp p.side .Z xz.2).effect ab.2 *\n+           (S.pointMeasExp p.side .X xz.1).effect ab.1))\n+       S.psiHat ≤ C₁ * Real.sqrt ε)\n+     (h₂ : ∀ p : Placement, opFamilyDistSq (uniformDistribution (PointPair P))\n+       (fun xz (ab : PauliScalar P × PauliScalar P) => S.place p\n+         ((S.pointMeasExp p.side .X xz.1).effect ab.1 *\n+           (S.pointMeasExp p.side .Z xz.2).effect ab.2))\n+       (fun xz ab => S.place p\n+         ((S.pointMeasExp p.side .Z xz.2).effect ab.2 *\n+           (S.pointMeasExp p.side .X xz.1).effect ab.1))\n+       S.psiHat ≤ C₂ * Real.sqrt ε)\n+     (h₃ : ∀ p₁ p₂ : Placement, p₁.IsOpposite p₂ →\n+       opFamilyDistSq (uniformDistribution (PointPair P))\n+         (fun xz (ab : PauliScalar P × PauliScalar P) => S.place p₁\n+           ((S.pointMeasExp p₁.side .Z xz.2).effect ab.2 *\n+             (S.pointMeasExp p₁.side .X xz.1).effect ab.1))\n+         (fun xz ab => S.place p₂\n+           ((S.pointMeasExp p₂.side .X xz.1).effect ab.1 *\n+             (S.pointMeasExp p₂.side .Z xz.2).effect ab.2))\n+         S.psiHat ≤ C₃ * ε)\n+     (p₁ p₂ : Placement) (hopp : p₁.IsOpposite p₂) :\n+     opFamilyDistSq (uniformDistribution (PointPair P))\n+         (fun xz (ab : PauliScalar P × PauliScalar P) =>\n+           S.place p₁ ((Q p₁.side xz).effect ab))\n+         (fun xz ab => S.place p₂\n+           ((S.pointMeasExp p₂.side .X xz.1).effect ab.1 *\n+             (S.pointMeasExp p₂.side .Z xz.2).effect ab.2))\n+         S.psiHat ≤ 2 * η + 4 * (C₁ * Real.sqrt ε) + 4 * (C₃ * ε) ∧\n+       opFamilyDistSq (uniformDistribution (PointPair P))\n+         (fun xz (ab : PauliScalar P × PauliScalar P) =>\n+           S.place p₁ ((Q p₁.side xz).effect ab))\n+         (fun xz ab => S.place p₂\n+           ((S.pointMeasExp p₂.side .Z xz.2).effect ab.2 *\n+             (S.pointMeasExp p₂.side .X xz.1).effect ab.1))\n+         S.psiHat ≤ 4 * η + 8 * (C₁ * Real.sqrt ε) + 8 * (C₃ * ε) +\n+           2 * (C₂ * Real.sqrt ε) ∧\n+       opFamilyDistSq (uniformDistribution (PointPair P))\n+         (fun xz (ab : PauliScalar P × PauliScalar P) =>\n+           S.place p₁ ((Q p₁.side xz).effect ab))\n+         (fun xz ab => S.place p₂ ((Q p₂.side xz).effect ab))\n+         S.psiHat ≤ 12 * η + 20 * (C₁ * Real.sqrt ε) + 16 * (C₃ * ε) +\n+           4 * (C₂ * Real.sqrt ε) := by\n+   -- `R_1 ≈ M^X M^Z` on the opposite placement\n+   have hRXZ := opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P))\n+     _ _ _ S.psiHat _ _ (h₁ p₁) (h₃ p₁ p₂ hopp)\n+   -- `Q_1 ≈ M^X M^Z` on the opposite placement\n+   have hQXZ := opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P))\n+     _ _ _ S.psiHat _ _ (hQR p₁) hRXZ\n+   -- `Q_1 ≈ M^Z M^X` on the opposite placement\n+   have hQZX := opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P))\n+     _ _ _ S.psiHat _ _ hQXZ (h₂ p₂)\n+   -- `M^Z M^X ≈ Q_2` on the opposite placement\n+   have hZXQ : opFamilyDistSq (uniformDistribution (PointPair P))\n+       (fun xz (ab : PauliScalar P × PauliScalar P) => S.place p₂\n+         ((S.pointMeasExp p₂.side .Z xz.2).effect ab.2 *\n+           (S.pointMeasExp p₂.side .X xz.1).effect ab.1))\n+       (fun xz ab => S.place p₂ ((Q p₂.side xz).effect ab))\n+       S.psiHat ≤ 2 * η + 2 * (C₁ * Real.sqrt ε) := by\n+     rw [opFamilyDistSq_symm]\n+     exact opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P))\n+       _ _ _ S.psiHat _ _ (hQR p₂) (h₁ p₂)\n+   have hQQ := opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P))\n+     _ _ _ S.psiHat _ _ hQZX hZXQ\n+   refine ⟨by linarith, by linarith, by linarith⟩\n+ \n+ end ProjectiveSetting\n+ \n+ /-! ## Collapsing the error terms into one power -/\n+ \n+ /-- For `0 ≤ ε ≤ 1`, the error terms `ε`, `√ε`, and `(C₀ (ε + √ε))^{1/4}`\n+ with `C₀ ≥ 1` are all bounded by multiples of `ε^{1/8}`. -/\n+ theorem error_terms_le_rpow_eighth {ε C₀ : ℝ} (hε : 0 ≤ ε) (hε1 : ε ≤ 1)\n+     (hC₀ : 1 ≤ C₀) :\n+     ε ≤ Real.rpow ε (1 / 8 : ℝ) ∧ Real.sqrt ε ≤ Real.rpow ε (1 / 8 : ℝ) ∧\n+       Real.rpow (C₀ * (ε + Real.sqrt ε)) (1 / 4 : ℝ) ≤\n+         2 * C₀ * Real.rpow ε (1 / 8 : ℝ) := by\n+   rcases eq_or_lt_of_le hε with h0 | hpos\n+   · subst h0\n+     have h8 : Real.rpow (0 : ℝ) (1 / 8 : ℝ) = 0 := Real.zero_rpow (by norm_num)\n+     have h4 : Real.rpow (C₀ * (0 + Real.sqrt 0)) (1 / 4 : ℝ) = 0 := by\n+       rw [Real.sqrt_zero, add_zero, mul_zero]\n+       exact Real.zero_rpow (by norm_num)\n+     rw [h8, h4, Real.sqrt_zero]\n+     refine ⟨le_rfl, le_rfl, ?_⟩\n+     positivity\n+   · have hsqrt : Real.sqrt ε = Real.rpow ε (1 / 2 : ℝ) := Real.sqrt_eq_rpow ε\n+     have hε1' : Real.rpow ε 1 = ε := Real.rpow_one ε\n+     have hmono : ∀ y z : ℝ, z ≤ y → Real.rpow ε y ≤ Real.rpow ε z := fun y z hyz =>\n+       Real.rpow_le_rpow_of_exponent_ge hpos hε1 hyz\n+     refine ⟨?_, ?_, ?_⟩\n+     · exact le_of_eq_of_le hε1'.symm (hmono 1 (1 / 8) (by norm_num))\n+     · rw [hsqrt]\n+       exact hmono (1 / 2) (1 / 8) (by norm_num)\n+     · have hsum : ε + Real.sqrt ε ≤ 2 * Real.sqrt ε := by\n+         have : ε ≤ Real.sqrt ε := by\n+           rw [hsqrt]\n+           exact le_of_eq_of_le hε1'.symm (hmono 1 (1 / 2) (by norm_num))\n+         linarith\n+       have hC : 0 ≤ 2 * C₀ := by linarith\n+       calc Real.rpow (C₀ * (ε + Real.sqrt ε)) (1 / 4 : ℝ)\n+           ≤ Real.rpow (2 * C₀ * Real.sqrt ε) (1 / 4 : ℝ) := by\n+             apply Real.rpow_le_rpow (by positivity) _ (by norm_num)\n+             nlinarith [Real.sqrt_nonneg ε]\n+         _ = Real.rpow (2 * C₀) (1 / 4 : ℝ) * Real.rpow ε (1 / 8 : ℝ) := by\n+             change (2 * C₀ * Real.sqrt ε) ^ (1 / 4 : ℝ) =\n+               (2 * C₀) ^ (1 / 4 : ℝ) * ε ^ (1 / 8 : ℝ)\n+             rw [Real.mul_rpow hC (Real.sqrt_nonneg ε), Real.sqrt_eq_rpow,\n+               ← Real.rpow_mul hε]\n+             norm_num\n+         _ ≤ 2 * C₀ * Real.rpow ε (1 / 8 : ℝ) := by\n+             refine mul_le_mul_of_nonneg_right ?_ (Real.rpow_nonneg hε _)\n+             calc Real.rpow (2 * C₀) (1 / 4 : ℝ) ≤ Real.rpow (2 * C₀) 1 :=\n+                   Real.rpow_le_rpow_of_exponent_le (by linarith) (by norm_num)\n+               _ = 2 * C₀ := Real.rpow_one _\n+ \n+ end\n+ \n+ end MIPStarRE.QPBT\n++>>>>>>> github/main\ndiff --cc MIPStarRE/QPBT/Combining/Points/Commutation.lean\nindex 34a6bc7a,e0bc940b..00000000\n--- a/MIPStarRE/QPBT/Combining/Points/Commutation.lean\n+++ b/MIPStarRE/QPBT/Combining/Points/Commutation.lean\n@@@ -1,457 -1,457 +1,918 @@@\n++<<<<<<< HEAD\n +import MIPStarRE.QPBT.Combining.Points.Placement\n +\n +/-!\n +# Approximate commutation of the field-valued expanded point measurements\n +\n +The approximate commutation of `lem:qld-comm-cons` is stated for the binary\n +refinements `M^{(Point,W),u,r}_b` of the expanded point measurements.  The\n +combined point measurements of `lem:qld-4-10` are built here directly from the\n +`F_q`-valued measurements `M^{(Point,W),u}_a`, so the commutation estimate is\n +transferred to them.  The transfer is exact: since\n +`M^{(Point,X),x}_a = E_r (-1)^{tr(ar)} X^r(x)` and\n +`M^{(Point,Z),z}_b = E_s (-1)^{tr(bs)} Z^s(z)`, the commutator of the two\n +measurement effects is the Fourier transform, in the outcome pair `(a, b)`,\n +of the commutators of the expanded observables, and Parseval's identity for\n +the additive characters of `F_q` turns the sum over `(a, b)` of the squared\n +norms into the average over `(r, s)` of the squared norms of the observable\n +commutators.  No factor depending on `q` is lost.\n +\n +## Main results\n +\n +* `sum_norm_sum_smul_sq_of_orthogonal`: Parseval's identity for an orthogonal\n +  system of coefficients.\n +* `sum_fixedCharacter_mul`: Fourier cancellation for the fixed trace character.\n +* `expPoint_comm`: the field-valued expanded point measurements approximately\n +  commute on every register placement, with the error of\n +  `lem:qld-comm-cons`.\n +\n +## References\n +\n +The commutation estimate for the binary refinements is item 2 of\n +`lem:qld-comm-cons`, blueprint\n +`blueprint/src/chapter/ch14_qpbt_observables.tex:1139-1210`, paper\n +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:466-505`; the\n +Fourier form of the point effects is `def:expanded-point-measurement`, paper\n +lines 384--418.  The role of the transfer in the proof of `lem:qld-4-10` is\n +explained in `docs/paper-gaps/qpbt_linearity-theorem-quotation.tex`.\n +-/\n +\n +open scoped BigOperators Matrix MatrixOrder ComplexOrder\n +\n +namespace MIPStarRE.QPBT\n +\n +open MIPStarRE.LDT hiding Measurement\n +open MIPStarRE.Quantum\n +open MIPStarRE.LDT.Preliminaries\n +\n +noncomputable section\n +\n +/-- A pair of points, one for the `X` basis and one for the `Z` basis.  This\n +is the question pair `(x, z)` of `lem:qld-4-10`, paper\n +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:689-709`. -/\n +abbrev PointPair (P : AdmissibleParams) :=\n +  (Fin P.m → PauliScalar P) × (Fin P.m → PauliScalar P)\n +\n +/-! ## Parseval's identity for an orthogonal system of coefficients -/\n +\n +/-- Formalization-only auxiliary for `lem:qld-4-10`: if the coefficient\n +vectors `j ↦ c j i`, `i` ranging over a finite set, are orthogonal with common\n +squared norm `N`, then the squared norms of the weighted sums\n +`∑ i, c j i • v i` add up to `N` times the squared norms of the `v i`. -/\n +theorem sum_norm_sum_smul_sq_of_orthogonal {I J E : Type*} [Fintype I]\n +    [DecidableEq I] [Fintype J] [NormedAddCommGroup E] [InnerProductSpace ℂ E]\n +    (c : J → I → ℂ) (N : ℝ)\n +    (horth : ∀ i i', ∑ j, (starRingEnd ℂ) (c j i) * c j i' =\n +      if i = i' then (N : ℂ) else 0)\n +    (v : I → E) :\n +    ∑ j, ‖∑ i, c j i • v i‖ ^ 2 = N * ∑ i, ‖v i‖ ^ 2 := by\n +  have hnorm : ∀ x : E, ‖x‖ ^ 2 = (inner ℂ x x).re := fun x => by\n +    simpa using (inner_self_eq_norm_sq (𝕜 := ℂ) x).symm\n +  have hj : ∀ j, ‖∑ i, c j i • v i‖ ^ 2 =\n +      (∑ i, ∑ i', ((starRingEnd ℂ) (c j i) * c j i') *\n +        inner ℂ (v i) (v i')).re := by\n +    intro j\n +    rw [hnorm, sum_inner]\n +    simp only [inner_sum, inner_smul_left, inner_smul_right]\n +    congr 1\n +    refine Finset.sum_congr rfl fun i _ => Finset.sum_congr rfl fun i' _ => ?_\n +    ring\n +  have hsum : ∑ j, ∑ i, ∑ i', ((starRingEnd ℂ) (c j i) * c j i') *\n +      inner ℂ (v i) (v i') = ∑ i, (N : ℂ) * inner ℂ (v i) (v i) := by\n +    rw [Finset.sum_comm]\n +    refine Finset.sum_congr rfl fun i _ => ?_\n +    rw [Finset.sum_comm]\n +    calc ∑ i', ∑ j, ((starRingEnd ℂ) (c j i) * c j i') * inner ℂ (v i) (v i')\n +        = ∑ i', (∑ j, (starRingEnd ℂ) (c j i) * c j i') *\n +            inner ℂ (v i) (v i') := by\n +          refine Finset.sum_congr rfl fun i' _ => ?_\n +          rw [Finset.sum_mul]\n +      _ = ∑ i', (if i = i' then (N : ℂ) else 0) * inner ℂ (v i) (v i') := by\n +          refine Finset.sum_congr rfl fun i' _ => ?_\n +          rw [horth]\n +      _ = (N : ℂ) * inner ℂ (v i) (v i) := by\n +          simp [ite_mul]\n +  calc ∑ j, ‖∑ i, c j i • v i‖ ^ 2\n +      = (∑ j, ∑ i, ∑ i', ((starRingEnd ℂ) (c j i) * c j i') *\n +          inner ℂ (v i) (v i')).re := by\n +        rw [Complex.re_sum]\n +        exact Finset.sum_congr rfl fun j _ => hj j\n +    _ = (∑ i, (N : ℂ) * inner ℂ (v i) (v i)).re := by rw [hsum]\n +    _ = N * ∑ i, ‖v i‖ ^ 2 := by\n +        rw [Complex.re_sum, Finset.mul_sum]\n +        refine Finset.sum_congr rfl fun i _ => ?_\n +        rw [Complex.re_ofReal_mul, ← hnorm]\n +\n +/-! ## The fixed trace character -/\n +\n +section Characters\n +\n +variable {P : AdmissibleParams}\n +\n +/-- The phase induced by the fixed binary trace is an additive character.\n +Paper `references/qpbt-paper/04_preliminaries.tex:1052-1081`. -/\n +theorem fixedCharacter_mul (x y : PauliScalar P) :\n +    phaseSign (fixedBinTrace P.model x) * phaseSign (fixedBinTrace P.model y) =\n +      phaseSign (fixedBinTrace P.model (x + y)) := by\n +  rw [fixedBinTrace, map_add, phaseSign_eq_ffChar, phaseSign_eq_ffChar,\n +    phaseSign_eq_ffChar]\n +  exact ((ZMod.stdAddChar (N := 2)).map_add_eq_mul _ _).symm\n +\n +/-- The fixed trace character is even: negation acts trivially on the binary\n +trace. -/\n +theorem fixedCharacter_neg (x : PauliScalar P) :\n +    phaseSign (fixedBinTrace P.model (-x)) =\n +      phaseSign (fixedBinTrace P.model x) := by\n +  rw [fixedBinTrace, map_neg, ZMod.neg_eq_self_mod_two]\n +\n +/-- Fourier cancellation for the fixed trace character: the character sums to\n +the field size at `0` and to zero elsewhere.  This is `lem:cancellation` for\n +the one-dimensional space, blueprint\n +`blueprint/src/chapter/ch11_qpbt_algebra.tex:686`, paper\n +`references/qpbt-paper/04_preliminaries.tex:1124-1132`. -/\n +theorem sum_fixedCharacter_mul (c : PauliScalar P) :\n +    ∑ a : PauliScalar P, phaseSign (fixedBinTrace P.model (a * c)) =\n +      if c = 0 then (Fintype.card (PauliScalar P) : ℂ) else 0 := by\n +  have h : (𝔼 r : PauliScalar P, phaseSign (fixedBinTrace P.model (r * c))) =\n +      if c = 0 then (1 : ℂ) else 0 := by\n +    simpa only [fixedBinTrace, phaseSign_eq_ffChar,\n +      MIPStarRE.LDT.Preliminaries.ffChar_apply] using\n +      (fourier_fact_scalar (p := 2) (F := PauliScalar P) c)\n +  rw [Finset.expect_eq_sum_div_card] at h\n +  have hcard : (Fintype.card (PauliScalar P) : ℂ) ≠ 0 :=\n +    Nat.cast_ne_zero.mpr Fintype.card_ne_zero\n +  rw [Finset.card_univ, div_eq_iff hcard] at h\n +  rw [h]\n +  split_ifs <;> simp\n +\n +/-- Orthogonality of two fixed trace characters. -/\n +theorem sum_fixedCharacter_mul_fixedCharacter (r r' : PauliScalar P) :\n +    ∑ a : PauliScalar P, phaseSign (fixedBinTrace P.model (a * r)) *\n +        phaseSign (fixedBinTrace P.model (a * r')) =\n +      if r = r' then (Fintype.card (PauliScalar P) : ℂ) else 0 := by\n +  have hterm : ∀ a : PauliScalar P,\n +      phaseSign (fixedBinTrace P.model (a * r)) *\n +          phaseSign (fixedBinTrace P.model (a * r')) =\n +        phaseSign (fixedBinTrace P.model (a * (r' - r))) := by\n +    intro a\n +    rw [← fixedCharacter_neg (a * r), fixedCharacter_mul]\n +    congr 2\n +    ring\n +  simp_rw [hterm, sum_fixedCharacter_mul]\n +  by_cases h : r = r'\n +  · simp [h]\n +  · rw [if_neg h, if_neg]\n +    intro h'\n +    exact h (sub_eq_zero.mp h').symm\n +\n +/-- The two-dimensional character system `(a, b) ↦ χ(a r) χ(b s)` is orthogonal\n +with common squared norm `q ^ 2`. -/\n +theorem sum_pairCharacter_mul_pairCharacter\n +    (rs rs' : PauliScalar P × PauliScalar P) :\n +    ∑ ab : PauliScalar P × PauliScalar P,\n +        (starRingEnd ℂ) (phaseSign (fixedBinTrace P.model (ab.1 * rs.1)) *\n +            phaseSign (fixedBinTrace P.model (ab.2 * rs.2))) *\n +          (phaseSign (fixedBinTrace P.model (ab.1 * rs'.1)) *\n +            phaseSign (fixedBinTrace P.model (ab.2 * rs'.2))) =\n +      if rs = rs' then\n +        (((Fintype.card (PauliScalar P) : ℝ) ^ 2 : ℝ) : ℂ) else 0 := by\n +  have hstar : ∀ t : ZMod 2, (starRingEnd ℂ) (phaseSign t) = phaseSign t := by\n +    intro t\n +    rw [← Complex.star_def]\n +    exact star_phaseSign t\n +  simp_rw [map_mul, hstar]\n +  rw [Fintype.sum_prod_type]\n +  calc ∑ a : PauliScalar P, ∑ b : PauliScalar P,\n +        phaseSign (fixedBinTrace P.model (a * rs.1)) *\n +            phaseSign (fixedBinTrace P.model (b * rs.2)) *\n +          (phaseSign (fixedBinTrace P.model (a * rs'.1)) *\n +            phaseSign (fixedBinTrace P.model (b * rs'.2)))\n +      = (∑ a : PauliScalar P, phaseSign (fixedBinTrace P.model (a * rs.1)) *\n +            phaseSign (fixedBinTrace P.model (a * rs'.1))) *\n +          ∑ b : PauliScalar P, phaseSign (fixedBinTrace P.model (b * rs.2)) *\n +            phaseSign (fixedBinTrace P.model (b * rs'.2)) := by\n +        rw [Finset.sum_mul_sum]\n +        refine Finset.sum_congr rfl fun a _ => Finset.sum_congr rfl fun b _ => ?_\n +        ring\n +    _ = _ := by\n +        rw [sum_fixedCharacter_mul_fixedCharacter,\n +          sum_fixedCharacter_mul_fixedCharacter]\n +        by_cases h1 : rs.1 = rs'.1 <;> by_cases h2 : rs.2 = rs'.2\n +        · rw [if_pos h1, if_pos h2, if_pos (Prod.ext h1 h2)]\n +          push_cast\n +          ring\n +        · rw [if_pos h1, if_neg h2, if_neg (fun h => h2 (congrArg Prod.snd h))]\n +          simp\n +        · rw [if_neg h1, if_pos h2, if_neg (fun h => h1 (congrArg Prod.fst h))]\n +          simp\n +        · rw [if_neg h1, if_neg h2, if_neg (fun h => h1 (congrArg Prod.fst h))]\n +          simp\n +\n +end Characters\n +\n +/-! ## Fourier form of the point effects and of their commutator -/\n +\n +/-- A uniform operator average is the normalized sum. -/\n +theorem averageOperatorOverDistribution_uniform_eq_inv_card_smul_sum\n +    {α ι : Type*} [Fintype α] [DecidableEq α] [Nonempty α]\n +    [Fintype ι] [DecidableEq ι] (f : α → Op ι) :\n +    averageOperatorOverDistribution (uniformDistribution α) f =\n +      (Fintype.card α : ℂ)⁻¹ • ∑ a, f a := by\n +  ext i j\n +  simp only [averageOperatorOverDistribution, uniformDistribution,\n +    Distribution.uniformOnFinset, Finset.mem_univ, if_true, Matrix.sum_apply,\n +    Matrix.smul_apply, Complex.real_smul, smul_eq_mul,\n +    Finset.card_univ, one_div, Complex.ofReal_inv, Complex.ofReal_natCast]\n +  rw [Finset.mul_sum]\n +\n +namespace ProjectiveSetting\n +\n +variable {P : AdmissibleParams} {ε : ℝ}\n +\n +/-- The Fourier form of an expanded point effect as a normalized character\n +sum of the expanded observables.  This is the first display of\n +`def:expanded-point-measurement`, paper\n +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:384-418`. -/\n +theorem expPointOp_eq_inv_card_smul_sum (S : ProjectiveSetting P ε)\n +    (side : PlayerSide) (W : PauliKind) (u : Fin P.m → PauliScalar P)\n +    (a : PauliScalar P) :\n +    S.expPointOp side W u a =\n +      (Fintype.card (PauliScalar P) : ℂ)⁻¹ •\n +        ∑ r, phaseSign (fixedBinTrace P.model (a * r)) • S.expObs side W r u := by\n +  unfold expPointOp\n +  rw [averageOperatorOverDistribution_uniform_eq_inv_card_smul_sum]\n +\n +/-- Formalization-only auxiliary: the product of two normalized weighted sums\n +is the normalized double sum of the weighted products, indexed by pairs. -/\n +theorem smul_sum_mul_smul_sum {ι K : Type*} [Fintype K] [Fintype ι]\n +    (c : ℂ) (α β : K → ℂ) (X Z : K → Op ι) :\n +    (c • ∑ r, α r • X r) * (c • ∑ s, β s • Z s) =\n +      (c * c) • ∑ rs : K × K, (α rs.1 * β rs.2) • (X rs.1 * Z rs.2) := by\n +  rw [Fintype.sum_prod_type, smul_mul_smul_comm, Finset.sum_mul_sum]\n +  congr 1\n +  refine Finset.sum_congr rfl fun r _ => Finset.sum_congr rfl fun s _ => ?_\n +  rw [smul_mul_smul_comm]\n +\n +/-- Formalization-only auxiliary: the product of two normalized weighted sums\n +in the opposite order, indexed by the same pairs. -/\n +theorem smul_sum_mul_smul_sum_swap {ι K : Type*} [Fintype K] [Fintype ι]\n +    (c : ℂ) (α β : K → ℂ) (X Z : K → Op ι) :\n +    (c • ∑ s, β s • Z s) * (c • ∑ r, α r • X r) =\n +      (c * c) • ∑ rs : K × K, (α rs.1 * β rs.2) • (Z rs.2 * X rs.1) := by\n +  rw [Fintype.sum_prod_type_right, smul_mul_smul_comm, Finset.sum_mul_sum]\n +  congr 1\n +  refine Finset.sum_congr rfl fun s _ => Finset.sum_congr rfl fun r _ => ?_\n +  rw [smul_mul_smul_comm, mul_comm (β s)]\n +\n +/-- The commutator of two field-valued point effects is the Fourier transform\n +of the commutators of the expanded observables. -/\n +theorem expPointOp_commutator_eq (S : ProjectiveSetting P ε) (side : PlayerSide)\n +    (x z : Fin P.m → PauliScalar P) (a b : PauliScalar P) :\n +    S.expPointOp side .X x a * S.expPointOp side .Z z b -\n +        S.expPointOp side .Z z b * S.expPointOp side .X x a =\n +      ((Fintype.card (PauliScalar P) : ℂ)⁻¹ *\n +          (Fintype.card (PauliScalar P) : ℂ)⁻¹) •\n +        ∑ rs : PauliScalar P × PauliScalar P,\n +          (phaseSign (fixedBinTrace P.model (a * rs.1)) *\n +              phaseSign (fixedBinTrace P.model (b * rs.2))) •\n +            (S.expObs side .X rs.1 x * S.expObs side .Z rs.2 z -\n +              S.expObs side .Z rs.2 z * S.expObs side .X rs.1 x) := by\n +  rw [expPointOp_eq_inv_card_smul_sum, expPointOp_eq_inv_card_smul_sum,\n +    smul_sum_mul_smul_sum, smul_sum_mul_smul_sum_swap, ← smul_sub,\n +    ← Finset.sum_sub_distrib]\n +  congr 1\n +  refine Finset.sum_congr rfl fun rs _ => ?_\n +  rw [smul_sub]\n +\n +/-- Formalization-only auxiliary: an operator applied to a state is linear in\n +the operator over finite sums. -/\n +theorem applyOperatorToState_finsetSum {ι γ : Type*} [Fintype ι] [DecidableEq ι]\n +    (s : Finset γ) (M : γ → Op ι) (ψ : EuclideanSpace ℂ ι) :\n +    applyOperatorToState (∑ x ∈ s, M x) ψ =\n +      ∑ x ∈ s, applyOperatorToState (M x) ψ := by\n +  unfold applyOperatorToState\n +  simp only [map_sum, LinearMap.sum_apply]\n +\n +/-- Parseval transfer, pointwise in the point pair: the summed squared norms of\n +the placed commutators of the field-valued point effects equal the average over\n +`(r, s)` of the squared norms of the placed commutators of the expanded\n +observables. -/\n +theorem sum_norm_place_expPointOp_commutator_sq (S : ProjectiveSetting P ε)\n +    (p : Placement) (x z : Fin P.m → PauliScalar P) :\n +    ∑ ab : PauliScalar P × PauliScalar P,\n +        ‖applyOperatorToState (S.place p\n +          (S.expPointOp p.side .X x ab.1 * S.expPointOp p.side .Z z ab.2 -\n +            S.expPointOp p.side .Z z ab.2 * S.expPointOp p.side .X x ab.1))\n +          S.psiHat‖ ^ 2 =\n +      avgOver (uniformDistribution (PauliScalar P × PauliScalar P))\n +        (fun rs => ‖applyOperatorToState (S.place p\n +          (S.expObs p.side .X rs.1 x * S.expObs p.side .Z rs.2 z -\n +            S.expObs p.side .Z rs.2 z * S.expObs p.side .X rs.1 x))\n +          S.psiHat‖ ^ 2) := by\n +  set v : PauliScalar P × PauliScalar P →\n +      EuclideanSpace ℂ (SixReg P S.toStrategy.ιA S.toStrategy.ιB) :=\n +    fun rs => applyOperatorToState (S.place p\n +      (S.expObs p.side .X rs.1 x * S.expObs p.side .Z rs.2 z -\n +        S.expObs p.side .Z rs.2 z * S.expObs p.side .X rs.1 x)) S.psiHat\n +  set c : ℂ := (Fintype.card (PauliScalar P) : ℂ)⁻¹\n +  have hpt : ∀ ab : PauliScalar P × PauliScalar P,\n +      applyOperatorToState (S.place p\n +          (S.expPointOp p.side .X x ab.1 * S.expPointOp p.side .Z z ab.2 -\n +            S.expPointOp p.side .Z z ab.2 * S.expPointOp p.side .X x ab.1))\n +          S.psiHat =\n +        (c * c) • ∑ rs : PauliScalar P × PauliScalar P,\n +          (phaseSign (fixedBinTrace P.model (ab.1 * rs.1)) *\n +              phaseSign (fixedBinTrace P.model (ab.2 * rs.2))) • v rs := by\n +    intro ab\n +    rw [expPointOp_commutator_eq, place_smul, place_finsetSum,\n +      WinImplications.applyOperatorToState_smul_op, applyOperatorToState_finsetSum]\n +    congr 1\n +    refine Finset.sum_congr rfl fun rs _ => ?_\n +    rw [place_smul, WinImplications.applyOperatorToState_smul_op]\n +  have hparseval := sum_norm_sum_smul_sq_of_orthogonal\n +    (fun (ab rs : PauliScalar P × PauliScalar P) =>\n +      phaseSign (fixedBinTrace P.model (ab.1 * rs.1)) *\n +        phaseSign (fixedBinTrace P.model (ab.2 * rs.2)))\n +    ((Fintype.card (PauliScalar P) : ℝ) ^ 2)\n +    (fun rs rs' => sum_pairCharacter_mul_pairCharacter rs rs') v\n +  have hq : (0 : ℝ) < (Fintype.card (PauliScalar P) : ℝ) := by\n +    exact_mod_cast Fintype.card_pos\n +  have hcnorm : ‖c * c‖ = ((Fintype.card (PauliScalar P) : ℝ) ^ 2)⁻¹ := by\n +    simp only [c, norm_mul, norm_inv, Complex.norm_natCast]\n +    rw [sq, mul_inv]\n +  calc ∑ ab : PauliScalar P × PauliScalar P,\n +        ‖applyOperatorToState (S.place p\n +          (S.expPointOp p.side .X x ab.1 * S.expPointOp p.side .Z z ab.2 -\n +            S.expPointOp p.side .Z z ab.2 * S.expPointOp p.side .X x ab.1))\n +          S.psiHat‖ ^ 2\n +      = ∑ ab : PauliScalar P × PauliScalar P,\n +          ‖c * c‖ ^ 2 * ‖∑ rs : PauliScalar P × PauliScalar P,\n +            (phaseSign (fixedBinTrace P.model (ab.1 * rs.1)) *\n +              phaseSign (fixedBinTrace P.model (ab.2 * rs.2))) • v rs‖ ^ 2 := by\n +        refine Finset.sum_congr rfl fun ab _ => ?_\n +        rw [hpt, norm_smul, mul_pow]\n +    _ = ‖c * c‖ ^ 2 * (((Fintype.card (PauliScalar P) : ℝ) ^ 2) *\n +          ∑ rs, ‖v rs‖ ^ 2) := by\n +        rw [← Finset.mul_sum, hparseval]\n +    _ = avgOver (uniformDistribution (PauliScalar P × PauliScalar P))\n +          (fun rs => ‖v rs‖ ^ 2) := by\n +        rw [avgOver_uniform_eq_inv_card_mul_sum, Fintype.card_prod, hcnorm]\n +        push_cast\n +        field_simp\n +\n +/-- The field-valued expanded point measurements approximately commute on each\n +of the four register placements, with the error of item 2 of\n +`lem:qld-comm-cons`.  The estimate is transferred from the binary refinements\n +of the source by the Parseval identity, without loss in the field size.  Paper\n +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:466-505`,\n +blueprint `blueprint/src/chapter/ch14_qpbt_observables.tex:1139-1210`; the\n +role of this form in the proof of `lem:qld-4-10` is explained in\n +`docs/paper-gaps/qpbt_linearity-theorem-quotation.tex`. -/\n +theorem expPoint_comm :\n +    ∃ C : ℝ, 1 ≤ C ∧\n +      ∀ (P : AdmissibleParams) (ε : ℝ) (S : ProjectiveSetting P ε)\n +        (p : Placement),\n +        opFamilyDistSq (uniformDistribution (PointPair P))\n +          (fun xz (ab : PauliScalar P × PauliScalar P) => S.place p\n +            ((S.pointMeasExp p.side .X xz.1).effect ab.1 *\n +              (S.pointMeasExp p.side .Z xz.2).effect ab.2))\n +          (fun xz ab => S.place p\n +            ((S.pointMeasExp p.side .Z xz.2).effect ab.2 *\n +              (S.pointMeasExp p.side .X xz.1).effect ab.1))\n +          S.psiHat ≤ C * Real.sqrt ε := by\n +  obtain ⟨C, hC, h⟩ := exists_twistedCommutator_avg_le\n +  refine ⟨C, hC, ?_⟩\n +  intro P ε S p\n +  have hε : (0 : ℝ) ≤ ε := by\n +    have hv := WinImplications.strategy_value_le_one S.toStrategy\n +    have hw := S.win\n +    linarith\n +  have hnorm : ∀ (x z : Fin P.m → PauliScalar P)\n +      (rs : PauliScalar P × PauliScalar P),\n +      ‖applyOperatorToState (S.place p\n +          (S.expObs p.side .X rs.1 x * S.expObs p.side .Z rs.2 z -\n +            S.expObs p.side .Z rs.2 z * S.expObs p.side .X rs.1 x))\n +          S.psiHat‖ ^ 2 =\n +        ‖applyOperatorToState\n +          (S.placeStrategySide p.side (S.twistedCommutator p.side (x, z, rs.1, rs.2)))\n +          S.toStrategy.ψ‖ ^ 2 := by\n +    intro x z rs\n +    rw [expObs_commutator S p.side (x, z, rs.1, rs.2),\n +      norm_place_heteroKron_psiHat S p _ _ (tauX_mul_tauZ_isometry P (x, z, rs.1, rs.2))]\n +  have hfamily : opFamilyDistSq (uniformDistribution (PointPair P))\n +      (fun xz (ab : PauliScalar P × PauliScalar P) => S.place p\n +        ((S.pointMeasExp p.side .X xz.1).effect ab.1 *\n +          (S.pointMeasExp p.side .Z xz.2).effect ab.2))\n +      (fun xz ab => S.place p\n +        ((S.pointMeasExp p.side .Z xz.2).effect ab.2 *\n +          (S.pointMeasExp p.side .X xz.1).effect ab.1))\n +      S.psiHat =\n +      avgOver (uniformDistribution (PauliTuple P)) (fun ω =>\n +        ‖applyOperatorToState\n +          (S.placeStrategySide p.side (S.twistedCommutator p.side ω))\n +          S.toStrategy.ψ‖ ^ 2) := by\n +    unfold opFamilyDistSq\n +    calc avgOver (uniformDistribution (PointPair P)) (fun xz =>\n +          ∑ ab : PauliScalar P × PauliScalar P,\n +            ‖applyOperatorToState (S.place p\n +                ((S.pointMeasExp p.side .X xz.1).effect ab.1 *\n +                  (S.pointMeasExp p.side .Z xz.2).effect ab.2) -\n +              S.place p ((S.pointMeasExp p.side .Z xz.2).effect ab.2 *\n +                (S.pointMeasExp p.side .X xz.1).effect ab.1)) S.psiHat‖ ^ 2)\n +        = avgOver (uniformDistribution (PointPair P)) (fun xz =>\n +            avgOver (uniformDistribution (PauliScalar P × PauliScalar P))\n +              (fun rs => ‖applyOperatorToState\n +                (S.placeStrategySide p.side\n +                  (S.twistedCommutator p.side (xz.1, xz.2, rs.1, rs.2)))\n +                S.toStrategy.ψ‖ ^ 2)) := by\n +          refine avgOver_congr _ _ _ fun xz => ?_\n +          rw [← avgOver_congr _ _ _ (hnorm xz.1 xz.2),\n +            ← sum_norm_place_expPointOp_commutator_sq S p xz.1 xz.2]\n +          refine Finset.sum_congr rfl fun ab _ => ?_\n +          rw [place_sub]\n +          rfl\n +      _ = avgOver (uniformDistribution (PointPair P × (PauliScalar P × PauliScalar P)))\n +            (fun q => ‖applyOperatorToState\n +              (S.placeStrategySide p.side\n +                (S.twistedCommutator p.side (q.1.1, q.1.2, q.2.1, q.2.2)))\n +              S.toStrategy.ψ‖ ^ 2) :=\n +          (avgOver_uniform_prod (fun (xz : PointPair P)\n +            (rs : PauliScalar P × PauliScalar P) => ‖applyOperatorToState\n +              (S.placeStrategySide p.side\n +                (S.twistedCommutator p.side (xz.1, xz.2, rs.1, rs.2)))\n +              S.toStrategy.ψ‖ ^ 2)).symm\n +      _ = avgOver (uniformDistribution (PauliTuple P)) (fun ω =>\n +            ‖applyOperatorToState\n +              (S.placeStrategySide p.side (S.twistedCommutator p.side ω))\n +              S.toStrategy.ψ‖ ^ 2) := by\n +          rw [avgOver_uniform_equiv (Equiv.prodAssoc (Fin P.m → PauliScalar P)\n +            (Fin P.m → PauliScalar P) (PauliScalar P × PauliScalar P))]\n +          rfl\n +  rw [hfamily]\n +  exact h P ε S p.side hε\n +\n +end ProjectiveSetting\n +\n +end\n +\n +end MIPStarRE.QPBT\n++||||||| 1c5d5c16\n++=======\n+ import MIPStarRE.QPBT.Combining.Points.Placement\n+ \n+ /-!\n+ # Approximate commutation of the field-valued expanded point measurements\n+ \n+ The approximate commutation of `lem:qld-comm-cons` is stated for the binary\n+ refinements `M^{(Point,W),u,r}_b` of the expanded point measurements.  The\n+ combined point measurements of `lem:qld-4-10` are built here directly from the\n+ `F_q`-valued measurements `M^{(Point,W),u}_a`, so the commutation estimate is\n+ transferred to them.  The transfer is exact: since\n+ `M^{(Point,X),x}_a = E_r (-1)^{tr(ar)} X^r(x)` and\n+ `M^{(Point,Z),z}_b = E_s (-1)^{tr(bs)} Z^s(z)`, the commutator of the two\n+ measurement effects is the Fourier transform, in the outcome pair `(a, b)`,\n+ of the commutators of the expanded observables, and Parseval's identity for\n+ the additive characters of `F_q` turns the sum over `(a, b)` of the squared\n+ norms into the average over `(r, s)` of the squared norms of the observable\n+ commutators.  No factor depending on `q` is lost.\n+ \n+ ## Main results\n+ \n+ * `sum_norm_sum_smul_sq_of_orthogonal`: Parseval's identity for an orthogonal\n+   system of coefficients.\n+ * `sum_fixedCharacter_mul`: Fourier cancellation for the fixed trace character.\n+ * `expPoint_comm`: the field-valued expanded point measurements approximately\n+   commute on every register placement, with the error of\n+   `lem:qld-comm-cons`.\n+ \n+ ## References\n+ \n+ The commutation estimate for the binary refinements is item 2 of\n+ `lem:qld-comm-cons`, blueprint\n+ `blueprint/src/chapter/ch14_qpbt_observables.tex:1139-1210`, paper\n+ `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:466-505`; the\n+ Fourier form of the point effects is `def:expanded-point-measurement`, paper\n+ lines 384--418.  The role of the transfer in the proof of `lem:qld-4-10` is\n+ explained in `docs/paper-gaps/qpbt_combined-points-direct.tex`.\n+ -/\n+ \n+ open scoped BigOperators Matrix MatrixOrder ComplexOrder\n+ \n+ namespace MIPStarRE.QPBT\n+ \n+ open MIPStarRE.LDT hiding Measurement\n+ open MIPStarRE.Quantum\n+ open MIPStarRE.LDT.Preliminaries\n+ \n+ noncomputable section\n+ \n+ /-- A pair of points, one for the `X` basis and one for the `Z` basis.  This\n+ is the question pair `(x, z)` of `lem:qld-4-10`, paper\n+ `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:689-709`. -/\n+ abbrev PointPair (P : AdmissibleParams) :=\n+   (Fin P.m → PauliScalar P) × (Fin P.m → PauliScalar P)\n+ \n+ /-! ## Parseval's identity for an orthogonal system of coefficients -/\n+ \n+ /-- Formalization-only auxiliary for `lem:qld-4-10`: if the coefficient\n+ columns `j ↦ c j i`, indexed by `i`, are orthogonal with common\n+ squared norm `N`, then the squared norms of the weighted sums\n+ `∑ i, c j i • v i` add up to `N` times the squared norms of the `v i`. -/\n+ theorem sum_norm_sum_smul_sq_of_orthogonal {I J E : Type*} [Fintype I]\n+     [DecidableEq I] [Fintype J] [NormedAddCommGroup E] [InnerProductSpace ℂ E]\n+     (c : J → I → ℂ) (N : ℝ)\n+     (horth : ∀ i i', ∑ j, (starRingEnd ℂ) (c j i) * c j i' =\n+       if i = i' then (N : ℂ) else 0)\n+     (v : I → E) :\n+     ∑ j, ‖∑ i, c j i • v i‖ ^ 2 = N * ∑ i, ‖v i‖ ^ 2 := by\n+   have hnorm : ∀ x : E, ‖x‖ ^ 2 = (inner ℂ x x).re := fun x => by\n+     simpa using (inner_self_eq_norm_sq (𝕜 := ℂ) x).symm\n+   have hj : ∀ j, ‖∑ i, c j i • v i‖ ^ 2 =\n+       (∑ i, ∑ i', ((starRingEnd ℂ) (c j i) * c j i') *\n+         inner ℂ (v i) (v i')).re := by\n+     intro j\n+     rw [hnorm, sum_inner]\n+     simp only [inner_sum, inner_smul_left, inner_smul_right]\n+     congr 1\n+     refine Finset.sum_congr rfl fun i _ => Finset.sum_congr rfl fun i' _ => ?_\n+     ring\n+   have hsum : ∑ j, ∑ i, ∑ i', ((starRingEnd ℂ) (c j i) * c j i') *\n+       inner ℂ (v i) (v i') = ∑ i, (N : ℂ) * inner ℂ (v i) (v i) := by\n+     rw [Finset.sum_comm]\n+     refine Finset.sum_congr rfl fun i _ => ?_\n+     rw [Finset.sum_comm]\n+     calc ∑ i', ∑ j, ((starRingEnd ℂ) (c j i) * c j i') * inner ℂ (v i) (v i')\n+         = ∑ i', (∑ j, (starRingEnd ℂ) (c j i) * c j i') *\n+             inner ℂ (v i) (v i') := by\n+           refine Finset.sum_congr rfl fun i' _ => ?_\n+           rw [Finset.sum_mul]\n+       _ = ∑ i', (if i = i' then (N : ℂ) else 0) * inner ℂ (v i) (v i') := by\n+           refine Finset.sum_congr rfl fun i' _ => ?_\n+           rw [horth]\n+       _ = (N : ℂ) * inner ℂ (v i) (v i) := by\n+           simp [ite_mul]\n+   calc ∑ j, ‖∑ i, c j i • v i‖ ^ 2\n+       = (∑ j, ∑ i, ∑ i', ((starRingEnd ℂ) (c j i) * c j i') *\n+           inner ℂ (v i) (v i')).re := by\n+         rw [Complex.re_sum]\n+         exact Finset.sum_congr rfl fun j _ => hj j\n+     _ = (∑ i, (N : ℂ) * inner ℂ (v i) (v i)).re := by rw [hsum]\n+     _ = N * ∑ i, ‖v i‖ ^ 2 := by\n+         rw [Complex.re_sum, Finset.mul_sum]\n+         refine Finset.sum_congr rfl fun i _ => ?_\n+         rw [Complex.re_ofReal_mul, ← hnorm]\n+ \n+ /-! ## The fixed trace character -/\n+ \n+ section Characters\n+ \n+ variable {P : AdmissibleParams}\n+ \n+ /-- The phase induced by the fixed binary trace is an additive character.\n+ Paper `references/qpbt-paper/04_preliminaries.tex:1052-1081`. -/\n+ theorem fixedCharacter_mul (x y : PauliScalar P) :\n+     phaseSign (fixedBinTrace P.model x) * phaseSign (fixedBinTrace P.model y) =\n+       phaseSign (fixedBinTrace P.model (x + y)) := by\n+   rw [fixedBinTrace, map_add, phaseSign_eq_ffChar, phaseSign_eq_ffChar,\n+     phaseSign_eq_ffChar]\n+   exact ((ZMod.stdAddChar (N := 2)).map_add_eq_mul _ _).symm\n+ \n+ /-- The fixed trace character is even: negation acts trivially on the binary\n+ trace. -/\n+ theorem fixedCharacter_neg (x : PauliScalar P) :\n+     phaseSign (fixedBinTrace P.model (-x)) =\n+       phaseSign (fixedBinTrace P.model x) := by\n+   rw [fixedBinTrace, map_neg, ZMod.neg_eq_self_mod_two]\n+ \n+ /-- Fourier cancellation for the fixed trace character: the character sums to\n+ the field size at `0` and to zero elsewhere.  This is `lem:cancellation` for\n+ the one-dimensional space, blueprint\n+ `blueprint/src/chapter/ch11_qpbt_algebra.tex:686`, paper\n+ `references/qpbt-paper/04_preliminaries.tex:1124-1132`. -/\n+ theorem sum_fixedCharacter_mul (c : PauliScalar P) :\n+     ∑ a : PauliScalar P, phaseSign (fixedBinTrace P.model (a * c)) =\n+       if c = 0 then (Fintype.card (PauliScalar P) : ℂ) else 0 := by\n+   have h : (𝔼 r : PauliScalar P, phaseSign (fixedBinTrace P.model (r * c))) =\n+       if c = 0 then (1 : ℂ) else 0 := by\n+     simpa only [fixedBinTrace, phaseSign_eq_ffChar,\n+       MIPStarRE.LDT.Preliminaries.ffChar_apply] using\n+       (fourier_fact_scalar (p := 2) (F := PauliScalar P) c)\n+   rw [Finset.expect_eq_sum_div_card] at h\n+   have hcard : (Fintype.card (PauliScalar P) : ℂ) ≠ 0 :=\n+     Nat.cast_ne_zero.mpr Fintype.card_ne_zero\n+   rw [Finset.card_univ, div_eq_iff hcard] at h\n+   rw [h]\n+   split_ifs <;> simp\n+ \n+ /-- Orthogonality of two fixed trace characters. -/\n+ theorem sum_fixedCharacter_mul_fixedCharacter (r r' : PauliScalar P) :\n+     ∑ a : PauliScalar P, phaseSign (fixedBinTrace P.model (a * r)) *\n+         phaseSign (fixedBinTrace P.model (a * r')) =\n+       if r = r' then (Fintype.card (PauliScalar P) : ℂ) else 0 := by\n+   have hterm : ∀ a : PauliScalar P,\n+       phaseSign (fixedBinTrace P.model (a * r)) *\n+           phaseSign (fixedBinTrace P.model (a * r')) =\n+         phaseSign (fixedBinTrace P.model (a * (r' - r))) := by\n+     intro a\n+     rw [← fixedCharacter_neg (a * r), fixedCharacter_mul]\n+     congr 2\n+     ring\n+   simp_rw [hterm, sum_fixedCharacter_mul]\n+   by_cases h : r = r'\n+   · simp [h]\n+   · rw [if_neg h, if_neg]\n+     intro h'\n+     exact h (sub_eq_zero.mp h').symm\n+ \n+ /-- The two-dimensional character system `(a, b) ↦ χ(a r) χ(b s)` is orthogonal\n+ with common squared norm `q ^ 2`. -/\n+ theorem sum_pairCharacter_mul_pairCharacter\n+     (rs rs' : PauliScalar P × PauliScalar P) :\n+     ∑ ab : PauliScalar P × PauliScalar P,\n+         (starRingEnd ℂ) (phaseSign (fixedBinTrace P.model (ab.1 * rs.1)) *\n+             phaseSign (fixedBinTrace P.model (ab.2 * rs.2))) *\n+           (phaseSign (fixedBinTrace P.model (ab.1 * rs'.1)) *\n+             phaseSign (fixedBinTrace P.model (ab.2 * rs'.2))) =\n+       if rs = rs' then\n+         (((Fintype.card (PauliScalar P) : ℝ) ^ 2 : ℝ) : ℂ) else 0 := by\n+   have hstar : ∀ t : ZMod 2, (starRingEnd ℂ) (phaseSign t) = phaseSign t := by\n+     intro t\n+     rw [← Complex.star_def]\n+     exact star_phaseSign t\n+   simp_rw [map_mul, hstar]\n+   rw [Fintype.sum_prod_type]\n+   calc ∑ a : PauliScalar P, ∑ b : PauliScalar P,\n+         phaseSign (fixedBinTrace P.model (a * rs.1)) *\n+             phaseSign (fixedBinTrace P.model (b * rs.2)) *\n+           (phaseSign (fixedBinTrace P.model (a * rs'.1)) *\n+             phaseSign (fixedBinTrace P.model (b * rs'.2)))\n+       = (∑ a : PauliScalar P, phaseSign (fixedBinTrace P.model (a * rs.1)) *\n+             phaseSign (fixedBinTrace P.model (a * rs'.1))) *\n+           ∑ b : PauliScalar P, phaseSign (fixedBinTrace P.model (b * rs.2)) *\n+             phaseSign (fixedBinTrace P.model (b * rs'.2)) := by\n+         rw [Finset.sum_mul_sum]\n+         refine Finset.sum_congr rfl fun a _ => Finset.sum_congr rfl fun b _ => ?_\n+         ring\n+     _ = _ := by\n+         rw [sum_fixedCharacter_mul_fixedCharacter,\n+           sum_fixedCharacter_mul_fixedCharacter]\n+         by_cases h1 : rs.1 = rs'.1 <;> by_cases h2 : rs.2 = rs'.2\n+         · rw [if_pos h1, if_pos h2, if_pos (Prod.ext h1 h2)]\n+           push_cast\n+           ring\n+         · rw [if_pos h1, if_neg h2, if_neg (fun h => h2 (congrArg Prod.snd h))]\n+           simp\n+         · rw [if_neg h1, if_pos h2, if_neg (fun h => h1 (congrArg Prod.fst h))]\n+           simp\n+         · rw [if_neg h1, if_neg h2, if_neg (fun h => h1 (congrArg Prod.fst h))]\n+           simp\n+ \n+ end Characters\n+ \n+ /-! ## Fourier form of the point effects and of their commutator -/\n+ \n+ /-- A uniform operator average is the normalized sum. -/\n+ theorem averageOperatorOverDistribution_uniform_eq_inv_card_smul_sum\n+     {α ι : Type*} [Fintype α] [DecidableEq α] [Nonempty α]\n+     [Fintype ι] [DecidableEq ι] (f : α → Op ι) :\n+     averageOperatorOverDistribution (uniformDistribution α) f =\n+       (Fintype.card α : ℂ)⁻¹ • ∑ a, f a := by\n+   ext i j\n+   simp only [averageOperatorOverDistribution, uniformDistribution,\n+     Distribution.uniformOnFinset, Finset.mem_univ, if_true, Matrix.sum_apply,\n+     Matrix.smul_apply, Complex.real_smul, smul_eq_mul,\n+     Finset.card_univ, one_div, Complex.ofReal_inv, Complex.ofReal_natCast]\n+   rw [Finset.mul_sum]\n+ \n+ namespace ProjectiveSetting\n+ \n+ variable {P : AdmissibleParams} {ε : ℝ}\n+ \n+ /-- The Fourier form of an expanded point effect as a normalized character\n+ sum of the expanded observables.  This is the first display of\n+ `def:expanded-point-measurement`, paper\n+ `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:384-418`. -/\n+ theorem expPointOp_eq_inv_card_smul_sum (S : ProjectiveSetting P ε)\n+     (side : PlayerSide) (W : PauliKind) (u : Fin P.m → PauliScalar P)\n+     (a : PauliScalar P) :\n+     S.expPointOp side W u a =\n+       (Fintype.card (PauliScalar P) : ℂ)⁻¹ •\n+         ∑ r, phaseSign (fixedBinTrace P.model (a * r)) • S.expObs side W r u := by\n+   unfold expPointOp\n+   rw [averageOperatorOverDistribution_uniform_eq_inv_card_smul_sum]\n+ \n+ /-- Formalization-only auxiliary: the product of two normalized weighted sums\n+ is the normalized double sum of the weighted products, indexed by pairs. -/\n+ theorem smul_sum_mul_smul_sum {ι K : Type*} [Fintype K] [Fintype ι]\n+     (c : ℂ) (α β : K → ℂ) (X Z : K → Op ι) :\n+     (c • ∑ r, α r • X r) * (c • ∑ s, β s • Z s) =\n+       (c * c) • ∑ rs : K × K, (α rs.1 * β rs.2) • (X rs.1 * Z rs.2) := by\n+   rw [Fintype.sum_prod_type, smul_mul_smul_comm, Finset.sum_mul_sum]\n+   congr 1\n+   refine Finset.sum_congr rfl fun r _ => Finset.sum_congr rfl fun s _ => ?_\n+   rw [smul_mul_smul_comm]\n+ \n+ /-- Formalization-only auxiliary: the product of two normalized weighted sums\n+ in the opposite order, indexed by the same pairs. -/\n+ theorem smul_sum_mul_smul_sum_swap {ι K : Type*} [Fintype K] [Fintype ι]\n+     (c : ℂ) (α β : K → ℂ) (X Z : K → Op ι) :\n+     (c • ∑ s, β s • Z s) * (c • ∑ r, α r • X r) =\n+       (c * c) • ∑ rs : K × K, (α rs.1 * β rs.2) • (Z rs.2 * X rs.1) := by\n+   rw [Fintype.sum_prod_type_right, smul_mul_smul_comm, Finset.sum_mul_sum]\n+   congr 1\n+   refine Finset.sum_congr rfl fun s _ => Finset.sum_congr rfl fun r _ => ?_\n+   rw [smul_mul_smul_comm, mul_comm (β s)]\n+ \n+ /-- The commutator of two field-valued point effects is the Fourier transform\n+ of the commutators of the expanded observables. -/\n+ theorem expPointOp_commutator_eq (S : ProjectiveSetting P ε) (side : PlayerSide)\n+     (x z : Fin P.m → PauliScalar P) (a b : PauliScalar P) :\n+     S.expPointOp side .X x a * S.expPointOp side .Z z b -\n+         S.expPointOp side .Z z b * S.expPointOp side .X x a =\n+       ((Fintype.card (PauliScalar P) : ℂ)⁻¹ *\n+           (Fintype.card (PauliScalar P) : ℂ)⁻¹) •\n+         ∑ rs : PauliScalar P × PauliScalar P,\n+           (phaseSign (fixedBinTrace P.model (a * rs.1)) *\n+               phaseSign (fixedBinTrace P.model (b * rs.2))) •\n+             (S.expObs side .X rs.1 x * S.expObs side .Z rs.2 z -\n+               S.expObs side .Z rs.2 z * S.expObs side .X rs.1 x) := by\n+   rw [expPointOp_eq_inv_card_smul_sum, expPointOp_eq_inv_card_smul_sum,\n+     smul_sum_mul_smul_sum, smul_sum_mul_smul_sum_swap, ← smul_sub,\n+     ← Finset.sum_sub_distrib]\n+   congr 1\n+   refine Finset.sum_congr rfl fun rs _ => ?_\n+   rw [smul_sub]\n+ \n+ /-- Formalization-only auxiliary: an operator applied to a state is linear in\n+ the operator over finite sums. -/\n+ theorem applyOperatorToState_finsetSum {ι γ : Type*} [Fintype ι] [DecidableEq ι]\n+     (s : Finset γ) (M : γ → Op ι) (ψ : EuclideanSpace ℂ ι) :\n+     applyOperatorToState (∑ x ∈ s, M x) ψ =\n+       ∑ x ∈ s, applyOperatorToState (M x) ψ := by\n+   unfold applyOperatorToState\n+   simp only [map_sum, LinearMap.sum_apply]\n+ \n+ /-- Parseval transfer, pointwise in the point pair: the summed squared norms of\n+ the placed commutators of the field-valued point effects equal the average over\n+ `(r, s)` of the squared norms of the placed commutators of the expanded\n+ observables. -/\n+ theorem sum_norm_place_expPointOp_commutator_sq (S : ProjectiveSetting P ε)\n+     (p : Placement) (x z : Fin P.m → PauliScalar P) :\n+     ∑ ab : PauliScalar P × PauliScalar P,\n+         ‖applyOperatorToState (S.place p\n+           (S.expPointOp p.side .X x ab.1 * S.expPointOp p.side .Z z ab.2 -\n+             S.expPointOp p.side .Z z ab.2 * S.expPointOp p.side .X x ab.1))\n+           S.psiHat‖ ^ 2 =\n+       avgOver (uniformDistribution (PauliScalar P × PauliScalar P))\n+         (fun rs => ‖applyOperatorToState (S.place p\n+           (S.expObs p.side .X rs.1 x * S.expObs p.side .Z rs.2 z -\n+             S.expObs p.side .Z rs.2 z * S.expObs p.side .X rs.1 x))\n+           S.psiHat‖ ^ 2) := by\n+   set v : PauliScalar P × PauliScalar P →\n+       EuclideanSpace ℂ (SixReg P S.toStrategy.ιA S.toStrategy.ιB) :=\n+     fun rs => applyOperatorToState (S.place p\n+       (S.expObs p.side .X rs.1 x * S.expObs p.side .Z rs.2 z -\n+         S.expObs p.side .Z rs.2 z * S.expObs p.side .X rs.1 x)) S.psiHat\n+   set c : ℂ := (Fintype.card (PauliScalar P) : ℂ)⁻¹\n+   have hpt : ∀ ab : PauliScalar P × PauliScalar P,\n+       applyOperatorToState (S.place p\n+           (S.expPointOp p.side .X x ab.1 * S.expPointOp p.side .Z z ab.2 -\n+             S.expPointOp p.side .Z z ab.2 * S.expPointOp p.side .X x ab.1))\n+           S.psiHat =\n+         (c * c) • ∑ rs : PauliScalar P × PauliScalar P,\n+           (phaseSign (fixedBinTrace P.model (ab.1 * rs.1)) *\n+               phaseSign (fixedBinTrace P.model (ab.2 * rs.2))) • v rs := by\n+     intro ab\n+     rw [expPointOp_commutator_eq, place_smul, place_finsetSum,\n+       WinImplications.applyOperatorToState_smul_op, applyOperatorToState_finsetSum]\n+     congr 1\n+     refine Finset.sum_congr rfl fun rs _ => ?_\n+     rw [place_smul, WinImplications.applyOperatorToState_smul_op]\n+   have hparseval := sum_norm_sum_smul_sq_of_orthogonal\n+     (fun (ab rs : PauliScalar P × PauliScalar P) =>\n+       phaseSign (fixedBinTrace P.model (ab.1 * rs.1)) *\n+         phaseSign (fixedBinTrace P.model (ab.2 * rs.2)))\n+     ((Fintype.card (PauliScalar P) : ℝ) ^ 2)\n+     (fun rs rs' => sum_pairCharacter_mul_pairCharacter rs rs') v\n+   have hq : (0 : ℝ) < (Fintype.card (PauliScalar P) : ℝ) := by\n+     exact_mod_cast Fintype.card_pos\n+   have hcnorm : ‖c * c‖ = ((Fintype.card (PauliScalar P) : ℝ) ^ 2)⁻¹ := by\n+     simp only [c, norm_mul, norm_inv, Complex.norm_natCast]\n+     rw [sq, mul_inv]\n+   calc ∑ ab : PauliScalar P × PauliScalar P,\n+         ‖applyOperatorToState (S.place p\n+           (S.expPointOp p.side .X x ab.1 * S.expPointOp p.side .Z z ab.2 -\n+             S.expPointOp p.side .Z z ab.2 * S.expPointOp p.side .X x ab.1))\n+           S.psiHat‖ ^ 2\n+       = ∑ ab : PauliScalar P × PauliScalar P,\n+           ‖c * c‖ ^ 2 * ‖∑ rs : PauliScalar P × PauliScalar P,\n+             (phaseSign (fixedBinTrace P.model (ab.1 * rs.1)) *\n+               phaseSign (fixedBinTrace P.model (ab.2 * rs.2))) • v rs‖ ^ 2 := by\n+         refine Finset.sum_congr rfl fun ab _ => ?_\n+         rw [hpt, norm_smul, mul_pow]\n+     _ = ‖c * c‖ ^ 2 * (((Fintype.card (PauliScalar P) : ℝ) ^ 2) *\n+           ∑ rs, ‖v rs‖ ^ 2) := by\n+         rw [← Finset.mul_sum, hparseval]\n+     _ = avgOver (uniformDistribution (PauliScalar P × PauliScalar P))\n+           (fun rs => ‖v rs‖ ^ 2) := by\n+         rw [avgOver_uniform_eq_inv_card_mul_sum, Fintype.card_prod, hcnorm]\n+         push_cast\n+         field_simp\n+ \n+ /-- The field-valued expanded point measurements approximately commute on each\n+ of the four register placements, with the error of item 2 of\n+ `lem:qld-comm-cons`.  The estimate is transferred from the binary refinements\n+ of the source by the Parseval identity, without loss in the field size.  Paper\n+ `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:466-505`,\n+ blueprint `blueprint/src/chapter/ch14_qpbt_observables.tex:1139-1210`; the\n+ role of this form in the proof of `lem:qld-4-10` is explained in\n+ `docs/paper-gaps/qpbt_combined-points-direct.tex`. -/\n+ theorem expPoint_comm :\n+     ∃ C : ℝ, 1 ≤ C ∧\n+       ∀ (P : AdmissibleParams) (ε : ℝ) (S : ProjectiveSetting P ε)\n+         (p : Placement),\n+         opFamilyDistSq (uniformDistribution (PointPair P))\n+           (fun xz (ab : PauliScalar P × PauliScalar P) => S.place p\n+             ((S.pointMeasExp p.side .X xz.1).effect ab.1 *\n+               (S.pointMeasExp p.side .Z xz.2).effect ab.2))\n+           (fun xz ab => S.place p\n+             ((S.pointMeasExp p.side .Z xz.2).effect ab.2 *\n+               (S.pointMeasExp p.side .X xz.1).effect ab.1))\n+           S.psiHat ≤ C * Real.sqrt ε := by\n+   obtain ⟨C, hC, h⟩ := exists_twistedCommutator_avg_le\n+   refine ⟨C, hC, ?_⟩\n+   intro P ε S p\n+   have hε : (0 : ℝ) ≤ ε := by\n+     have hv := WinImplications.strategy_value_le_one S.toStrategy\n+     have hw := S.win\n+     linarith\n+   have hnorm : ∀ (x z : Fin P.m → PauliScalar P)\n+       (rs : PauliScalar P × PauliScalar P),\n+       ‖applyOperatorToState (S.place p\n+           (S.expObs p.side .X rs.1 x * S.expObs p.side .Z rs.2 z -\n+             S.expObs p.side .Z rs.2 z * S.expObs p.side .X rs.1 x))\n+           S.psiHat‖ ^ 2 =\n+         ‖applyOperatorToState\n+           (S.placeStrategySide p.side (S.twistedCommutator p.side (x, z, rs.1, rs.2)))\n+           S.toStrategy.ψ‖ ^ 2 := by\n+     intro x z rs\n+     rw [expObs_commutator S p.side (x, z, rs.1, rs.2),\n+       norm_place_heteroKron_psiHat S p _ _ (tauX_mul_tauZ_isometry P (x, z, rs.1, rs.2))]\n+   have hfamily : opFamilyDistSq (uniformDistribution (PointPair P))\n+       (fun xz (ab : PauliScalar P × PauliScalar P) => S.place p\n+         ((S.pointMeasExp p.side .X xz.1).effect ab.1 *\n+           (S.pointMeasExp p.side .Z xz.2).effect ab.2))\n+       (fun xz ab => S.place p\n+         ((S.pointMeasExp p.side .Z xz.2).effect ab.2 *\n+           (S.pointMeasExp p.side .X xz.1).effect ab.1))\n+       S.psiHat =\n+       avgOver (uniformDistribution (PauliTuple P)) (fun ω =>\n+         ‖applyOperatorToState\n+           (S.placeStrategySide p.side (S.twistedCommutator p.side ω))\n+           S.toStrategy.ψ‖ ^ 2) := by\n+     unfold opFamilyDistSq\n+     calc avgOver (uniformDistribution (PointPair P)) (fun xz =>\n+           ∑ ab : PauliScalar P × PauliScalar P,\n+             ‖applyOperatorToState (S.place p\n+                 ((S.pointMeasExp p.side .X xz.1).effect ab.1 *\n+                   (S.pointMeasExp p.side .Z xz.2).effect ab.2) -\n+               S.place p ((S.pointMeasExp p.side .Z xz.2).effect ab.2 *\n+                 (S.pointMeasExp p.side .X xz.1).effect ab.1)) S.psiHat‖ ^ 2)\n+         = avgOver (uniformDistribution (PointPair P)) (fun xz =>\n+             avgOver (uniformDistribution (PauliScalar P × PauliScalar P))\n+               (fun rs => ‖applyOperatorToState\n+                 (S.placeStrategySide p.side\n+                   (S.twistedCommutator p.side (xz.1, xz.2, rs.1, rs.2)))\n+                 S.toStrategy.ψ‖ ^ 2)) := by\n+           refine avgOver_congr _ _ _ fun xz => ?_\n+           rw [← avgOver_congr _ _ _ (hnorm xz.1 xz.2),\n+             ← sum_norm_place_expPointOp_commutator_sq S p xz.1 xz.2]\n+           refine Finset.sum_congr rfl fun ab _ => ?_\n+           rw [place_sub]\n+           rfl\n+       _ = avgOver (uniformDistribution (PointPair P × (PauliScalar P × PauliScalar P)))\n+             (fun q => ‖applyOperatorToState\n+               (S.placeStrategySide p.side\n+                 (S.twistedCommutator p.side (q.1.1, q.1.2, q.2.1, q.2.2)))\n+               S.toStrategy.ψ‖ ^ 2) :=\n+           (avgOver_uniform_prod (fun (xz : PointPair P)\n+             (rs : PauliScalar P × PauliScalar P) => ‖applyOperatorToState\n+               (S.placeStrategySide p.side\n+                 (S.twistedCommutator p.side (xz.1, xz.2, rs.1, rs.2)))\n+               S.toStrategy.ψ‖ ^ 2)).symm\n+       _ = avgOver (uniformDistribution (PauliTuple P)) (fun ω =>\n+             ‖applyOperatorToState\n+               (S.placeStrategySide p.side (S.twistedCommutator p.side ω))\n+               S.toStrategy.ψ‖ ^ 2) := by\n+           rw [avgOver_uniform_equiv (Equiv.prodAssoc (Fin P.m → PauliScalar P)\n+             (Fin P.m → PauliScalar P) (PauliScalar P × PauliScalar P))]\n+           rfl\n+   rw [hfamily]\n+   exact h P ε S p.side hε\n+ \n+ end ProjectiveSetting\n+ \n+ end\n+ \n+ end MIPStarRE.QPBT\n++>>>>>>> github/main\ndiff --cc MIPStarRE/QPBT/Combining/Points/Consistency.lean\nindex 46bfa321,b4e99d17..00000000\n--- a/MIPStarRE/QPBT/Combining/Points/Consistency.lean\n+++ b/MIPStarRE/QPBT/Combining/Points/Consistency.lean\n@@@ -1,428 -1,428 +1,860 @@@\n++<<<<<<< HEAD\n +import MIPStarRE.QPBT.Combining.Points.Sandwich\n +\n +/-!\n +# Self-consistency of the sandwich POVM\n +\n +The sandwich POVM `R^{x,z}_{a,b} = M^Z_b M^X_a M^Z_b` of\n +`MIPStarRE/QPBT/Combining/Points/Sandwich.lean` is approximately self-consistent\n +between opposite register placements.  The source establishes this by a\n +Cauchy--Schwarz chain (displays `eq:qld-rw-self-cons-1` to\n +`eq:qld-rw-self-cons-4`); here an exact identity is used instead.  Writing\n +`P_1, P_2` for the two placements of an operator `P`,\n +`W_b = (M^Z_b)_1 (M^Z_b)_2`, and `D^W_c = (M^W_c)_1 - (M^W_c)_2`, the\n +consistency defect of the two placed sandwiches equals\n +`(1/2) ∑_b ‖D^Z_b ψ‖^2 + (1/2) ∑_{a,b} ‖D^X_a W_b ψ‖^2`,\n +by two applications of the identity\n +`∑_c ⟨w, P_c Q_c w⟩ = ‖w‖^2 - (1/2) ∑_c ‖(P_c - Q_c) w‖^2` for projective\n +measurements.  The second sum is then bounded by the self-consistency of `M^X`\n +and the commutators on the two placements, since\n +`D^X_a W_b = W_b D^X_a + (M^Z_b)_2 K^1_{a,b} - (M^Z_b)_1 K^2_{a,b}`, where\n +`K^i_{a,b}` is the placed commutator of `M^X_a` and `M^Z_b`.\n +\n +## Main results\n +\n +* `sandwich_overlap_identity`: the exact expression of the overlap of two\n +  placed sandwiches.\n +* `sandwich_defect_pointwise_le`: the pointwise bound on the consistency\n +  defect of the sandwich for a fixed point pair.\n +* `ProjectiveSetting.sandwichDefectBound`,\n +  `ProjectiveSetting.sandwich_offDiagonal_le_sandwichDefectBound`, and\n +  `ProjectiveSetting.avg_sandwichDefectBound_le`: the bound as a function of\n +  the point pair, the pointwise estimate, and the average.\n +\n +## References\n +\n +Paper `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:743-790`,\n +blueprint `blueprint/src/chapter/ch15_qpbt_combining.tex:851-880`\n +(`lem:qld-4-10`, first step); the identity route is explained in\n +`docs/paper-gaps/qpbt_linearity-theorem-quotation.tex`.\n +-/\n +\n +open scoped BigOperators Matrix MatrixOrder ComplexOrder\n +\n +namespace MIPStarRE.QPBT\n +\n +open MIPStarRE.LDT hiding Measurement\n +open MIPStarRE.Quantum DistanceCalculus\n +\n +noncomputable section\n +\n +/-! ## Quadratic-form identities -/\n +\n +/-- The quadratic form of `Wᴴ M W` in `ψ` is the quadratic form of `M` in\n +`W ψ`. -/\n +theorem stateQForm_conjTranspose_mul_mul {ι : Type*} [Fintype ι] [DecidableEq ι]\n +    (ψ : EuclideanSpace ℂ ι) (W M : Op ι) :\n +    stateQForm ψ (Wᴴ * M * W) = stateQForm (applyOperatorToState W ψ) M := by\n +  unfold stateQForm\n +  rw [DistanceCalculus.applyOperatorToState_mul, DistanceCalculus.applyOperatorToState_mul]\n +  congr 1\n +  change inner ℂ ψ (Matrix.toEuclideanLin Wᴴ _) =\n +    inner ℂ (Matrix.toEuclideanLin W ψ) _\n +  rw [Matrix.toEuclideanLin_conjTranspose_eq_adjoint, LinearMap.adjoint_inner_right]\n +\n +/-- The squared norm of `W ψ` is the quadratic form of `Wᴴ W`. -/\n +theorem norm_applyOperatorToState_sq_eq_stateQForm {ι : Type*} [Fintype ι]\n +    [DecidableEq ι] (ψ : EuclideanSpace ℂ ι) (W : Op ι) :\n +    ‖applyOperatorToState W ψ‖ ^ 2 = stateQForm ψ (Wᴴ * W) :=\n +  MagicSquareRigidity.norm_applyOperatorToState_sq W ψ\n +\n +/-- For two projective measurements, the diagonal overlap in a vector `w` is\n +the squared norm of `w` minus half the summed squared distances.  This is the\n +identity behind `fact:agreement` for projective families, blueprint\n +`blueprint/src/chapter/ch12_qpbt_games.tex:260-272`. -/\n +theorem sum_stateQForm_mul_eq_of_projective {α ι : Type*} [Fintype α]\n +    [Fintype ι] [DecidableEq ι]\n +    (A B : Measurement α ι) (w : EuclideanSpace ℂ ι)\n +    (hA : MIPStarRE.QPBT.Measurement.IsProjective A)\n +    (hB : MIPStarRE.QPBT.Measurement.IsProjective B) :\n +    ∑ a, stateQForm w (A.effect a * B.effect a) =\n +      ‖w‖ ^ 2 -\n +        (1 / 2) * ∑ a, ‖applyOperatorToState (A.effect a - B.effect a) w‖ ^ 2 := by\n +  classical\n +  rw [point_distance_eq_two_defect_of_projective A B w hA hB, point_defect_eq]\n +  ring\n +\n +/-- An effect of a projective measurement is a contraction. -/\n +theorem norm_applyOperatorToState_proj_effect_le {α ι : Type*} [Fintype α]\n +    [Fintype ι] [DecidableEq ι] (M : Measurement α ι)\n +    (hM : MIPStarRE.QPBT.Measurement.IsProjective M) (a : α)\n +    (v : EuclideanSpace ℂ ι) :\n +    ‖applyOperatorToState (M.effect a) v‖ ≤ ‖v‖ := by\n +  refine MagicSquareRigidity.norm_applyOperatorToState_le ?_ v\n +  rw [(hM a).isSelfAdjoint.isHermitian.eq, (hM a).isIdempotentElem.eq]\n +  exact measurement_effect_le_one M a\n +\n +/-- The effects of a projective measurement are square-summable to the\n +identity. -/\n +theorem sum_effect_conjTranspose_mul_self_le_one_of_projective {α ι : Type*}\n +    [Fintype α] [Fintype ι] [DecidableEq ι] (M : Measurement α ι)\n +    (hM : MIPStarRE.QPBT.Measurement.IsProjective M) :\n +    ∑ a, (M.effect a)ᴴ * M.effect a ≤ 1 := by\n +  refine le_of_eq ?_\n +  calc ∑ a, (M.effect a)ᴴ * M.effect a = ∑ a, M.effect a := by\n +        refine Finset.sum_congr rfl fun a _ => ?_\n +        rw [(hM a).isSelfAdjoint.isHermitian.eq, (hM a).isIdempotentElem.eq]\n +    _ = 1 := M.sum_eq_one\n +\n +/-! ## The overlap of two placed sandwiches -/\n +\n +section Abstract\n +\n +variable {α β ι : Type*} [Fintype α] [Fintype β] [Fintype ι] [DecidableEq ι]\n +\n +/-- Formalization-only auxiliary for `lem:qld-4-10`: the product of the two\n +placed sandwiches is `W_bᴴ (X_1 X_2) W_b` with `W_b = Z_1 Z_2`, whenever the\n +operators of the two placements commute. -/\n +theorem sandwich_mul_sandwich_eq (X₁ X₂ : Measurement α ι) (Z₁ Z₂ : Measurement β ι)\n +    (hXZ : ∀ a b, X₁.effect a * Z₂.effect b = Z₂.effect b * X₁.effect a)\n +    (hZX : ∀ a b, Z₁.effect b * X₂.effect a = X₂.effect a * Z₁.effect b)\n +    (hZZ : ∀ b, Z₁.effect b * Z₂.effect b = Z₂.effect b * Z₁.effect b)\n +    (a : α) (b : β) :\n +    (Z₁.effect b * X₁.effect a * Z₁.effect b) *\n +        (Z₂.effect b * X₂.effect a * Z₂.effect b) =\n +      (Z₁.effect b * Z₂.effect b)ᴴ * (X₁.effect a * X₂.effect a) *\n +        (Z₁.effect b * Z₂.effect b) := by\n +  rw [Matrix.conjTranspose_mul, measurement_effect_hermitian,\n +    measurement_effect_hermitian]\n +  simp only [Matrix.mul_assoc]\n +  rw [(show Commute (Z₁.effect b) (Z₂.effect b) from hZZ b).left_comm\n +      (X₂.effect a * Z₂.effect b),\n +    (show Commute (X₁.effect a) (Z₂.effect b) from hXZ a b).left_comm,\n +    (show Commute (Z₁.effect b) (Z₂.effect b) from hZZ b).left_comm,\n +    (show Commute (Z₁.effect b) (X₂.effect a) from hZX a b).left_comm]\n +\n +omit [DecidableEq ι] in\n +/-- Formalization-only auxiliary for `lem:qld-4-10`: the decomposition of\n +`(X_1 - X_2) Z_1 Z_2` into `Z_1 Z_2 (X_1 - X_2)` and the two commutator\n +terms. -/\n +theorem sub_mul_mul_eq_add_commutators (X₁ X₂ Z₁ Z₂ : Op ι)\n +    (hXZ : X₁ * Z₂ = Z₂ * X₁) (hZX : Z₁ * X₂ = X₂ * Z₁)\n +    (hZZ : Z₁ * Z₂ = Z₂ * Z₁) :\n +    (X₁ - X₂) * (Z₁ * Z₂) =\n +      Z₁ * Z₂ * (X₁ - X₂) + Z₂ * (X₁ * Z₁ - Z₁ * X₁) -\n +        Z₁ * (X₂ * Z₂ - Z₂ * X₂) := by\n +  simp only [sub_mul, mul_sub, Matrix.mul_assoc]\n +  rw [(show Commute Z₂ X₁ from hXZ.symm).left_comm Z₁, ← hZZ,\n +    (show Commute Z₂ Z₁ from hZZ.symm).left_comm X₁,\n +    (show Commute Z₁ X₂ from hZX).left_comm Z₂]\n +  abel\n +\n +/-- The overlap of the two placed sandwiches, exactly: with\n +`W_b = Z_1(b) Z_2(b)`,\n +`∑_{a,b} ⟨ψ, R_1(a,b) R_2(a,b) ψ⟩ = ‖ψ‖^2 - (1/2) ∑_b ‖(Z_1(b) - Z_2(b)) ψ‖^2\n +  - (1/2) ∑_{a,b} ‖(X_1(a) - X_2(a)) W_b ψ‖^2`.\n +This replaces the Cauchy--Schwarz chain of displays\n +`eq:qld-rw-self-cons-1` to `eq:qld-rw-self-cons-4`, paper\n +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:743-790`. -/\n +theorem sandwich_overlap_identity (ψ : EuclideanSpace ℂ ι)\n +    (X₁ X₂ : Measurement α ι) (Z₁ Z₂ : Measurement β ι)\n +    (hX₁ : MIPStarRE.QPBT.Measurement.IsProjective X₁)\n +    (hX₂ : MIPStarRE.QPBT.Measurement.IsProjective X₂)\n +    (hZ₁ : MIPStarRE.QPBT.Measurement.IsProjective Z₁)\n +    (hZ₂ : MIPStarRE.QPBT.Measurement.IsProjective Z₂)\n +    (hXZ : ∀ a b, X₁.effect a * Z₂.effect b = Z₂.effect b * X₁.effect a)\n +    (hZX : ∀ a b, Z₁.effect b * X₂.effect a = X₂.effect a * Z₁.effect b)\n +    (hZZ : ∀ b, Z₁.effect b * Z₂.effect b = Z₂.effect b * Z₁.effect b) :\n +    ∑ ab : α × β, stateQForm ψ\n +        ((Z₁.effect ab.2 * X₁.effect ab.1 * Z₁.effect ab.2) *\n +          (Z₂.effect ab.2 * X₂.effect ab.1 * Z₂.effect ab.2)) =\n +      ‖ψ‖ ^ 2 -\n +        (1 / 2) * ∑ b, ‖applyOperatorToState (Z₁.effect b - Z₂.effect b) ψ‖ ^ 2 -\n +        (1 / 2) * ∑ ab : α × β, ‖applyOperatorToState (X₁.effect ab.1 - X₂.effect ab.1)\n +          (applyOperatorToState (Z₁.effect ab.2 * Z₂.effect ab.2) ψ)‖ ^ 2 := by\n +  have hW : ∀ b, ‖applyOperatorToState (Z₁.effect b * Z₂.effect b) ψ‖ ^ 2 =\n +      stateQForm ψ (Z₁.effect b * Z₂.effect b) := by\n +    intro b\n +    rw [norm_applyOperatorToState_sq_eq_stateQForm, Matrix.conjTranspose_mul,\n +      measurement_effect_hermitian, measurement_effect_hermitian]\n +    congr 1\n +    rw [Matrix.mul_assoc, ← Matrix.mul_assoc (Z₁.effect b) (Z₁.effect b),\n +      (hZ₁ b).isIdempotentElem.eq, hZZ b, ← Matrix.mul_assoc,\n +      (hZ₂ b).isIdempotentElem.eq]\n +  have hstep : ∀ ab : α × β, stateQForm ψ\n +      ((Z₁.effect ab.2 * X₁.effect ab.1 * Z₁.effect ab.2) *\n +        (Z₂.effect ab.2 * X₂.effect ab.1 * Z₂.effect ab.2)) =\n +      stateQForm (applyOperatorToState (Z₁.effect ab.2 * Z₂.effect ab.2) ψ)\n +        (X₁.effect ab.1 * X₂.effect ab.1) := by\n +    intro ab\n +    rw [sandwich_mul_sandwich_eq X₁ X₂ Z₁ Z₂ hXZ hZX hZZ,\n +      stateQForm_conjTranspose_mul_mul]\n +  have hWsum : ∑ b, ‖applyOperatorToState (Z₁.effect b * Z₂.effect b) ψ‖ ^ 2 =\n +      ‖ψ‖ ^ 2 -\n +        (1 / 2) * ∑ b, ‖applyOperatorToState (Z₁.effect b - Z₂.effect b) ψ‖ ^ 2 := by\n +    simp_rw [hW]\n +    exact sum_stateQForm_mul_eq_of_projective Z₁ Z₂ ψ hZ₁ hZ₂\n +  calc ∑ ab : α × β, stateQForm ψ\n +        ((Z₁.effect ab.2 * X₁.effect ab.1 * Z₁.effect ab.2) *\n +          (Z₂.effect ab.2 * X₂.effect ab.1 * Z₂.effect ab.2))\n +      = ∑ b, ∑ a, stateQForm (applyOperatorToState (Z₁.effect b * Z₂.effect b) ψ)\n +          (X₁.effect a * X₂.effect a) := by\n +        simp_rw [hstep]\n +        exact Fintype.sum_prod_type_right _\n +    _ = ∑ b, (‖applyOperatorToState (Z₁.effect b * Z₂.effect b) ψ‖ ^ 2 -\n +          (1 / 2) * ∑ a, ‖applyOperatorToState (X₁.effect a - X₂.effect a)\n +            (applyOperatorToState (Z₁.effect b * Z₂.effect b) ψ)‖ ^ 2) := by\n +        refine Finset.sum_congr rfl fun b _ => ?_\n +        exact sum_stateQForm_mul_eq_of_projective X₁ X₂ _ hX₁ hX₂\n +    _ = _ := by\n +        rw [Finset.sum_sub_distrib, ← Finset.mul_sum, hWsum,\n +          Fintype.sum_prod_type_right]\n +\n +/-- The pointwise bound on the consistency defect of the placed sandwiches:\n +in terms of the distances `D^Z`, `D^X` of the two placements and the placed\n +commutators `K^1`, `K^2`,\n +`‖ψ‖^2 - ∑_{a,b} ⟨ψ, R_1 R_2 ψ⟩ ≤ (1/2) D^Z + (3/2) (D^X + K^1 + K^2)`. -/\n +theorem sandwich_defect_pointwise_le (ψ : EuclideanSpace ℂ ι)\n +    (X₁ X₂ : Measurement α ι) (Z₁ Z₂ : Measurement β ι)\n +    (hX₁ : MIPStarRE.QPBT.Measurement.IsProjective X₁)\n +    (hX₂ : MIPStarRE.QPBT.Measurement.IsProjective X₂)\n +    (hZ₁ : MIPStarRE.QPBT.Measurement.IsProjective Z₁)\n +    (hZ₂ : MIPStarRE.QPBT.Measurement.IsProjective Z₂)\n +    (hXZ : ∀ a b, X₁.effect a * Z₂.effect b = Z₂.effect b * X₁.effect a)\n +    (hZX : ∀ a b, Z₁.effect b * X₂.effect a = X₂.effect a * Z₁.effect b)\n +    (hZZ : ∀ b, Z₁.effect b * Z₂.effect b = Z₂.effect b * Z₁.effect b) :\n +    ‖ψ‖ ^ 2 - ∑ ab : α × β, stateQForm ψ\n +        ((Z₁.effect ab.2 * X₁.effect ab.1 * Z₁.effect ab.2) *\n +          (Z₂.effect ab.2 * X₂.effect ab.1 * Z₂.effect ab.2)) ≤\n +      (1 / 2) * ∑ b, ‖applyOperatorToState (Z₁.effect b - Z₂.effect b) ψ‖ ^ 2 +\n +        (3 / 2) * ((∑ a, ‖applyOperatorToState (X₁.effect a - X₂.effect a) ψ‖ ^ 2) +\n +          (∑ ab : α × β, ‖applyOperatorToState\n +            (X₁.effect ab.1 * Z₁.effect ab.2 -\n +              Z₁.effect ab.2 * X₁.effect ab.1) ψ‖ ^ 2) +\n +          ∑ ab : α × β, ‖applyOperatorToState\n +            (X₂.effect ab.1 * Z₂.effect ab.2 -\n +              Z₂.effect ab.2 * X₂.effect ab.1) ψ‖ ^ 2) := by\n +  rw [sandwich_overlap_identity ψ X₁ X₂ Z₁ Z₂ hX₁ hX₂ hZ₁ hZ₂ hXZ hZX hZZ]\n +  -- the pointwise decomposition of `(X_1 - X_2) W_b ψ`\n +  have hpt : ∀ ab : α × β,\n +      ‖applyOperatorToState (X₁.effect ab.1 - X₂.effect ab.1)\n +          (applyOperatorToState (Z₁.effect ab.2 * Z₂.effect ab.2) ψ)‖ ^ 2 ≤\n +        3 * (‖applyOperatorToState (Z₂.effect ab.2 *\n +              (X₁.effect ab.1 - X₂.effect ab.1)) ψ‖ ^ 2 +\n +          ‖applyOperatorToState\n +            (X₁.effect ab.1 * Z₁.effect ab.2 -\n +              Z₁.effect ab.2 * X₁.effect ab.1) ψ‖ ^ 2 +\n +          ‖applyOperatorToState\n +            (X₂.effect ab.1 * Z₂.effect ab.2 -\n +              Z₂.effect ab.2 * X₂.effect ab.1) ψ‖ ^ 2) := by\n +    intro ab\n +    obtain ⟨a, b⟩ := ab\n +    rw [← DistanceCalculus.applyOperatorToState_mul, sub_mul_mul_eq_add_commutators _ _ _ _\n +      (hXZ a b) (hZX a b) (hZZ b)]\n +    have hlin : applyOperatorToState\n +        (Z₁.effect b * Z₂.effect b * (X₁.effect a - X₂.effect a) +\n +          Z₂.effect b * (X₁.effect a * Z₁.effect b - Z₁.effect b * X₁.effect a) -\n +          Z₁.effect b * (X₂.effect a * Z₂.effect b - Z₂.effect b * X₂.effect a)) ψ =\n +        applyOperatorToState (Z₁.effect b)\n +            (applyOperatorToState (Z₂.effect b * (X₁.effect a - X₂.effect a)) ψ) +\n +          applyOperatorToState (Z₂.effect b) (applyOperatorToState\n +            (X₁.effect a * Z₁.effect b - Z₁.effect b * X₁.effect a) ψ) -\n +          applyOperatorToState (Z₁.effect b) (applyOperatorToState\n +            (X₂.effect a * Z₂.effect b - Z₂.effect b * X₂.effect a) ψ) := by\n +      rw [← DistanceCalculus.applyOperatorToState_mul, ← DistanceCalculus.applyOperatorToState_mul,\n +        ← DistanceCalculus.applyOperatorToState_mul, Matrix.mul_assoc]\n +      unfold applyOperatorToState\n +      simp only [map_add, map_sub, LinearMap.add_apply, LinearMap.sub_apply]\n +    rw [hlin]\n +    set u := applyOperatorToState (Z₁.effect b)\n +      (applyOperatorToState (Z₂.effect b * (X₁.effect a - X₂.effect a)) ψ)\n +    set v := applyOperatorToState (Z₂.effect b) (applyOperatorToState\n +      (X₁.effect a * Z₁.effect b - Z₁.effect b * X₁.effect a) ψ)\n +    set w := applyOperatorToState (Z₁.effect b) (applyOperatorToState\n +      (X₂.effect a * Z₂.effect b - Z₂.effect b * X₂.effect a) ψ)\n +    have hu : ‖u‖ ≤ ‖applyOperatorToState\n +        (Z₂.effect b * (X₁.effect a - X₂.effect a)) ψ‖ :=\n +      norm_applyOperatorToState_proj_effect_le Z₁ hZ₁ b _\n +    have hv : ‖v‖ ≤ ‖applyOperatorToState\n +        (X₁.effect a * Z₁.effect b - Z₁.effect b * X₁.effect a) ψ‖ :=\n +      norm_applyOperatorToState_proj_effect_le Z₂ hZ₂ b _\n +    have hw : ‖w‖ ≤ ‖applyOperatorToState\n +        (X₂.effect a * Z₂.effect b - Z₂.effect b * X₂.effect a) ψ‖ :=\n +      norm_applyOperatorToState_proj_effect_le Z₁ hZ₁ b _\n +    have htri : ‖u + v - w‖ ≤ ‖u‖ + ‖v‖ + ‖w‖ :=\n +      le_trans (norm_sub_le (u + v) w) (add_le_add (norm_add_le u v) (le_refl ‖w‖))\n +    have hsq : ‖u + v - w‖ ^ 2 ≤ 3 * (‖u‖ ^ 2 + ‖v‖ ^ 2 + ‖w‖ ^ 2) := by\n +      nlinarith [sq_nonneg (‖u‖ - ‖v‖), sq_nonneg (‖v‖ - ‖w‖),\n +        sq_nonneg (‖u‖ - ‖w‖), norm_nonneg (u + v - w), norm_nonneg u,\n +        norm_nonneg v, norm_nonneg w]\n +    have hu2 := pow_le_pow_left₀ (norm_nonneg _) hu 2\n +    have hv2 := pow_le_pow_left₀ (norm_nonneg _) hv 2\n +    have hw2 := pow_le_pow_left₀ (norm_nonneg _) hw 2\n +    linarith\n +  -- the contraction sum over `b`\n +  have hcontr : ∑ ab : α × β, ‖applyOperatorToState (Z₂.effect ab.2 *\n +      (X₁.effect ab.1 - X₂.effect ab.1)) ψ‖ ^ 2 ≤\n +      ∑ a, ‖applyOperatorToState (X₁.effect a - X₂.effect a) ψ‖ ^ 2 := by\n +    simp only [Fintype.sum_prod_type]\n +    refine Finset.sum_le_sum fun a _ => ?_\n +    exact sum_norm_mul_apply_le Z₂.effect (X₁.effect a - X₂.effect a) ψ\n +      (sum_effect_conjTranspose_mul_self_le_one_of_projective Z₂ hZ₂)\n +  have hsum := Finset.sum_le_sum fun ab (_ : ab ∈ Finset.univ) => hpt ab\n +  rw [← Finset.mul_sum, Finset.sum_add_distrib, Finset.sum_add_distrib] at hsum\n +  linarith\n +\n +end Abstract\n +\n +/-! ## The bound for the placed sandwiches -/\n +\n +namespace ProjectiveSetting\n +\n +variable {P : AdmissibleParams} {ε : ℝ}\n +\n +/-- The pointwise bound on the consistency defect of the sandwich POVM between\n +two placements, as a function of the point pair: one half of the\n +`Z`-distance plus three halves of the `X`-distance and of the two placed\n +commutator sums. -/\n +def sandwichDefectBound (S : ProjectiveSetting P ε) (p₁ p₂ : Placement)\n +    (xz : PointPair P) : ℝ :=\n +  (1 / 2) * ∑ b : PauliScalar P, ‖applyOperatorToState\n +      (S.place p₁ ((S.pointMeasExp p₁.side .Z xz.2).effect b) -\n +        S.place p₂ ((S.pointMeasExp p₂.side .Z xz.2).effect b)) S.psiHat‖ ^ 2 +\n +    (3 / 2) * ((∑ a : PauliScalar P, ‖applyOperatorToState\n +        (S.place p₁ ((S.pointMeasExp p₁.side .X xz.1).effect a) -\n +          S.place p₂ ((S.pointMeasExp p₂.side .X xz.1).effect a)) S.psiHat‖ ^ 2) +\n +      (∑ ab : PauliScalar P × PauliScalar P, ‖applyOperatorToState\n +        (S.place p₁ ((S.pointMeasExp p₁.side .X xz.1).effect ab.1 *\n +            (S.pointMeasExp p₁.side .Z xz.2).effect ab.2) -\n +          S.place p₁ ((S.pointMeasExp p₁.side .Z xz.2).effect ab.2 *\n +            (S.pointMeasExp p₁.side .X xz.1).effect ab.1)) S.psiHat‖ ^ 2) +\n +      ∑ ab : PauliScalar P × PauliScalar P, ‖applyOperatorToState\n +        (S.place p₂ ((S.pointMeasExp p₂.side .X xz.1).effect ab.1 *\n +            (S.pointMeasExp p₂.side .Z xz.2).effect ab.2) -\n +          S.place p₂ ((S.pointMeasExp p₂.side .Z xz.2).effect ab.2 *\n +            (S.pointMeasExp p₂.side .X xz.1).effect ab.1)) S.psiHat‖ ^ 2)\n +\n +/-- The pointwise bound is nonnegative. -/\n +theorem sandwichDefectBound_nonneg (S : ProjectiveSetting P ε) (p₁ p₂ : Placement)\n +    (xz : PointPair P) : 0 ≤ S.sandwichDefectBound p₁ p₂ xz := by\n +  unfold sandwichDefectBound\n +  positivity\n +\n +/-- For a fixed point pair, the off-diagonal mass of the two placed sandwiches\n +is at most the pointwise bound.  This is the consistency of the sandwich POVM\n +between opposite placements, display `eq:rw-sc` of the proof of\n +`lem:qld-4-10`, paper\n +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:743-790`, in\n +exact form. -/\n +theorem sandwich_offDiagonal_le_sandwichDefectBound (S : ProjectiveSetting P ε)\n +    (p₁ p₂ : Placement) (hopp : p₁.IsOpposite p₂) (xz : PointPair P) :\n +    (∑ ab : PauliScalar P × PauliScalar P, ∑ ab' : PauliScalar P × PauliScalar P,\n +      if ab = ab' then 0 else stateQForm S.psiHat\n +        (S.place p₁ ((S.sandwichPoint p₁.side xz.1 xz.2).effect ab) *\n +          S.place p₂ ((S.sandwichPoint p₂.side xz.1 xz.2).effect ab'))) ≤\n +      S.sandwichDefectBound p₁ p₂ xz := by\n +  have hdefect := point_defect_eq\n +    (S.placedMeasurement p₁ (S.sandwichPoint p₁.side xz.1 xz.2))\n +    (S.placedMeasurement p₂ (S.sandwichPoint p₂.side xz.1 xz.2)) S.psiHat\n +  simp only [placedMeasurement_effect] at hdefect\n +  rw [hdefect, psiHat_norm]\n +  have hkey := sandwich_defect_pointwise_le S.psiHat\n +    (S.placedMeasurement p₁ (S.pointMeasExp p₁.side .X xz.1))\n +    (S.placedMeasurement p₂ (S.pointMeasExp p₂.side .X xz.1))\n +    (S.placedMeasurement p₁ (S.pointMeasExp p₁.side .Z xz.2))\n +    (S.placedMeasurement p₂ (S.pointMeasExp p₂.side .Z xz.2))\n +    (S.placedMeasurement_isProjective p₁ _ (S.pointMeasExp_isProjective _ _ _))\n +    (S.placedMeasurement_isProjective p₂ _ (S.pointMeasExp_isProjective _ _ _))\n +    (S.placedMeasurement_isProjective p₁ _ (S.pointMeasExp_isProjective _ _ _))\n +    (S.placedMeasurement_isProjective p₂ _ (S.pointMeasExp_isProjective _ _ _))\n +    (fun a b => S.place_comm p₁ p₂ hopp _ _)\n +    (fun a b => S.place_comm p₁ p₂ hopp _ _)\n +    (fun b => S.place_comm p₁ p₂ hopp _ _)\n +  simp only [placedMeasurement_effect, psiHat_norm] at hkey\n +  unfold sandwichDefectBound\n +  simp only [sandwichPoint_effect, place_mul]\n +  simpa only [place_mul] using hkey\n +\n +/-- The average over the point pair of the pointwise bound is polynomially\n +small: at most a universal constant times `ε + √ε`.  The `X`- and\n +`Z`-distances are the self-consistency of item 1 of `lem:qld-comm-cons`, and\n +the two commutator sums are the field-valued commutation estimate. -/\n +theorem avg_sandwichDefectBound_le :\n +    ∃ C : ℝ, 1 ≤ C ∧\n +      ∀ (P : AdmissibleParams) (ε : ℝ) (S : ProjectiveSetting P ε)\n +        (p₁ p₂ : Placement), p₁.IsOpposite p₂ →\n +        avgOver (uniformDistribution (PointPair P)) (S.sandwichDefectBound p₁ p₂) ≤\n +          C * (ε + Real.sqrt ε) := by\n +  obtain ⟨C₁, hC₁, h₁⟩ := expPoint_self_cons\n +  obtain ⟨C₂, hC₂, h₂⟩ := expPoint_comm\n +  refine ⟨2 * C₁ + 3 * C₂, by linarith, ?_⟩\n +  intro P ε S p₁ p₂ hopp\n +  have hε : (0 : ℝ) ≤ ε := by\n +    have hv := WinImplications.strategy_value_le_one S.toStrategy\n +    have hw := S.win\n +    linarith\n +  have hZ : avgOver (uniformDistribution (PointPair P)) (fun xz =>\n +      ∑ b : PauliScalar P, ‖applyOperatorToState\n +        (S.place p₁ ((S.pointMeasExp p₁.side .Z xz.2).effect b) -\n +          S.place p₂ ((S.pointMeasExp p₂.side .Z xz.2).effect b)) S.psiHat‖ ^ 2) ≤\n +      C₁ * ε := by\n +    rw [avgOver_uniform_snd (α := Fin P.m → PauliScalar P)\n +      (fun z => ∑ b : PauliScalar P, ‖applyOperatorToState\n +        (S.place p₁ ((S.pointMeasExp p₁.side .Z z).effect b) -\n +          S.place p₂ ((S.pointMeasExp p₂.side .Z z).effect b)) S.psiHat‖ ^ 2)]\n +    exact h₁ P ε S p₁ p₂ hopp .Z\n +  have hX : avgOver (uniformDistribution (PointPair P)) (fun xz =>\n +      ∑ a : PauliScalar P, ‖applyOperatorToState\n +        (S.place p₁ ((S.pointMeasExp p₁.side .X xz.1).effect a) -\n +          S.place p₂ ((S.pointMeasExp p₂.side .X xz.1).effect a)) S.psiHat‖ ^ 2) ≤\n +      C₁ * ε := by\n +    rw [avgOver_uniform_fst (β := Fin P.m → PauliScalar P)\n +      (fun x => ∑ a : PauliScalar P, ‖applyOperatorToState\n +        (S.place p₁ ((S.pointMeasExp p₁.side .X x).effect a) -\n +          S.place p₂ ((S.pointMeasExp p₂.side .X x).effect a)) S.psiHat‖ ^ 2)]\n +    exact h₁ P ε S p₁ p₂ hopp .X\n +  have hK₁ := h₂ P ε S p₁\n +  have hK₂ := h₂ P ε S p₂\n +  unfold opFamilyDistSq at hK₁ hK₂\n +  unfold sandwichDefectBound\n +  rw [avgOver_add, avgOver_const_mul, avgOver_const_mul, avgOver_add,\n +    avgOver_add]\n +  have hs : (0 : ℝ) ≤ Real.sqrt ε := Real.sqrt_nonneg ε\n +  nlinarith [hZ, hX, hK₁, hK₂, hs, hε, hC₁, hC₂]\n +\n +end ProjectiveSetting\n +\n +end\n +\n +end MIPStarRE.QPBT\n++||||||| 1c5d5c16\n++=======\n+ import MIPStarRE.QPBT.Combining.Points.Sandwich\n+ \n+ /-!\n+ # Self-consistency of the sandwich POVM\n+ \n+ The sandwich POVM `R^{x,z}_{a,b} = M^Z_b M^X_a M^Z_b` of\n+ `MIPStarRE/QPBT/Combining/Points/Sandwich.lean` is approximately self-consistent\n+ between opposite register placements.  The source establishes this by a\n+ Cauchy--Schwarz chain (displays `eq:qld-rw-self-cons-1` to\n+ `eq:qld-rw-self-cons-4`); here an exact identity is used instead.  Writing\n+ `P_1, P_2` for the two placements of an operator `P`,\n+ `W_b = (M^Z_b)_1 (M^Z_b)_2`, and `D^W_c = (M^W_c)_1 - (M^W_c)_2`, the\n+ consistency defect of the two placed sandwiches equals\n+ `(1/2) ∑_b ‖D^Z_b ψ‖^2 + (1/2) ∑_{a,b} ‖D^X_a W_b ψ‖^2`,\n+ by two applications of the identity\n+ `∑_c ⟨w, P_c Q_c w⟩ = ‖w‖^2 - (1/2) ∑_c ‖(P_c - Q_c) w‖^2` for projective\n+ measurements.  The second sum is then bounded by the self-consistency of `M^X`\n+ and the commutators on the two placements, since\n+ `D^X_a W_b = W_b D^X_a + (M^Z_b)_2 K^1_{a,b} - (M^Z_b)_1 K^2_{a,b}`, where\n+ `K^i_{a,b}` is the placed commutator of `M^X_a` and `M^Z_b`.\n+ \n+ ## Main results\n+ \n+ * `sandwich_overlap_identity`: the exact expression of the overlap of two\n+   placed sandwiches.\n+ * `sandwich_defect_pointwise_le`: the pointwise bound on the consistency\n+   defect of the sandwich for a fixed point pair.\n+ * `ProjectiveSetting.sandwichDefectBound`,\n+   `ProjectiveSetting.sandwich_offDiagonal_le_sandwichDefectBound`, and\n+   `ProjectiveSetting.avg_sandwichDefectBound_le`: the bound as a function of\n+   the point pair, the pointwise estimate, and the average.\n+ \n+ ## References\n+ \n+ Paper `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:743-790`,\n+ blueprint `blueprint/src/chapter/ch15_qpbt_combining.tex:851-880`\n+ (`lem:qld-4-10`, first step); the identity route is explained in\n+ `docs/paper-gaps/qpbt_combined-points-direct.tex`.\n+ -/\n+ \n+ open scoped BigOperators Matrix MatrixOrder ComplexOrder\n+ \n+ namespace MIPStarRE.QPBT\n+ \n+ open MIPStarRE.LDT hiding Measurement\n+ open MIPStarRE.Quantum DistanceCalculus\n+ \n+ noncomputable section\n+ \n+ /-! ## Quadratic-form identities -/\n+ \n+ /-- The quadratic form of `Wᴴ M W` in `ψ` is the quadratic form of `M` in\n+ `W ψ`. -/\n+ theorem stateQForm_conjTranspose_mul_mul {ι : Type*} [Fintype ι] [DecidableEq ι]\n+     (ψ : EuclideanSpace ℂ ι) (W M : Op ι) :\n+     stateQForm ψ (Wᴴ * M * W) = stateQForm (applyOperatorToState W ψ) M := by\n+   unfold stateQForm\n+   rw [applyOperatorToState_mul, applyOperatorToState_mul]\n+   congr 1\n+   change inner ℂ ψ (Matrix.toEuclideanLin Wᴴ _) =\n+     inner ℂ (Matrix.toEuclideanLin W ψ) _\n+   rw [Matrix.toEuclideanLin_conjTranspose_eq_adjoint, LinearMap.adjoint_inner_right]\n+ \n+ /-- The squared norm of `W ψ` is the quadratic form of `Wᴴ W`. -/\n+ theorem norm_applyOperatorToState_sq_eq_stateQForm {ι : Type*} [Fintype ι]\n+     [DecidableEq ι] (ψ : EuclideanSpace ℂ ι) (W : Op ι) :\n+     ‖applyOperatorToState W ψ‖ ^ 2 = stateQForm ψ (Wᴴ * W) :=\n+   MagicSquareRigidity.norm_applyOperatorToState_sq W ψ\n+ \n+ /-- For two projective measurements, the diagonal overlap in a vector `w` is\n+ the squared norm of `w` minus half the summed squared distances.  This is the\n+ identity behind `fact:agreement` for projective families, blueprint\n+ `blueprint/src/chapter/ch12_qpbt_games.tex:260-272`. -/\n+ theorem sum_stateQForm_mul_eq_of_projective {α ι : Type*} [Fintype α]\n+     [Fintype ι] [DecidableEq ι]\n+     (A B : Measurement α ι) (w : EuclideanSpace ℂ ι)\n+     (hA : MIPStarRE.QPBT.Measurement.IsProjective A)\n+     (hB : MIPStarRE.QPBT.Measurement.IsProjective B) :\n+     ∑ a, stateQForm w (A.effect a * B.effect a) =\n+       ‖w‖ ^ 2 -\n+         (1 / 2) * ∑ a, ‖applyOperatorToState (A.effect a - B.effect a) w‖ ^ 2 := by\n+   classical\n+   rw [point_distance_eq_two_defect_of_projective A B w hA hB, point_defect_eq]\n+   ring\n+ \n+ /-- An effect of a projective measurement is a contraction. -/\n+ theorem norm_applyOperatorToState_proj_effect_le {α ι : Type*} [Fintype α]\n+     [Fintype ι] [DecidableEq ι] (M : Measurement α ι)\n+     (hM : MIPStarRE.QPBT.Measurement.IsProjective M) (a : α)\n+     (v : EuclideanSpace ℂ ι) :\n+     ‖applyOperatorToState (M.effect a) v‖ ≤ ‖v‖ := by\n+   refine MagicSquareRigidity.norm_applyOperatorToState_le ?_ v\n+   rw [(hM a).isSelfAdjoint.isHermitian.eq, (hM a).isIdempotentElem.eq]\n+   exact measurement_effect_le_one M a\n+ \n+ /-- The effects of a projective measurement are square-summable to the\n+ identity. -/\n+ theorem sum_effect_conjTranspose_mul_self_le_one_of_projective {α ι : Type*}\n+     [Fintype α] [Fintype ι] [DecidableEq ι] (M : Measurement α ι)\n+     (hM : MIPStarRE.QPBT.Measurement.IsProjective M) :\n+     ∑ a, (M.effect a)ᴴ * M.effect a ≤ 1 := by\n+   refine le_of_eq ?_\n+   calc ∑ a, (M.effect a)ᴴ * M.effect a = ∑ a, M.effect a := by\n+         refine Finset.sum_congr rfl fun a _ => ?_\n+         rw [(hM a).isSelfAdjoint.isHermitian.eq, (hM a).isIdempotentElem.eq]\n+     _ = 1 := M.sum_eq_one\n+ \n+ /-! ## The overlap of two placed sandwiches -/\n+ \n+ section Abstract\n+ \n+ variable {α β ι : Type*} [Fintype α] [Fintype β] [Fintype ι] [DecidableEq ι]\n+ \n+ /-- Formalization-only auxiliary for `lem:qld-4-10`: the product of the two\n+ placed sandwiches is `W_bᴴ (X_1 X_2) W_b` with `W_b = Z_1 Z_2`, whenever the\n+ operators of the two placements commute. -/\n+ theorem sandwich_mul_sandwich_eq (X₁ X₂ : Measurement α ι) (Z₁ Z₂ : Measurement β ι)\n+     (hXZ : ∀ a b, X₁.effect a * Z₂.effect b = Z₂.effect b * X₁.effect a)\n+     (hZX : ∀ a b, Z₁.effect b * X₂.effect a = X₂.effect a * Z₁.effect b)\n+     (hZZ : ∀ b, Z₁.effect b * Z₂.effect b = Z₂.effect b * Z₁.effect b)\n+     (a : α) (b : β) :\n+     (Z₁.effect b * X₁.effect a * Z₁.effect b) *\n+         (Z₂.effect b * X₂.effect a * Z₂.effect b) =\n+       (Z₁.effect b * Z₂.effect b)ᴴ * (X₁.effect a * X₂.effect a) *\n+         (Z₁.effect b * Z₂.effect b) := by\n+   rw [Matrix.conjTranspose_mul, measurement_effect_hermitian,\n+     measurement_effect_hermitian]\n+   simp only [Matrix.mul_assoc]\n+   rw [(show Commute (Z₁.effect b) (Z₂.effect b) from hZZ b).left_comm\n+       (X₂.effect a * Z₂.effect b),\n+     (show Commute (X₁.effect a) (Z₂.effect b) from hXZ a b).left_comm,\n+     (show Commute (Z₁.effect b) (Z₂.effect b) from hZZ b).left_comm,\n+     (show Commute (Z₁.effect b) (X₂.effect a) from hZX a b).left_comm]\n+ \n+ omit [DecidableEq ι] in\n+ /-- Formalization-only auxiliary for `lem:qld-4-10`: the decomposition of\n+ `(X_1 - X_2) Z_1 Z_2` into `Z_1 Z_2 (X_1 - X_2)` and the two commutator\n+ terms. -/\n+ theorem sub_mul_mul_eq_add_commutators (X₁ X₂ Z₁ Z₂ : Op ι)\n+     (hXZ : X₁ * Z₂ = Z₂ * X₁) (hZX : Z₁ * X₂ = X₂ * Z₁)\n+     (hZZ : Z₁ * Z₂ = Z₂ * Z₁) :\n+     (X₁ - X₂) * (Z₁ * Z₂) =\n+       Z₁ * Z₂ * (X₁ - X₂) + Z₂ * (X₁ * Z₁ - Z₁ * X₁) -\n+         Z₁ * (X₂ * Z₂ - Z₂ * X₂) := by\n+   simp only [sub_mul, mul_sub, Matrix.mul_assoc]\n+   rw [(show Commute Z₂ X₁ from hXZ.symm).left_comm Z₁, ← hZZ,\n+     (show Commute Z₂ Z₁ from hZZ.symm).left_comm X₁,\n+     (show Commute Z₁ X₂ from hZX).left_comm Z₂]\n+   abel\n+ \n+ /-- The overlap of the two placed sandwiches, exactly: with\n+ `W_b = Z_1(b) Z_2(b)`,\n+ `∑_{a,b} ⟨ψ, R_1(a,b) R_2(a,b) ψ⟩ = ‖ψ‖^2 - (1/2) ∑_b ‖(Z_1(b) - Z_2(b)) ψ‖^2\n+   - (1/2) ∑_{a,b} ‖(X_1(a) - X_2(a)) W_b ψ‖^2`.\n+ This replaces the Cauchy--Schwarz chain of displays\n+ `eq:qld-rw-self-cons-1` to `eq:qld-rw-self-cons-4`, paper\n+ `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:743-790`. -/\n+ theorem sandwich_overlap_identity (ψ : EuclideanSpace ℂ ι)\n+     (X₁ X₂ : Measurement α ι) (Z₁ Z₂ : Measurement β ι)\n+     (hX₁ : MIPStarRE.QPBT.Measurement.IsProjective X₁)\n+     (hX₂ : MIPStarRE.QPBT.Measurement.IsProjective X₂)\n+     (hZ₁ : MIPStarRE.QPBT.Measurement.IsProjective Z₁)\n+     (hZ₂ : MIPStarRE.QPBT.Measurement.IsProjective Z₂)\n+     (hXZ : ∀ a b, X₁.effect a * Z₂.effect b = Z₂.effect b * X₁.effect a)\n+     (hZX : ∀ a b, Z₁.effect b * X₂.effect a = X₂.effect a * Z₁.effect b)\n+     (hZZ : ∀ b, Z₁.effect b * Z₂.effect b = Z₂.effect b * Z₁.effect b) :\n+     ∑ ab : α × β, stateQForm ψ\n+         ((Z₁.effect ab.2 * X₁.effect ab.1 * Z₁.effect ab.2) *\n+           (Z₂.effect ab.2 * X₂.effect ab.1 * Z₂.effect ab.2)) =\n+       ‖ψ‖ ^ 2 -\n+         (1 / 2) * ∑ b, ‖applyOperatorToState (Z₁.effect b - Z₂.effect b) ψ‖ ^ 2 -\n+         (1 / 2) * ∑ ab : α × β, ‖applyOperatorToState (X₁.effect ab.1 - X₂.effect ab.1)\n+           (applyOperatorToState (Z₁.effect ab.2 * Z₂.effect ab.2) ψ)‖ ^ 2 := by\n+   have hW : ∀ b, ‖applyOperatorToState (Z₁.effect b * Z₂.effect b) ψ‖ ^ 2 =\n+       stateQForm ψ (Z₁.effect b * Z₂.effect b) := by\n+     intro b\n+     rw [norm_applyOperatorToState_sq_eq_stateQForm, Matrix.conjTranspose_mul,\n+       measurement_effect_hermitian, measurement_effect_hermitian]\n+     congr 1\n+     rw [Matrix.mul_assoc, ← Matrix.mul_assoc (Z₁.effect b) (Z₁.effect b),\n+       (hZ₁ b).isIdempotentElem.eq, hZZ b, ← Matrix.mul_assoc,\n+       (hZ₂ b).isIdempotentElem.eq]\n+   have hstep : ∀ ab : α × β, stateQForm ψ\n+       ((Z₁.effect ab.2 * X₁.effect ab.1 * Z₁.effect ab.2) *\n+         (Z₂.effect ab.2 * X₂.effect ab.1 * Z₂.effect ab.2)) =\n+       stateQForm (applyOperatorToState (Z₁.effect ab.2 * Z₂.effect ab.2) ψ)\n+         (X₁.effect ab.1 * X₂.effect ab.1) := by\n+     intro ab\n+     rw [sandwich_mul_sandwich_eq X₁ X₂ Z₁ Z₂ hXZ hZX hZZ,\n+       stateQForm_conjTranspose_mul_mul]\n+   have hWsum : ∑ b, ‖applyOperatorToState (Z₁.effect b * Z₂.effect b) ψ‖ ^ 2 =\n+       ‖ψ‖ ^ 2 -\n+         (1 / 2) * ∑ b, ‖applyOperatorToState (Z₁.effect b - Z₂.effect b) ψ‖ ^ 2 := by\n+     simp_rw [hW]\n+     exact sum_stateQForm_mul_eq_of_projective Z₁ Z₂ ψ hZ₁ hZ₂\n+   calc ∑ ab : α × β, stateQForm ψ\n+         ((Z₁.effect ab.2 * X₁.effect ab.1 * Z₁.effect ab.2) *\n+           (Z₂.effect ab.2 * X₂.effect ab.1 * Z₂.effect ab.2))\n+       = ∑ b, ∑ a, stateQForm (applyOperatorToState (Z₁.effect b * Z₂.effect b) ψ)\n+           (X₁.effect a * X₂.effect a) := by\n+         simp_rw [hstep]\n+         exact Fintype.sum_prod_type_right _\n+     _ = ∑ b, (‖applyOperatorToState (Z₁.effect b * Z₂.effect b) ψ‖ ^ 2 -\n+           (1 / 2) * ∑ a, ‖applyOperatorToState (X₁.effect a - X₂.effect a)\n+             (applyOperatorToState (Z₁.effect b * Z₂.effect b) ψ)‖ ^ 2) := by\n+         refine Finset.sum_congr rfl fun b _ => ?_\n+         exact sum_stateQForm_mul_eq_of_projective X₁ X₂ _ hX₁ hX₂\n+     _ = _ := by\n+         rw [Finset.sum_sub_distrib, ← Finset.mul_sum, hWsum,\n+           Fintype.sum_prod_type_right]\n+ \n+ /-- The pointwise bound on the consistency defect of the placed sandwiches:\n+ in terms of the distances `D^Z`, `D^X` of the two placements and the placed\n+ commutators `K^1`, `K^2`,\n+ `‖ψ‖^2 - ∑_{a,b} ⟨ψ, R_1 R_2 ψ⟩ ≤ (1/2) D^Z + (3/2) (D^X + K^1 + K^2)`. -/\n+ theorem sandwich_defect_pointwise_le (ψ : EuclideanSpace ℂ ι)\n+     (X₁ X₂ : Measurement α ι) (Z₁ Z₂ : Measurement β ι)\n+     (hX₁ : MIPStarRE.QPBT.Measurement.IsProjective X₁)\n+     (hX₂ : MIPStarRE.QPBT.Measurement.IsProjective X₂)\n+     (hZ₁ : MIPStarRE.QPBT.Measurement.IsProjective Z₁)\n+     (hZ₂ : MIPStarRE.QPBT.Measurement.IsProjective Z₂)\n+     (hXZ : ∀ a b, X₁.effect a * Z₂.effect b = Z₂.effect b * X₁.effect a)\n+     (hZX : ∀ a b, Z₁.effect b * X₂.effect a = X₂.effect a * Z₁.effect b)\n+     (hZZ : ∀ b, Z₁.effect b * Z₂.effect b = Z₂.effect b * Z₁.effect b) :\n+     ‖ψ‖ ^ 2 - ∑ ab : α × β, stateQForm ψ\n+         ((Z₁.effect ab.2 * X₁.effect ab.1 * Z₁.effect ab.2) *\n+           (Z₂.effect ab.2 * X₂.effect ab.1 * Z₂.effect ab.2)) ≤\n+       (1 / 2) * ∑ b, ‖applyOperatorToState (Z₁.effect b - Z₂.effect b) ψ‖ ^ 2 +\n+         (3 / 2) * ((∑ a, ‖applyOperatorToState (X₁.effect a - X₂.effect a) ψ‖ ^ 2) +\n+           (∑ ab : α × β, ‖applyOperatorToState\n+             (X₁.effect ab.1 * Z₁.effect ab.2 -\n+               Z₁.effect ab.2 * X₁.effect ab.1) ψ‖ ^ 2) +\n+           ∑ ab : α × β, ‖applyOperatorToState\n+             (X₂.effect ab.1 * Z₂.effect ab.2 -\n+               Z₂.effect ab.2 * X₂.effect ab.1) ψ‖ ^ 2) := by\n+   rw [sandwich_overlap_identity ψ X₁ X₂ Z₁ Z₂ hX₁ hX₂ hZ₁ hZ₂ hXZ hZX hZZ]\n+   -- the pointwise decomposition of `(X_1 - X_2) W_b ψ`\n+   have hpt : ∀ ab : α × β,\n+       ‖applyOperatorToState (X₁.effect ab.1 - X₂.effect ab.1)\n+           (applyOperatorToState (Z₁.effect ab.2 * Z₂.effect ab.2) ψ)‖ ^ 2 ≤\n+         3 * (‖applyOperatorToState (Z₂.effect ab.2 *\n+               (X₁.effect ab.1 - X₂.effect ab.1)) ψ‖ ^ 2 +\n+           ‖applyOperatorToState\n+             (X₁.effect ab.1 * Z₁.effect ab.2 -\n+               Z₁.effect ab.2 * X₁.effect ab.1) ψ‖ ^ 2 +\n+           ‖applyOperatorToState\n+             (X₂.effect ab.1 * Z₂.effect ab.2 -\n+               Z₂.effect ab.2 * X₂.effect ab.1) ψ‖ ^ 2) := by\n+     intro ab\n+     obtain ⟨a, b⟩ := ab\n+     rw [← applyOperatorToState_mul, sub_mul_mul_eq_add_commutators _ _ _ _\n+       (hXZ a b) (hZX a b) (hZZ b)]\n+     have hlin : applyOperatorToState\n+         (Z₁.effect b * Z₂.effect b * (X₁.effect a - X₂.effect a) +\n+           Z₂.effect b * (X₁.effect a * Z₁.effect b - Z₁.effect b * X₁.effect a) -\n+           Z₁.effect b * (X₂.effect a * Z₂.effect b - Z₂.effect b * X₂.effect a)) ψ =\n+         applyOperatorToState (Z₁.effect b)\n+             (applyOperatorToState (Z₂.effect b * (X₁.effect a - X₂.effect a)) ψ) +\n+           applyOperatorToState (Z₂.effect b) (applyOperatorToState\n+             (X₁.effect a * Z₁.effect b - Z₁.effect b * X₁.effect a) ψ) -\n+           applyOperatorToState (Z₁.effect b) (applyOperatorToState\n+             (X₂.effect a * Z₂.effect b - Z₂.effect b * X₂.effect a) ψ) := by\n+       rw [← applyOperatorToState_mul, ← applyOperatorToState_mul,\n+         ← applyOperatorToState_mul, Matrix.mul_assoc]\n+       unfold applyOperatorToState\n+       simp only [map_add, map_sub, LinearMap.add_apply, LinearMap.sub_apply]\n+     rw [hlin]\n+     set u := applyOperatorToState (Z₁.effect b)\n+       (applyOperatorToState (Z₂.effect b * (X₁.effect a - X₂.effect a)) ψ)\n+     set v := applyOperatorToState (Z₂.effect b) (applyOperatorToState\n+       (X₁.effect a * Z₁.effect b - Z₁.effect b * X₁.effect a) ψ)\n+     set w := applyOperatorToState (Z₁.effect b) (applyOperatorToState\n+       (X₂.effect a * Z₂.effect b - Z₂.effect b * X₂.effect a) ψ)\n+     have hu : ‖u‖ ≤ ‖applyOperatorToState\n+         (Z₂.effect b * (X₁.effect a - X₂.effect a)) ψ‖ :=\n+       norm_applyOperatorToState_proj_effect_le Z₁ hZ₁ b _\n+     have hv : ‖v‖ ≤ ‖applyOperatorToState\n+         (X₁.effect a * Z₁.effect b - Z₁.effect b * X₁.effect a) ψ‖ :=\n+