∑ b : PauliScalar P, ‖applyOperatorToState\n+       (S.place p₁ ((S.pointMeasExp p₁.side .Z xz.2).effect b) -\n+         S.place p₂ ((S.pointMeasExp p₂.side .Z xz.2).effect b)) S.psiHat‖ ^ 2 +\n+     (3 / 2) * ((∑ a : PauliScalar P, ‖applyOperatorToState\n+         (S.place p₁ ((S.pointMeasExp p₁.side .X xz.1).effect a) -\n+           S.place p₂ ((S.pointMeasExp p₂.side .X xz.1).effect a)) S.psiHat‖ ^ 2) +\n+       (∑ ab : PauliScalar P × PauliScalar P, ‖applyOperatorToState\n+         (S.place p₁ ((S.pointMeasExp p₁.side .X xz.1).effect ab.1 *\n+             (S.pointMeasExp p₁.side .Z xz.2).effect ab.2) -\n+           S.place p₁ ((S.pointMeasExp p₁.side .Z xz.2).effect ab.2 *\n+             (S.pointMeasExp p₁.side .X xz.1).effect ab.1)) S.psiHat‖ ^ 2) +\n+       ∑ ab : PauliScalar P × PauliScalar P, ‖applyOperatorToState\n+         (S.place p₂ ((S.pointMeasExp p₂.side .X xz.1).effect ab.1 *\n+             (S.pointMeasExp p₂.side .Z xz.2).effect ab.2) -\n+           S.place p₂ ((S.pointMeasExp p₂.side .Z xz.2).effect ab.2 *\n+             (S.pointMeasExp p₂.side .X xz.1).effect ab.1)) S.psiHat‖ ^ 2)\n+ \n+ /-- The pointwise bound is nonnegative. -/\n+ theorem sandwichDefectBound_nonneg (S : ProjectiveSetting P ε) (p₁ p₂ : Placement)\n+     (xz : PointPair P) : 0 ≤ S.sandwichDefectBound p₁ p₂ xz := by\n+   unfold sandwichDefectBound\n+   positivity\n+ \n+ /-- For a fixed point pair, the off-diagonal mass of the two placed sandwiches\n+ is at most the pointwise bound.  This is the consistency of the sandwich POVM\n+ between opposite placements, display `eq:rw-sc` of the proof of\n+ `lem:qld-4-10`, paper\n+ `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:743-790`, in\n+ exact form. -/\n+ theorem sandwich_offDiagonal_le_sandwichDefectBound (S : ProjectiveSetting P ε)\n+     (p₁ p₂ : Placement) (hopp : p₁.IsOpposite p₂) (xz : PointPair P) :\n+     (∑ ab : PauliScalar P × PauliScalar P, ∑ ab' : PauliScalar P × PauliScalar P,\n+       if ab = ab' then 0 else stateQForm S.psiHat\n+         (S.place p₁ ((S.sandwichPoint p₁.side xz.1 xz.2).effect ab) *\n+           S.place p₂ ((S.sandwichPoint p₂.side xz.1 xz.2).effect ab'))) ≤\n+       S.sandwichDefectBound p₁ p₂ xz := by\n+   have hdefect := point_defect_eq\n+     (S.placedMeasurement p₁ (S.sandwichPoint p₁.side xz.1 xz.2))\n+     (S.placedMeasurement p₂ (S.sandwichPoint p₂.side xz.1 xz.2)) S.psiHat\n+   simp only [placedMeasurement_effect] at hdefect\n+   rw [hdefect, psiHat_norm]\n+   have hkey := sandwich_defect_pointwise_le S.psiHat\n+     (S.placedMeasurement p₁ (S.pointMeasExp p₁.side .X xz.1))\n+     (S.placedMeasurement p₂ (S.pointMeasExp p₂.side .X xz.1))\n+     (S.placedMeasurement p₁ (S.pointMeasExp p₁.side .Z xz.2))\n+     (S.placedMeasurement p₂ (S.pointMeasExp p₂.side .Z xz.2))\n+     (S.placedMeasurement_isProjective p₁ _ (S.pointMeasExp_isProjective _ _ _))\n+     (S.placedMeasurement_isProjective p₂ _ (S.pointMeasExp_isProjective _ _ _))\n+     (S.placedMeasurement_isProjective p₁ _ (S.pointMeasExp_isProjective _ _ _))\n+     (S.placedMeasurement_isProjective p₂ _ (S.pointMeasExp_isProjective _ _ _))\n+     (fun a b => S.place_comm p₁ p₂ hopp _ _)\n+     (fun a b => S.place_comm p₁ p₂ hopp _ _)\n+     (fun b => S.place_comm p₁ p₂ hopp _ _)\n+   simp only [placedMeasurement_effect, psiHat_norm] at hkey\n+   unfold sandwichDefectBound\n+   simp only [sandwichPoint_effect, place_mul]\n+   simpa only [place_mul] using hkey\n+ \n+ /-- The average over the point pair of the pointwise bound is polynomially\n+ small: at most a universal constant times `ε + √ε`.  The `X`- and\n+ `Z`-distances are the self-consistency of item 1 of `lem:qld-comm-cons`, and\n+ the two commutator sums are the field-valued commutation estimate. -/\n+ theorem avg_sandwichDefectBound_le :\n+     ∃ C : ℝ, 1 ≤ C ∧\n+       ∀ (P : AdmissibleParams) (ε : ℝ) (S : ProjectiveSetting P ε)\n+         (p₁ p₂ : Placement), p₁.IsOpposite p₂ →\n+         avgOver (uniformDistribution (PointPair P)) (S.sandwichDefectBound p₁ p₂) ≤\n+           C * (ε + Real.sqrt ε) := by\n+   obtain ⟨C₁, hC₁, h₁⟩ := expPoint_self_cons\n+   obtain ⟨C₂, hC₂, h₂⟩ := expPoint_comm\n+   refine ⟨2 * C₁ + 3 * C₂, by linarith, ?_⟩\n+   intro P ε S p₁ p₂ hopp\n+   have hε : (0 : ℝ) ≤ ε := by\n+     have hv := WinImplications.strategy_value_le_one S.toStrategy\n+     have hw := S.win\n+     linarith\n+   have hZ : avgOver (uniformDistribution (PointPair P)) (fun xz =>\n+       ∑ b : PauliScalar P, ‖applyOperatorToState\n+         (S.place p₁ ((S.pointMeasExp p₁.side .Z xz.2).effect b) -\n+           S.place p₂ ((S.pointMeasExp p₂.side .Z xz.2).effect b)) S.psiHat‖ ^ 2) ≤\n+       C₁ * ε := by\n+     rw [avgOver_uniform_snd (α := Fin P.m → PauliScalar P)\n+       (fun z => ∑ b : PauliScalar P, ‖applyOperatorToState\n+         (S.place p₁ ((S.pointMeasExp p₁.side .Z z).effect b) -\n+           S.place p₂ ((S.pointMeasExp p₂.side .Z z).effect b)) S.psiHat‖ ^ 2)]\n+     exact h₁ P ε S p₁ p₂ hopp .Z\n+   have hX : avgOver (uniformDistribution (PointPair P)) (fun xz =>\n+       ∑ a : PauliScalar P, ‖applyOperatorToState\n+         (S.place p₁ ((S.pointMeasExp p₁.side .X xz.1).effect a) -\n+           S.place p₂ ((S.pointMeasExp p₂.side .X xz.1).effect a)) S.psiHat‖ ^ 2) ≤\n+       C₁ * ε := by\n+     rw [avgOver_uniform_fst (β := Fin P.m → PauliScalar P)\n+       (fun x => ∑ a : PauliScalar P, ‖applyOperatorToState\n+         (S.place p₁ ((S.pointMeasExp p₁.side .X x).effect a) -\n+           S.place p₂ ((S.pointMeasExp p₂.side .X x).effect a)) S.psiHat‖ ^ 2)]\n+     exact h₁ P ε S p₁ p₂ hopp .X\n+   have hK₁ := h₂ P ε S p₁\n+   have hK₂ := h₂ P ε S p₂\n+   unfold opFamilyDistSq at hK₁ hK₂\n+   unfold sandwichDefectBound\n+   rw [avgOver_add, avgOver_const_mul, avgOver_const_mul, avgOver_add,\n+     avgOver_add]\n+   have hs : (0 : ℝ) ≤ Real.sqrt ε := Real.sqrt_nonneg ε\n+   nlinarith [hZ, hX, hK₁, hK₂, hs, hε, hC₁, hC₂]\n+ \n+ end ProjectiveSetting\n+ \n+ end\n+ \n+ end MIPStarRE.QPBT\n++>>>>>>> github/main\ndiff --cc MIPStarRE/QPBT/Combining/Points/Orthonormalization.lean\nindex 144e05fc,10292cc2..00000000\n--- a/MIPStarRE/QPBT/Combining/Points/Orthonormalization.lean\n+++ b/MIPStarRE/QPBT/Combining/Points/Orthonormalization.lean\n@@@ -1,346 -1,330 +1,680 @@@\n++<<<<<<< HEAD\n +import MIPStarRE.QPBT.Combining.Points.Consistency\n +import MIPStarRE.QPBT.Games.DistanceTheorems\n +\n +/-!\n +# Orthonormalization of the sandwich POVM\n +\n +For each fixed point pair `(x, z)`, the sandwich POVM `R^{x,z}` on one\n +register placement is consistent with the sandwich POVM on the opposite\n +placement, with the consistency defect bounded by\n +`ProjectiveSetting.sandwichDefectBound`.  The orthonormalization lemma\n +`lem:ortho`, in its explicit-constant form\n +`projective_rounding_with_explicit_constant`, therefore produces a projective\n +measurement `Q^{x,z}` on the original local space, within `220 · c^{1/4}` of\n +`R^{x,z}` on the expanded state, where `c` is that bound.  Choosing such a\n +measurement for every pair and averaging, the concavity of `t ↦ t^{1/4}`\n +turns the average of the fiberwise errors into the same function of the\n +average defect.\n +\n +The orthonormalization lemma is stated for a bipartite state whose first\n +tensor factor carries the POVM to be rounded.  The two bipartitions used are\n +`AA' | BA''(B'B'')`, for Alice's measurements, and `BA'' | AA'(B'B'')`, for\n +Bob's; the second is introduced here.\n +\n +## Main results\n +\n +* `baAaBipartition` with its two placement lemmas.\n +* `avgOver_rpow_quarter_le`: Jensen's inequality for the fourth root.\n +* `ProjectiveSetting.exists_projective_close_sandwich`: the fiberwise\n +  orthonormalization, for any bipartition exhibiting the two placements as\n +  the two tensor factors.\n +\n +## References\n +\n +Paper `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:786-790`\n +(the application of the orthonormalization lemma), blueprint\n +`blueprint/src/chapter/ch15_qpbt_combining.tex:870-878` (`lem:qld-4-10`), and\n +`blueprint/src/chapter/ch14_qpbt_observables.tex:395-464` (`lem:ortho`); the\n +route is explained in `docs/paper-gaps/qpbt_linearity-theorem-quotation.tex`.\n +-/\n +\n +open scoped BigOperators Matrix MatrixOrder ComplexOrder\n +\n +namespace MIPStarRE.QPBT\n +\n +open MIPStarRE.LDT hiding Measurement\n +open MIPStarRE.Quantum DistanceCalculus\n +\n +noncomputable section\n +\n +/-! ## Jensen's inequality for the fourth root -/\n +\n +/-- The fourth root of a nonnegative real is the iterated square root. -/\n +theorem rpow_quarter_eq_sqrt_sqrt {t : ℝ} (ht : 0 ≤ t) :\n +    Real.rpow t (1 / 4 : ℝ) = Real.sqrt (Real.sqrt t) := by\n +  rw [Real.sqrt_eq_rpow, Real.sqrt_eq_rpow, ← Real.rpow_mul ht]\n +  norm_num\n +\n +/-- Jensen's inequality for the concave function `t ↦ t^{1/4}` on a\n +sub-probability average, obtained by applying the square-root inequality\n +twice. -/\n +theorem avgOver_rpow_quarter_le {X : Type*} (𝒟 : Distribution X)\n +    (h𝒟 : ∑ x ∈ 𝒟.support, 𝒟.weight x ≤ 1) (b : X → ℝ) (hb : ∀ x, 0 ≤ b x) :\n +    avgOver 𝒟 (fun x => Real.rpow (b x) (1 / 4 : ℝ)) ≤\n +      Real.rpow (avgOver 𝒟 b) (1 / 4 : ℝ) := by\n +  have h1 : |avgOver 𝒟 (fun x => Real.sqrt (Real.sqrt (b x)))| ≤\n +      Real.sqrt (avgOver 𝒟 (fun x => Real.sqrt (b x))) :=\n +    MIPStarRE.LDT.Preliminaries.avgOver_abs_le_sqrt_of_pointwise 𝒟 _ _\n +      (fun x => by rw [abs_of_nonneg (Real.sqrt_nonneg _)])\n +      (fun x => Real.sqrt_nonneg _) h𝒟\n +  have h2 : |avgOver 𝒟 (fun x => Real.sqrt (b x))| ≤ Real.sqrt (avgOver 𝒟 b) :=\n +    MIPStarRE.LDT.Preliminaries.avgOver_abs_le_sqrt_of_pointwise 𝒟 _ _\n +      (fun x => by rw [abs_of_nonneg (Real.sqrt_nonneg _)]) hb h𝒟\n +  have havg : 0 ≤ avgOver 𝒟 b := avgOver_nonneg 𝒟 b hb\n +  rw [rpow_quarter_eq_sqrt_sqrt havg]\n +  calc avgOver 𝒟 (fun x => Real.rpow (b x) (1 / 4 : ℝ))\n +      = avgOver 𝒟 (fun x => Real.sqrt (Real.sqrt (b x))) :=\n +        avgOver_congr _ _ _ fun x => rpow_quarter_eq_sqrt_sqrt (hb x)\n +    _ ≤ |avgOver 𝒟 (fun x => Real.sqrt (Real.sqrt (b x)))| := le_abs_self _\n +    _ ≤ Real.sqrt (avgOver 𝒟 (fun x => Real.sqrt (b x))) := h1\n +    _ ≤ Real.sqrt (Real.sqrt (avgOver 𝒟 b)) :=\n +        Real.sqrt_le_sqrt (le_trans (le_abs_self _) h2)\n +\n +/-! ## The bipartition with Bob's registers first -/\n +\n +/-- Regroup `AA'A''BB'B''` as `BA'' | AA'(B'B'')`.  This is the bipartition\n +in which Bob's expanded local space is the first tensor factor, used to\n +orthonormalize the sandwich POVM on Bob's side. -/\n +def baAaBipartition (P : AdmissibleParams) (ιA ιB : Type*) :\n +    SixReg P ιA ιB ≃\n +      (ιB × PauliRegister P) ×\n +        ((ιA × PauliRegister P) × (PauliRegister P × PauliRegister P)) where\n +  toFun := fun ⟨⟨a, a', a''⟩, b, b', b''⟩ => ((b, a''), ((a, a'), (b', b'')))\n +  invFun := fun ⟨⟨b, a''⟩, ⟨a, a'⟩, b', b''⟩ => ((a, (a', a'')), (b, (b', b'')))\n +  left_inv := by rintro ⟨⟨a, a', a''⟩, b, b', b''⟩; rfl\n +  right_inv := by rintro ⟨⟨b, a''⟩, ⟨a, a'⟩, b', b''⟩; rfl\n +\n +namespace ProjectiveSetting\n +\n +variable {P : AdmissibleParams} {ε : ℝ}\n +\n +/-- Under the `BA'' | AA'(B'B'')` bipartition, a `BA''` placement is the\n +ordinary left tensor placement. -/\n +theorem reindexOp_baAaBipartition_left (S : ProjectiveSetting P ε)\n +    (O : Op (S.ExpandedLocalSpace Placement.BA''.side)) :\n +    reindexOp (baAaBipartition P S.toStrategy.ιA S.toStrategy.ιB)\n +        (heteroKron O\n +          (1 : Op ((S.toStrategy.ιA × PauliRegister P) ×\n +            (PauliRegister P × PauliRegister P)))) =\n +      S.place .BA'' O := by\n +  ext i j\n +  obtain ⟨⟨a, a', a''⟩, b, b', b''⟩ := i\n +  obtain ⟨⟨c, c', c''⟩, d, d', d''⟩ := j\n +  simp only [reindexOp, Matrix.reindex_apply, Matrix.submatrix_apply,\n +    Equiv.symm_symm, place, baAaBipartition, Equiv.coe_fn_mk, heteroKron,\n +    Matrix.kronecker, Matrix.kroneckerMap_apply, Matrix.one_apply, Prod.mk.injEq]\n +  split_ifs\n +  all_goals simp_all\n +  all_goals rfl\n +\n +/-- Under the `BA'' | AA'(B'B'')` bipartition, an `AA'` placement is the\n +ordinary right tensor placement, with identity on the unused EPR pair. -/\n +theorem reindexOp_baAaBipartition_right (S : ProjectiveSetting P ε)\n +    (O : Op (S.ExpandedLocalSpace Placement.AA'.side)) :\n +    reindexOp (baAaBipartition P S.toStrategy.ιA S.toStrategy.ιB)\n +        (heteroKron (1 : Op (S.toStrategy.ιB × PauliRegister P))\n +          (heteroKron O (1 : Op (PauliRegister P × PauliRegister P)))) =\n +      S.place .AA' O := by\n +  ext i j\n +  obtain ⟨⟨a, a', a''⟩, b, b', b''⟩ := i\n +  obtain ⟨⟨c, c', c''⟩, d, d', d''⟩ := j\n +  simp only [reindexOp, Matrix.reindex_apply, Matrix.submatrix_apply,\n +    Equiv.symm_symm, place, baAaBipartition, Equiv.coe_fn_mk, heteroKron,\n +    Matrix.kronecker, Matrix.kroneckerMap_apply, Matrix.one_apply, Prod.mk.injEq]\n +  split_ifs\n +  all_goals simp_all\n +  all_goals rfl\n +\n +/-! ## Transport along a bipartition -/\n +\n +section Bipartition\n +\n +variable (S : ProjectiveSetting P ε) (p₁ p₂ : Placement)\n +\n +set_option synthInstance.maxSize 400 in\n +/-- The consistency defect of two placed POVMs, read in the bipartite picture\n +of the reindexed expanded state, is their off-diagonal mass in the expanded\n +state. -/\n +theorem consistencyDefect_reindex_eq {α : Type*} [Fintype α] [DecidableEq α]\n +    (e : SixReg P S.toStrategy.ιA S.toStrategy.ιB ≃\n +      S.ExpandedLocalSpace p₁.side ×\n +        (S.ExpandedLocalSpace p₂.side × (PauliRegister P × PauliRegister P)))\n +    (he₁ : ∀ O : Op (S.ExpandedLocalSpace p₁.side),\n +      reindexOp e (heteroKron O\n +        (1 : Op (S.ExpandedLocalSpace p₂.side ×\n +          (PauliRegister P × PauliRegister P)))) = S.place p₁ O)\n +    (he₂ : ∀ O : Op (S.ExpandedLocalSpace p₂.side),\n +      reindexOp e (heteroKron (1 : Op (S.ExpandedLocalSpace p₁.side))\n +        (heteroKron O (1 : Op (PauliRegister P × PauliRegister P)))) =\n +          S.place p₂ O)\n +    (Q : Measurement α (S.ExpandedLocalSpace p₁.side))\n +    (R : Measurement α (S.ExpandedLocalSpace p₂.side)) :\n +    consistencyDefect (uniformDistribution Unit)\n +        (fun _ a => heteroKron (Q.effect a) 1)\n +        (fun _ a => heteroKron 1\n +          ((leftPlacedMeasurement (ιB := PauliRegister P × PauliRegister P) R).effect a))\n +        (reindexState e S.psiHat) =\n +      ∑ a : α, ∑ b : α, if a = b then 0 else\n +        stateQForm S.psiHat (S.place p₁ (Q.effect a) * S.place p₂ (R.effect b)) := by\n +  classical\n +  unfold consistencyDefect\n +  rw [avgOver_uniform_const]\n +  refine Finset.sum_congr rfl fun a _ => Finset.sum_congr rfl fun b _ => ?_\n +  by_cases hab : a = b\n +  · simp [hab]\n +  · rw [if_neg hab, if_neg hab, consistency_term_eq_stateQForm,\n +      WinImplications.stateQForm_reindexState, WinImplications.reindexOp_mul, he₁]\n +    change stateQForm S.psiHat (S.place p₁ (Q.effect a) *\n +      reindexOp e (heteroKron 1 (heteroKron (R.effect b) 1))) = _\n +    rw [he₂]\n +\n +set_option synthInstance.maxSize 400 in\n +/-- The state-dependent distance of two families placed on the first factor,\n +read in the bipartite picture, is their placed distance in the expanded\n +state. -/\n +theorem opFamilyDistSq_reindex_left_eq {α : Type*} [Fintype α]\n +    (e : SixReg P S.toStrategy.ιA S.toStrategy.ιB ≃\n +      S.ExpandedLocalSpace p₁.side ×\n +        (S.ExpandedLocalSpace p₂.side × (PauliRegister P × PauliRegister P)))\n +    (he₁ : ∀ O : Op (S.ExpandedLocalSpace p₁.side),\n +      reindexOp e (heteroKron O\n +        (1 : Op (S.ExpandedLocalSpace p₂.side ×\n +          (PauliRegister P × PauliRegister P)))) = S.place p₁ O)\n +    (A B : α → Op (S.ExpandedLocalSpace p₁.side)) :\n +    opFamilyDistSq (uniformDistribution Unit)\n +        (fun _ a => heteroKron (A a) 1) (fun _ a => heteroKron (B a) 1)\n +        (reindexState e S.psiHat) =\n +      ∑ a : α, ‖applyOperatorToState (S.place p₁ (A a) - S.place p₁ (B a))\n +        S.psiHat‖ ^ 2 := by\n +  classical\n +  unfold opFamilyDistSq\n +  rw [avgOver_uniform_const]\n +  refine Finset.sum_congr rfl fun a _ => ?_\n +  rw [WinImplications.norm_applyOperatorToState_reindexState,\n +    WinImplications.reindexOp_sub, he₁, he₁]\n +\n +set_option synthInstance.maxSize 400 in\n +/-- Fiberwise orthonormalization of the sandwich POVM: for the placement pair\n +exhibited by the bipartition `e`, there is, for every point pair, a projective\n +measurement on the local space of the first placement whose placed distance to\n +the placed sandwich is at most `220` times the fourth root of the consistency\n +bound; on average over the point pair the distance is at most `220` times the\n +fourth root of the averaged bound. Both distances are squared distances.\n +This formalization-only auxiliary implements the application of `lem:ortho` in\n +the proof of `lem:qld-4-10`, paper\n +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:786-790`,\n +carried out for each point pair and averaged by Jensen's inequality. -/\n +theorem exists_projective_close_sandwich (hopp : p₁.IsOpposite p₂)\n +    (e : SixReg P S.toStrategy.ιA S.toStrategy.ιB ≃\n +      S.ExpandedLocalSpace p₁.side ×\n +        (S.ExpandedLocalSpace p₂.side × (PauliRegister P × PauliRegister P)))\n +    (he₁ : ∀ O : Op (S.ExpandedLocalSpace p₁.side),\n +      reindexOp e (heteroKron O\n +        (1 : Op (S.ExpandedLocalSpace p₂.side ×\n +          (PauliRegister P × PauliRegister P)))) = S.place p₁ O)\n +    (he₂ : ∀ O : Op (S.ExpandedLocalSpace p₂.side),\n +      reindexOp e (heteroKron (1 : Op (S.ExpandedLocalSpace p₁.side))\n +        (heteroKron O (1 : Op (PauliRegister P × PauliRegister P)))) =\n +          S.place p₂ O)\n +    :\n +    ∃ Q : PointPair P →\n +        Measurement (PauliScalar P × PauliScalar P) (S.ExpandedLocalSpace p₁.side),\n +      (∀ xz, MIPStarRE.QPBT.Measurement.IsProjective (Q xz)) ∧\n +        (∀ xz, ∑ ab : PauliScalar P × PauliScalar P, ‖applyOperatorToState\n +          (S.place p₁ ((Q xz).effect ab) -\n +            S.place p₁ ((S.sandwichPoint p₁.side xz.1 xz.2).effect ab))\n +          S.psiHat‖ ^ 2 ≤\n +          220 * Real.rpow (S.sandwichDefectBound p₁ p₂ xz) (1 / 4 : ℝ)) ∧\n +        opFamilyDistSq (uniformDistribution (PointPair P))\n +          (fun xz (ab : PauliScalar P × PauliScalar P) =>\n +            S.place p₁ ((Q xz).effect ab))\n +          (fun xz ab => S.place p₁ ((S.sandwichPoint p₁.side xz.1 xz.2).effect ab))\n +          S.psiHat ≤\n +          220 * Real.rpow (avgOver (uniformDistribution (PointPair P))\n +            (S.sandwichDefectBound p₁ p₂)) (1 / 4 : ℝ) := by\n +  classical\n +  have hψ : ‖reindexState e S.psiHat‖ = 1 := by\n +    rw [reindexState_norm_eq, psiHat_norm]\n +  have hxz : ∀ xz : PointPair P,\n +      ∃ Pm : Measurement (PauliScalar P × PauliScalar P)\n +        (S.ExpandedLocalSpace p₁.side),\n +        MIPStarRE.QPBT.Measurement.IsProjective Pm ∧\n +          ∑ ab : PauliScalar P × PauliScalar P, ‖applyOperatorToState\n +            (S.place p₁ (Pm.effect ab) -\n +              S.place p₁ ((S.sandwichPoint p₁.side xz.1 xz.2).effect ab))\n +            S.psiHat‖ ^ 2 ≤\n +            220 * Real.rpow (S.sandwichDefectBound p₁ p₂ xz) (1 / 4 : ℝ) := by\n +    intro xz\n +    have hcons : consistencyDefect (uniformDistribution Unit)\n +        (fun _ ab => heteroKron ((S.sandwichPoint p₁.side xz.1 xz.2).effect ab) 1)\n +        (fun _ ab => heteroKron 1\n +          ((leftPlacedMeasurement (ιB := PauliRegister P × PauliRegister P)\n +            (S.sandwichPoint p₂.side xz.1 xz.2)).effect ab))\n +        (reindexState e S.psiHat) ≤ S.sandwichDefectBound p₁ p₂ xz := by\n +      rw [consistencyDefect_reindex_eq S p₁ p₂ e he₁ he₂]\n +      exact S.sandwich_offDiagonal_le_sandwichDefectBound p₁ p₂ hopp xz\n +    obtain ⟨Pm, hPm, hdist⟩ := projective_rounding_with_explicit_constant\n +      (reindexState e S.psiHat) hψ (S.sandwichPoint p₁.side xz.1 xz.2)\n +      (leftPlacedMeasurement (ιB := PauliRegister P × PauliRegister P)\n +        (S.sandwichPoint p₂.side xz.1 xz.2))\n +      (S.sandwichDefectBound p₁ p₂ xz) (S.sandwichDefectBound_nonneg p₁ p₂ xz) hcons\n +    refine ⟨Pm, hPm, ?_⟩\n +    rw [opFamilyDistSq_reindex_left_eq S p₁ p₂ e he₁] at hdist\n +    exact hdist\n +  choose Q hQ using hxz\n +  refine ⟨Q, fun xz => (hQ xz).1, fun xz => (hQ xz).2, ?_⟩\n +  unfold opFamilyDistSq\n +  calc avgOver (uniformDistribution (PointPair P)) (fun xz =>\n +        ∑ ab : PauliScalar P × PauliScalar P, ‖applyOperatorToState\n +          (S.place p₁ ((Q xz).effect ab) -\n +            S.place p₁ ((S.sandwichPoint p₁.side xz.1 xz.2).effect ab))\n +          S.psiHat‖ ^ 2)\n +      ≤ avgOver (uniformDistribution (PointPair P)) (fun xz =>\n +          220 * Real.rpow (S.sandwichDefectBound p₁ p₂ xz) (1 / 4 : ℝ)) :=\n +        avgOver_mono _ _ _ fun xz => (hQ xz).2\n +    _ = 220 * avgOver (uniformDistribution (PointPair P)) (fun xz =>\n +          Real.rpow (S.sandwichDefectBound p₁ p₂ xz) (1 / 4 : ℝ)) :=\n +        avgOver_const_mul _ _ _\n +    _ ≤ 220 * Real.rpow (avgOver (uniformDistribution (PointPair P))\n +          (S.sandwichDefectBound p₁ p₂)) (1 / 4 : ℝ) := by\n +        refine mul_le_mul_of_nonneg_left ?_ (by norm_num)\n +        exact avgOver_rpow_quarter_le _ (uniformDistribution_weight_sum_le_one _) _\n +          (S.sandwichDefectBound_nonneg p₁ p₂)\n +\n +end Bipartition\n +\n +/-- Fiberwise orthonormalization on Alice's side, for the placement pair\n +`AA'`, `BA''`. -/\n +theorem exists_projective_close_sandwich_alice (S : ProjectiveSetting P ε) :\n +    ∃ Q : PointPair P →\n +        Measurement (PauliScalar P × PauliScalar P) (S.ExpandedLocalSpace .alice),\n +      (∀ xz, MIPStarRE.QPBT.Measurement.IsProjective (Q xz)) ∧\n +        (∀ xz, ∑ ab : PauliScalar P × PauliScalar P, ‖applyOperatorToState\n +          (S.place .AA' ((Q xz).effect ab) -\n +            S.place .AA' ((S.sandwichPoint .alice xz.1 xz.2).effect ab))\n +          S.psiHat‖ ^ 2 ≤\n +          220 * Real.rpow (S.sandwichDefectBound .AA' .BA'' xz) (1 / 4 : ℝ)) ∧\n +        opFamilyDistSq (uniformDistribution (PointPair P))\n +          (fun xz (ab : PauliScalar P × PauliScalar P) =>\n +            S.place .AA' ((Q xz).effect ab))\n +          (fun xz ab => S.place .AA' ((S.sandwichPoint .alice xz.1 xz.2).effect ab))\n +          S.psiHat ≤\n +          220 * Real.rpow (avgOver (uniformDistribution (PointPair P))\n +            (S.sandwichDefectBound .AA' .BA'')) (1 / 4 : ℝ) :=\n +  S.exists_projective_close_sandwich .AA' .BA'' trivial\n +    (aaBaBipartition P S.toStrategy.ιA S.toStrategy.ιB)\n +    (fun O => reindexOp_aaBaBipartition_left S O)\n +    (fun O => reindexOp_aaBaBipartition_right S O)\n +\n +/-- Fiberwise orthonormalization on Bob's side, for the placement pair\n +`BA''`, `AA'`. -/\n +theorem exists_projective_close_sandwich_bob (S : ProjectiveSetting P ε) :\n +    ∃ Q : PointPair P →\n +        Measurement (PauliScalar P × PauliScalar P) (S.ExpandedLocalSpace .bob),\n +      (∀ xz, MIPStarRE.QPBT.Measurement.IsProjective (Q xz)) ∧\n +        (∀ xz, ∑ ab : PauliScalar P × PauliScalar P, ‖applyOperatorToState\n +          (S.place .BA'' ((Q xz).effect ab) -\n +            S.place .BA'' ((S.sandwichPoint .bob xz.1 xz.2).effect ab))\n +          S.psiHat‖ ^ 2 ≤\n +          220 * Real.rpow (S.sandwichDefectBound .BA'' .AA' xz) (1 / 4 : ℝ)) ∧\n +        opFamilyDistSq (uniformDistribution (PointPair P))\n +          (fun xz (ab : PauliScalar P × PauliScalar P) =>\n +            S.place .BA'' ((Q xz).effect ab))\n +          (fun xz ab => S.place .BA'' ((S.sandwichPoint .bob xz.1 xz.2).effect ab))\n +          S.psiHat ≤\n +          220 * Real.rpow (avgOver (uniformDistribution (PointPair P))\n +            (S.sandwichDefectBound .BA'' .AA')) (1 / 4 : ℝ) :=\n +  S.exists_projective_close_sandwich .BA'' .AA' trivial\n +    (baAaBipartition P S.toStrategy.ιA S.toStrategy.ιB)\n +    (fun O => reindexOp_baAaBipartition_left S O)\n +    (fun O => reindexOp_baAaBipartition_right S O)\n +\n +end ProjectiveSetting\n +\n +end\n +\n +end MIPStarRE.QPBT\n++||||||| 1c5d5c16\n++=======\n+ import MIPStarRE.QPBT.Combining.Points.Consistency\n+ import MIPStarRE.QPBT.Games.DistanceTheorems\n+ \n+ /-!\n+ # Orthonormalization of the sandwich POVM\n+ \n+ For each fixed point pair `(x, z)`, the sandwich POVM `R^{x,z}` on one\n+ register placement is consistent with the sandwich POVM on the opposite\n+ placement, with the consistency defect bounded by\n+ `ProjectiveSetting.sandwichDefectBound`.  The orthonormalization lemma\n+ `lem:ortho`, in its explicit-constant form\n+ `projective_rounding_with_explicit_constant`, therefore produces a projective\n+ measurement `Q^{x,z}` on the original local space, within `220 · c^{1/4}` of\n+ `R^{x,z}` on the expanded state, where `c` is that bound.  Choosing such a\n+ measurement for every pair and averaging, the concavity of `t ↦ t^{1/4}`\n+ turns the average of the fiberwise errors into the same function of the\n+ average defect.\n+ \n+ The orthonormalization lemma is stated for a bipartite state whose first\n+ tensor factor carries the POVM to be rounded.  The two bipartitions used are\n+ `AA' | BA''(B'B'')`, for Alice's measurements, and `BA'' | AA'(B'B'')`, for\n+ Bob's; the second is introduced here.\n+ \n+ ## Main results\n+ \n+ * `baAaBipartition` with its two placement lemmas.\n+ * `avgOver_rpow_quarter_le`: Jensen's inequality for the fourth root.\n+ * `ProjectiveSetting.exists_projective_close_sandwich`: the fiberwise\n+   orthonormalization, for any bipartition exhibiting the two placements as\n+   the two tensor factors.\n+ \n+ ## References\n+ \n+ Paper `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:786-790`\n+ (the application of the orthonormalization lemma), blueprint\n+ `blueprint/src/chapter/ch15_qpbt_combining.tex:870-878` (`lem:qld-4-10`), and\n+ `blueprint/src/chapter/ch14_qpbt_observables.tex:395-464` (`lem:ortho`); the\n+ route is explained in `docs/paper-gaps/qpbt_combined-points-direct.tex`.\n+ -/\n+ \n+ open scoped BigOperators Matrix MatrixOrder ComplexOrder\n+ \n+ namespace MIPStarRE.QPBT\n+ \n+ open MIPStarRE.LDT hiding Measurement\n+ open MIPStarRE.Quantum DistanceCalculus\n+ \n+ noncomputable section\n+ \n+ /-! ## Jensen's inequality for the fourth root -/\n+ \n+ /-- The fourth root of a nonnegative real is the iterated square root. -/\n+ theorem rpow_quarter_eq_sqrt_sqrt {t : ℝ} (ht : 0 ≤ t) :\n+     Real.rpow t (1 / 4 : ℝ) = Real.sqrt (Real.sqrt t) := by\n+   rw [Real.sqrt_eq_rpow, Real.sqrt_eq_rpow, ← Real.rpow_mul ht]\n+   norm_num\n+ \n+ /-- Jensen's inequality for the concave function `t ↦ t^{1/4}` on a\n+ sub-probability average, obtained by applying the square-root inequality\n+ twice. -/\n+ theorem avgOver_rpow_quarter_le {X : Type*} (𝒟 : Distribution X)\n+     (h𝒟 : ∑ x ∈ 𝒟.support, 𝒟.weight x ≤ 1) (b : X → ℝ) (hb : ∀ x, 0 ≤ b x) :\n+     avgOver 𝒟 (fun x => Real.rpow (b x) (1 / 4 : ℝ)) ≤\n+       Real.rpow (avgOver 𝒟 b) (1 / 4 : ℝ) := by\n+   have h1 : |avgOver 𝒟 (fun x => Real.sqrt (Real.sqrt (b x)))| ≤\n+       Real.sqrt (avgOver 𝒟 (fun x => Real.sqrt (b x))) :=\n+     MIPStarRE.LDT.Preliminaries.avgOver_abs_le_sqrt_of_pointwise 𝒟 _ _\n+       (fun x => by rw [abs_of_nonneg (Real.sqrt_nonneg _)])\n+       (fun x => Real.sqrt_nonneg _) h𝒟\n+   have h2 : |avgOver 𝒟 (fun x => Real.sqrt (b x))| ≤ Real.sqrt (avgOver 𝒟 b) :=\n+     MIPStarRE.LDT.Preliminaries.avgOver_abs_le_sqrt_of_pointwise 𝒟 _ _\n+       (fun x => by rw [abs_of_nonneg (Real.sqrt_nonneg _)]) hb h𝒟\n+   have havg : 0 ≤ avgOver 𝒟 b := avgOver_nonneg 𝒟 b hb\n+   rw [rpow_quarter_eq_sqrt_sqrt havg]\n+   calc avgOver 𝒟 (fun x => Real.rpow (b x) (1 / 4 : ℝ))\n+       = avgOver 𝒟 (fun x => Real.sqrt (Real.sqrt (b x))) :=\n+         avgOver_congr _ _ _ fun x => rpow_quarter_eq_sqrt_sqrt (hb x)\n+     _ ≤ |avgOver 𝒟 (fun x => Real.sqrt (Real.sqrt (b x)))| := le_abs_self _\n+     _ ≤ Real.sqrt (avgOver 𝒟 (fun x => Real.sqrt (b x))) := h1\n+     _ ≤ Real.sqrt (Real.sqrt (avgOver 𝒟 b)) :=\n+         Real.sqrt_le_sqrt (le_trans (le_abs_self _) h2)\n+ \n+ /-! ## The bipartition with Bob's registers first -/\n+ \n+ /-- Regroup `AA'A''BB'B''` as `BA'' | AA'(B'B'')`.  This is the bipartition\n+ in which Bob's expanded local space is the first tensor factor, used to\n+ orthonormalize the sandwich POVM on Bob's side. -/\n+ def baAaBipartition (P : AdmissibleParams) (ιA ιB : Type*) :\n+     SixReg P ιA ιB ≃\n+       (ιB × PauliRegister P) ×\n+         ((ιA × PauliRegister P) × (PauliRegister P × PauliRegister P)) where\n+   toFun := fun ⟨⟨a, a', a''⟩, b, b', b''⟩ => ((b, a''), ((a, a'), (b', b'')))\n+   invFun := fun ⟨⟨b, a''⟩, ⟨a, a'⟩, b', b''⟩ => ((a, (a', a'')), (b, (b', b'')))\n+   left_inv := by rintro ⟨⟨a, a', a''⟩, b, b', b''⟩; rfl\n+   right_inv := by rintro ⟨⟨b, a''⟩, ⟨a, a'⟩, b', b''⟩; rfl\n+ \n+ namespace ProjectiveSetting\n+ \n+ variable {P : AdmissibleParams} {ε : ℝ}\n+ \n+ /-- Under the `BA'' | AA'(B'B'')` bipartition, a `BA''` placement is the\n+ ordinary left tensor placement. -/\n+ theorem reindexOp_baAaBipartition_left (S : ProjectiveSetting P ε)\n+     (O : Op (S.ExpandedLocalSpace Placement.BA''.side)) :\n+     reindexOp (baAaBipartition P S.toStrategy.ιA S.toStrategy.ιB)\n+         (heteroKron O\n+           (1 : Op ((S.toStrategy.ιA × PauliRegister P) ×\n+             (PauliRegister P × PauliRegister P)))) =\n+       S.place .BA'' O := by\n+   ext i j\n+   obtain ⟨⟨a, a', a''⟩, b, b', b''⟩ := i\n+   obtain ⟨⟨c, c', c''⟩, d, d', d''⟩ := j\n+   simp only [reindexOp, Matrix.reindex_apply, Matrix.submatrix_apply,\n+     Equiv.symm_symm, place, baAaBipartition, Equiv.coe_fn_mk, heteroKron,\n+     Matrix.kronecker, Matrix.kroneckerMap_apply, Matrix.one_apply, Prod.mk.injEq]\n+   split_ifs\n+   all_goals simp_all\n+   all_goals rfl\n+ \n+ /-- Under the `BA'' | AA'(B'B'')` bipartition, an `AA'` placement is the\n+ ordinary right tensor placement, with identity on the unused EPR pair. -/\n+ theorem reindexOp_baAaBipartition_right (S : ProjectiveSetting P ε)\n+     (O : Op (S.ExpandedLocalSpace Placement.AA'.side)) :\n+     reindexOp (baAaBipartition P S.toStrategy.ιA S.toStrategy.ιB)\n+         (heteroKron (1 : Op (S.toStrategy.ιB × PauliRegister P))\n+           (heteroKron O (1 : Op (PauliRegister P × PauliRegister P)))) =\n+       S.place .AA' O := by\n+   ext i j\n+   obtain ⟨⟨a, a', a''⟩, b, b', b''⟩ := i\n+   obtain ⟨⟨c, c', c''⟩, d, d', d''⟩ := j\n+   simp only [reindexOp, Matrix.reindex_apply, Matrix.submatrix_apply,\n+     Equiv.symm_symm, place, baAaBipartition, Equiv.coe_fn_mk, heteroKron,\n+     Matrix.kronecker, Matrix.kroneckerMap_apply, Matrix.one_apply, Prod.mk.injEq]\n+   split_ifs\n+   all_goals simp_all\n+   all_goals rfl\n+ \n+ /-! ## Transport along a bipartition -/\n+ \n+ section Bipartition\n+ \n+ variable (S : ProjectiveSetting P ε) (p₁ p₂ : Placement)\n+ \n+ set_option synthInstance.maxSize 400 in\n+ /-- The consistency defect of two placed POVMs, read in the bipartite picture\n+ of the reindexed expanded state, is their off-diagonal mass in the expanded\n+ state. -/\n+ theorem consistencyDefect_reindex_eq {α : Type*} [Fintype α] [DecidableEq α]\n+     (e : SixReg P S.toStrategy.ιA S.toStrategy.ιB ≃\n+       S.ExpandedLocalSpace p₁.side ×\n+         (S.ExpandedLocalSpace p₂.side × (PauliRegister P × PauliRegister P)))\n+     (he₁ : ∀ O : Op (S.ExpandedLocalSpace p₁.side),\n+       reindexOp e (heteroKron O\n+         (1 : Op (S.ExpandedLocalSpace p₂.side ×\n+           (PauliRegister P × PauliRegister P)))) = S.place p₁ O)\n+     (he₂ : ∀ O : Op (S.ExpandedLocalSpace p₂.side),\n+       reindexOp e (heteroKron (1 : Op (S.ExpandedLocalSpace p₁.side))\n+         (heteroKron O (1 : Op (PauliRegister P × PauliRegister P)))) =\n+           S.place p₂ O)\n+     (Q : Measurement α (S.ExpandedLocalSpace p₁.side))\n+     (R : Measurement α (S.ExpandedLocalSpace p₂.side)) :\n+     consistencyDefect (uniformDistribution Unit)\n+         (fun _ a => heteroKron (Q.effect a) 1)\n+         (fun _ a => heteroKron 1\n+           ((leftPlacedMeasurement (ιB := PauliRegister P × PauliRegister P) R).effect a))\n+         (reindexState e S.psiHat) =\n+       ∑ a : α, ∑ b : α, if a = b then 0 else\n+         stateQForm S.psiHat (S.place p₁ (Q.effect a) * S.place p₂ (R.effect b)) := by\n+   classical\n+   unfold consistencyDefect\n+   rw [avgOver_uniform_const]\n+   refine Finset.sum_congr rfl fun a _ => Finset.sum_congr rfl fun b _ => ?_\n+   by_cases hab : a = b\n+   · simp [hab]\n+   · rw [if_neg hab, if_neg hab, consistency_term_eq_stateQForm,\n+       WinImplications.stateQForm_reindexState, WinImplications.reindexOp_mul, he₁]\n+     change stateQForm S.psiHat (S.place p₁ (Q.effect a) *\n+       reindexOp e (heteroKron 1 (heteroKron (R.effect b) 1))) = _\n+     rw [he₂]\n+ \n+ set_option synthInstance.maxSize 400 in\n+ /-- The state-dependent distance of two families placed on the first factor,\n+ read in the bipartite picture, is their placed distance in the expanded\n+ state. -/\n+ theorem opFamilyDistSq_reindex_left_eq {α : Type*} [Fintype α]\n+     (e : SixReg P S.toStrategy.ιA S.toStrategy.ιB ≃\n+       S.ExpandedLocalSpace p₁.side ×\n+         (S.ExpandedLocalSpace p₂.side × (PauliRegister P × PauliRegister P)))\n+     (he₁ : ∀ O : Op (S.ExpandedLocalSpace p₁.side),\n+       reindexOp e (heteroKron O\n+         (1 : Op (S.ExpandedLocalSpace p₂.side ×\n+           (PauliRegister P × PauliRegister P)))) = S.place p₁ O)\n+     (A B : α → Op (S.ExpandedLocalSpace p₁.side)) :\n+     opFamilyDistSq (uniformDistribution Unit)\n+         (fun _ a => heteroKron (A a) 1) (fun _ a => heteroKron (B a) 1)\n+         (reindexState e S.psiHat) =\n+       ∑ a : α, ‖applyOperatorToState (S.place p₁ (A a) - S.place p₁ (B a))\n+         S.psiHat‖ ^ 2 := by\n+   classical\n+   unfold opFamilyDistSq\n+   rw [avgOver_uniform_const]\n+   refine Finset.sum_congr rfl fun a _ => ?_\n+   rw [WinImplications.norm_applyOperatorToState_reindexState,\n+     WinImplications.reindexOp_sub, he₁, he₁]\n+ \n+ set_option synthInstance.maxSize 400 in\n+ /-- Fiberwise orthonormalization of the sandwich POVM: for the placement pair\n+ exhibited by the bipartition `e`, there is, for every point pair, a projective\n+ measurement on the local space of the first placement whose placed distance to\n+ the placed sandwich is at most `220` times the fourth root of the consistency\n+ bound; on average over the point pair the distance is at most `220` times the\n+ fourth root of the averaged bound.  This is the application of `lem:ortho` in\n+ the proof of `lem:qld-4-10`, paper\n+ `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:786-790`,\n+ carried out for each point pair and averaged by Jensen's inequality. -/\n+ theorem exists_projective_close_sandwich (hopp : p₁.IsOpposite p₂)\n+     (e : SixReg P S.toStrategy.ιA S.toStrategy.ιB ≃\n+       S.ExpandedLocalSpace p₁.side ×\n+         (S.ExpandedLocalSpace p₂.side × (PauliRegister P × PauliRegister P)))\n+     (he₁ : ∀ O : Op (S.ExpandedLocalSpace p₁.side),\n+       reindexOp e (heteroKron O\n+         (1 : Op (S.ExpandedLocalSpace p₂.side ×\n+           (PauliRegister P × PauliRegister P)))) = S.place p₁ O)\n+     (he₂ : ∀ O : Op (S.ExpandedLocalSpace p₂.side),\n+       reindexOp e (heteroKron (1 : Op (S.ExpandedLocalSpace p₁.side))\n+         (heteroKron O (1 : Op (PauliRegister P × PauliRegister P)))) =\n+           S.place p₂ O)\n+     :\n+     ∃ Q : PointPair P →\n+         Measurement (PauliScalar P × PauliScalar P) (S.ExpandedLocalSpace p₁.side),\n+       (∀ xz, MIPStarRE.QPBT.Measurement.IsProjective (Q xz)) ∧\n+         opFamilyDistSq (uniformDistribution (PointPair P))\n+           (fun xz (ab : PauliScalar P × PauliScalar P) =>\n+             S.place p₁ ((Q xz).effect ab))\n+           (fun xz ab => S.place p₁ ((S.sandwichPoint p₁.side xz.1 xz.2).effect ab))\n+           S.psiHat ≤\n+           220 * Real.rpow (avgOver (uniformDistribution (PointPair P))\n+             (S.sandwichDefectBound p₁ p₂)) (1 / 4 : ℝ) := by\n+   classical\n+   have hψ : ‖reindexState e S.psiHat‖ = 1 := by\n+     rw [reindexState_norm_eq, psiHat_norm]\n+   have hxz : ∀ xz : PointPair P,\n+       ∃ Pm : Measurement (PauliScalar P × PauliScalar P)\n+         (S.ExpandedLocalSpace p₁.side),\n+         MIPStarRE.QPBT.Measurement.IsProjective Pm ∧\n+           ∑ ab : PauliScalar P × PauliScalar P, ‖applyOperatorToState\n+             (S.place p₁ (Pm.effect ab) -\n+               S.place p₁ ((S.sandwichPoint p₁.side xz.1 xz.2).effect ab))\n+             S.psiHat‖ ^ 2 ≤\n+             220 * Real.rpow (S.sandwichDefectBound p₁ p₂ xz) (1 / 4 : ℝ) := by\n+     intro xz\n+     have hcons : consistencyDefect (uniformDistribution Unit)\n+         (fun _ ab => heteroKron ((S.sandwichPoint p₁.side xz.1 xz.2).effect ab) 1)\n+         (fun _ ab => heteroKron 1\n+           ((leftPlacedMeasurement (ιB := PauliRegister P × PauliRegister P)\n+             (S.sandwichPoint p₂.side xz.1 xz.2)).effect ab))\n+         (reindexState e S.psiHat) ≤ S.sandwichDefectBound p₁ p₂ xz := by\n+       rw [consistencyDefect_reindex_eq S p₁ p₂ e he₁ he₂]\n+       exact S.sandwich_offDiagonal_le_sandwichDefectBound p₁ p₂ hopp xz\n+     obtain ⟨Pm, hPm, hdist⟩ := projective_rounding_with_explicit_constant\n+       (reindexState e S.psiHat) hψ (S.sandwichPoint p₁.side xz.1 xz.2)\n+       (leftPlacedMeasurement (ιB := PauliRegister P × PauliRegister P)\n+         (S.sandwichPoint p₂.side xz.1 xz.2))\n+       (S.sandwichDefectBound p₁ p₂ xz) (S.sandwichDefectBound_nonneg p₁ p₂ xz) hcons\n+     refine ⟨Pm, hPm, ?_⟩\n+     rw [opFamilyDistSq_reindex_left_eq S p₁ p₂ e he₁] at hdist\n+     exact hdist\n+   choose Q hQ using hxz\n+   refine ⟨Q, fun xz => (hQ xz).1, ?_⟩\n+   unfold opFamilyDistSq\n+   calc avgOver (uniformDistribution (PointPair P)) (fun xz =>\n+         ∑ ab : PauliScalar P × PauliScalar P, ‖applyOperatorToState\n+           (S.place p₁ ((Q xz).effect ab) -\n+             S.place p₁ ((S.sandwichPoint p₁.side xz.1 xz.2).effect ab))\n+           S.psiHat‖ ^ 2)\n+       ≤ avgOver (uniformDistribution (PointPair P)) (fun xz =>\n+           220 * Real.rpow (S.sandwichDefectBound p₁ p₂ xz) (1 / 4 : ℝ)) :=\n+         avgOver_mono _ _ _ fun xz => (hQ xz).2\n+     _ = 220 * avgOver (uniformDistribution (PointPair P)) (fun xz =>\n+           Real.rpow (S.sandwichDefectBound p₁ p₂ xz) (1 / 4 : ℝ)) :=\n+         avgOver_const_mul _ _ _\n+     _ ≤ 220 * Real.rpow (avgOver (uniformDistribution (PointPair P))\n+           (S.sandwichDefectBound p₁ p₂)) (1 / 4 : ℝ) := by\n+         refine mul_le_mul_of_nonneg_left ?_ (by norm_num)\n+         exact avgOver_rpow_quarter_le _ (uniformDistribution_weight_sum_le_one _) _\n+           (S.sandwichDefectBound_nonneg p₁ p₂)\n+ \n+ end Bipartition\n+ \n+ /-- Fiberwise orthonormalization on Alice's side, for the placement pair\n+ `AA'`, `BA''`. -/\n+ theorem exists_projective_close_sandwich_alice (S : ProjectiveSetting P ε) :\n+     ∃ Q : PointPair P →\n+         Measurement (PauliScalar P × PauliScalar P) (S.ExpandedLocalSpace .alice),\n+       (∀ xz, MIPStarRE.QPBT.Measurement.IsProjective (Q xz)) ∧\n+         opFamilyDistSq (uniformDistribution (PointPair P))\n+           (fun xz (ab : PauliScalar P × PauliScalar P) =>\n+             S.place .AA' ((Q xz).effect ab))\n+           (fun xz ab => S.place .AA' ((S.sandwichPoint .alice xz.1 xz.2).effect ab))\n+           S.psiHat ≤\n+           220 * Real.rpow (avgOver (uniformDistribution (PointPair P))\n+             (S.sandwichDefectBound .AA' .BA'')) (1 / 4 : ℝ) :=\n+   S.exists_projective_close_sandwich .AA' .BA'' trivial\n+     (aaBaBipartition P S.toStrategy.ιA S.toStrategy.ιB)\n+     (fun O => reindexOp_aaBaBipartition_left S O)\n+     (fun O => reindexOp_aaBaBipartition_right S O)\n+ \n+ /-- Fiberwise orthonormalization on Bob's side, for the placement pair\n+ `BA''`, `AA'`. -/\n+ theorem exists_projective_close_sandwich_bob (S : ProjectiveSetting P ε) :\n+     ∃ Q : PointPair P →\n+         Measurement (PauliScalar P × PauliScalar P) (S.ExpandedLocalSpace .bob),\n+       (∀ xz, MIPStarRE.QPBT.Measurement.IsProjective (Q xz)) ∧\n+         opFamilyDistSq (uniformDistribution (PointPair P))\n+           (fun xz (ab : PauliScalar P × PauliScalar P) =>\n+             S.place .BA'' ((Q xz).effect ab))\n+           (fun xz ab => S.place .BA'' ((S.sandwichPoint .bob xz.1 xz.2).effect ab))\n+           S.psiHat ≤\n+           220 * Real.rpow (avgOver (uniformDistribution (PointPair P))\n+             (S.sandwichDefectBound .BA'' .AA')) (1 / 4 : ℝ) :=\n+   S.exists_projective_close_sandwich .BA'' .AA' trivial\n+     (baAaBipartition P S.toStrategy.ιA S.toStrategy.ιB)\n+     (fun O => reindexOp_baAaBipartition_left S O)\n+     (fun O => reindexOp_baAaBipartition_right S O)\n+ \n+ end ProjectiveSetting\n+ \n+ end\n+ \n+ end MIPStarRE.QPBT\n++>>>>>>> github/main\ndiff --cc MIPStarRE/QPBT/Combining/Points/Placement.lean\nindex 74344631,85e87416..00000000\n--- a/MIPStarRE/QPBT/Combining/Points/Placement.lean\n+++ b/MIPStarRE/QPBT/Combining/Points/Placement.lean\n@@@ -1,402 -1,401 +1,807 @@@\n++<<<<<<< HEAD\n +import MIPStarRE.QPBT.Observables.PointConsistency\n +\n +/-!\n +# Placement calculus on the expanded state\n +\n +This module records the algebra of the four register placements used by the\n +combining argument: a placement is a unital `*`-homomorphism, placements on\n +opposite register pairs commute, and the crosswise exchange of the two EPR\n +pairs of the expanded state carries the placement `AA'` to `AB''` and `BA''`\n +to `BB'` while fixing the expanded state.  The last fact transfers every\n +state-dependent distance between the two bipartition schemes of\n +`def:symmetric-equivalents` without assuming a symmetric strategy.\n +\n +## References\n +\n +The placements are those of blueprint `def:symmetric-equivalents`, paper\n +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:420-450`.\n +The crosswise EPR exchange is proved independently in blueprint\n +`lem:qld-placement-transfer` using only the symmetry of the EPR vectors;\n +its use for `lem:qld-4-10` is analyzed in\n +`docs/paper-gaps/qpbt_linearity-theorem-quotation.tex`.\n +-/\n +\n +open scoped BigOperators Matrix MatrixOrder ComplexOrder\n +\n +namespace MIPStarRE.QPBT\n +\n +open MIPStarRE.LDT hiding Measurement\n +open MIPStarRE.Quantum\n +\n +noncomputable section\n +\n +namespace ProjectiveSetting\n +\n +variable {P : AdmissibleParams} {ε : ℝ}\n +\n +/-! ## Placements as reindexed tensor factors -/\n +\n +/-- The `AA'` placement is the reindexed left factor of the\n +`AA' | BA''(B'B'')` bipartition. -/\n +theorem place_AA'_eq (S : ProjectiveSetting P ε)\n +    (O : Op (S.ExpandedLocalSpace Placement.AA'.side)) :\n +    S.place .AA' O =\n +      reindexOp (aaBaBipartition P S.toStrategy.ιA S.toStrategy.ιB)\n +        (heteroKron O\n +          (1 : Op ((S.toStrategy.ιB × PauliRegister P) ×\n +            (PauliRegister P × PauliRegister P)))) :=\n +  (reindexOp_aaBaBipartition_left S O).symm\n +\n +/-- The `BA''` placement is the reindexed right factor of the\n +`AA' | BA''(B'B'')` bipartition. -/\n +theorem place_BA''_eq (S : ProjectiveSetting P ε)\n +    (O : Op (S.ExpandedLocalSpace Placement.BA''.side)) :\n +    S.place .BA'' O =\n +      reindexOp (aaBaBipartition P S.toStrategy.ιA S.toStrategy.ιB)\n +        (heteroKron (1 : Op (S.toStrategy.ιA × PauliRegister P))\n +          (heteroKron O (1 : Op (PauliRegister P × PauliRegister P)))) :=\n +  (reindexOp_aaBaBipartition_right S O).symm\n +\n +/-- The `AB''` placement is the reindexed left factor of the\n +`AB'' | BB'(A'A'')` bipartition. -/\n +theorem place_AB''_eq (S : ProjectiveSetting P ε)\n +    (O : Op (S.ExpandedLocalSpace Placement.AB''.side)) :\n +    S.place .AB'' O =\n +      reindexOp (abBbBipartition P S.toStrategy.ιA S.toStrategy.ιB)\n +        (heteroKron O\n +          (1 : Op ((S.toStrategy.ιB × PauliRegister P) ×\n +            (PauliRegister P × PauliRegister P)))) :=\n +  (reindexOp_abBbBipartition_left S O).symm\n +\n +/-- The `BB'` placement is the reindexed right factor of the\n +`AB'' | BB'(A'A'')` bipartition. -/\n +theorem place_BB'_eq (S : ProjectiveSetting P ε)\n +    (O : Op (S.ExpandedLocalSpace Placement.BB'.side)) :\n +    S.place .BB' O =\n +      reindexOp (abBbBipartition P S.toStrategy.ιA S.toStrategy.ιB)\n +        (heteroKron (1 : Op (S.toStrategy.ιA × PauliRegister P))\n +          (heteroKron O (1 : Op (PauliRegister P × PauliRegister P)))) :=\n +  (reindexOp_abBbBipartition_right S O).symm\n +\n +/-- Reindexing an operator commutes with the conjugate transpose. -/\n +theorem reindexOp_conjTranspose {ι κ : Type*} (e : ι ≃ κ) (M : Op κ) :\n +    reindexOp e Mᴴ = (reindexOp e M)ᴴ := by\n +  ext i j\n +  rfl\n +\n +/-- Reindexing an operator along an equivalence preserves positivity. -/\n +theorem reindexOp_nonneg {ι κ : Type*} [Finite ι] [Finite κ]\n +    (e : ι ≃ κ) {M : Op κ} (hM : 0 ≤ M) :\n +    0 ≤ reindexOp e M := by\n +  letI := Fintype.ofFinite ι\n +  letI := Fintype.ofFinite κ\n +  rw [Matrix.nonneg_iff_posSemidef] at hM ⊢\n +  exact hM.submatrix e.symm.symm\n +\n +/-! ## The placement is a unital `*`-homomorphism -/\n +\n +set_option synthInstance.maxSize 400 in\n +/-- A placement is multiplicative. -/\n +theorem place_mul (S : ProjectiveSetting P ε) :\n +    ∀ (p : Placement) (A B : Op (S.ExpandedLocalSpace p.side)),\n +      S.place p (A * B) = S.place p A * S.place p B\n +  | .AA', A, B => by\n +      classical\n +      rw [place_AA'_eq, place_AA'_eq, place_AA'_eq,\n +        ← WinImplications.reindexOp_mul, heteroKron_mul, mul_one]\n +      all_goals rfl\n +  | .BA'', A, B => by\n +      classical\n +      rw [place_BA''_eq, place_BA''_eq, place_BA''_eq,\n +        ← WinImplications.reindexOp_mul, heteroKron_mul, heteroKron_mul,\n +        mul_one, mul_one]\n +      all_goals rfl\n +  | .BB', A, B => by\n +      classical\n +      rw [place_BB'_eq, place_BB'_eq, place_BB'_eq,\n +        ← WinImplications.reindexOp_mul, heteroKron_mul, heteroKron_mul,\n +        mul_one, mul_one]\n +      all_goals rfl\n +  | .AB'', A, B => by\n +      classical\n +      rw [place_AB''_eq, place_AB''_eq, place_AB''_eq,\n +        ← WinImplications.reindexOp_mul, heteroKron_mul, mul_one]\n +      all_goals rfl\n +\n +/-- A placement sends the local identity to the identity of the six-register\n +space. -/\n +theorem place_one (S : ProjectiveSetting P ε) (p : Placement) :\n +    S.place p (1 : Op (S.ExpandedLocalSpace p.side)) = 1 := by\n +  ext i j\n +  cases p <;>\n +    · simp only [ProjectiveSetting.place, Matrix.one_apply, Prod.ext_iff]\n +      split_ifs <;> simp_all\n +\n +/-- A placement is additive over finite sums of local operators. -/\n +theorem place_finsetSum (S : ProjectiveSetting P ε) (p : Placement) {γ : Type*}\n +    (s : Finset γ) (O : γ → Op (S.ExpandedLocalSpace p.side)) :\n +    S.place p (∑ x ∈ s, O x) = ∑ x ∈ s, S.place p (O x) := by\n +  ext i j\n +  cases p <;>\n +    simp only [ProjectiveSetting.place, Matrix.sum_apply, Finset.sum_mul,\n +      Finset.mul_sum]\n +\n +/-- A placement commutes with the conjugate transpose. -/\n +theorem place_conjTranspose (S : ProjectiveSetting P ε) :\n +    ∀ (p : Placement) (A : Op (S.ExpandedLocalSpace p.side)),\n +      S.place p Aᴴ = (S.place p A)ᴴ\n +  | .AA', A => by\n +      rw [place_AA'_eq, place_AA'_eq, ← reindexOp_conjTranspose,\n +        WinImplications.heteroKron_conjTranspose, Matrix.conjTranspose_one]\n +      all_goals rfl\n +  | .BA'', A => by\n +      rw [place_BA''_eq, place_BA''_eq, ← reindexOp_conjTranspose,\n +        WinImplications.heteroKron_conjTranspose,\n +        WinImplications.heteroKron_conjTranspose, Matrix.conjTranspose_one,\n +        Matrix.conjTranspose_one]\n +      all_goals rfl\n +  | .BB', A => by\n +      rw [place_BB'_eq, place_BB'_eq, ← reindexOp_conjTranspose,\n +        WinImplications.heteroKron_conjTranspose,\n +        WinImplications.heteroKron_conjTranspose, Matrix.conjTranspose_one,\n +        Matrix.conjTranspose_one]\n +      all_goals rfl\n +  | .AB'', A => by\n +      rw [place_AB''_eq, place_AB''_eq, ← reindexOp_conjTranspose,\n +        WinImplications.heteroKron_conjTranspose, Matrix.conjTranspose_one]\n +      all_goals rfl\n +\n +set_option synthInstance.maxSize 400 in\n +/-- A placement preserves positivity. -/\n +theorem place_nonneg (S : ProjectiveSetting P ε) :\n +    ∀ (p : Placement) {A : Op (S.ExpandedLocalSpace p.side)}, 0 ≤ A →\n +      0 ≤ S.place p A\n +  | .AA', A, hA => by\n +      classical\n +      rw [place_AA'_eq]\n +      exact reindexOp_nonneg _ (MIPStarRE.Quantum.kronecker_nonneg hA\n +        (Matrix.PosSemidef.one.nonneg))\n +  | .BA'', A, hA => by\n +      classical\n +      rw [place_BA''_eq]\n +      exact reindexOp_nonneg _ (MIPStarRE.Quantum.kronecker_nonneg\n +        (Matrix.PosSemidef.one.nonneg)\n +        (MIPStarRE.Quantum.kronecker_nonneg hA (Matrix.PosSemidef.one.nonneg)))\n +  | .BB', A, hA => by\n +      classical\n +      rw [place_BB'_eq]\n +      exact reindexOp_nonneg _ (MIPStarRE.Quantum.kronecker_nonneg\n +        (Matrix.PosSemidef.one.nonneg)\n +        (MIPStarRE.Quantum.kronecker_nonneg hA (Matrix.PosSemidef.one.nonneg)))\n +  | .AB'', A, hA => by\n +      classical\n +      rw [place_AB''_eq]\n +      exact reindexOp_nonneg _ (MIPStarRE.Quantum.kronecker_nonneg hA\n +        (Matrix.PosSemidef.one.nonneg))\n +\n +/-- The placement of a local operator bounded by the identity is bounded by\n +the identity. -/\n +theorem place_le_one (S : ProjectiveSetting P ε) (p : Placement)\n +    {A : Op (S.ExpandedLocalSpace p.side)} (hA : A ≤ 1) :\n +    S.place p A ≤ 1 := by\n +  have h : 0 ≤ S.place p (1 - A) := S.place_nonneg p (sub_nonneg.mpr hA)\n +  rw [place_sub, place_one] at h\n +  exact sub_nonneg.mp h\n +\n +/-- The placement of a projector is a contraction. -/\n +theorem place_conjTranspose_mul_self_le_one (S : ProjectiveSetting P ε)\n +    (p : Placement) {E : Op (S.ExpandedLocalSpace p.side)} (hE : IsProj E) :\n +    (S.place p E)ᴴ * S.place p E ≤ 1 := by\n +  rw [← place_conjTranspose, ← place_mul, hE.isSelfAdjoint.isHermitian.eq,\n +    hE.isIdempotentElem.eq]\n +  exact S.place_le_one p (sub_nonneg.mp hE.one_sub.nonneg)\n +\n +set_option synthInstance.maxSize 400 in\n +/-- Operators placed on opposite register pairs commute. -/\n +theorem place_comm (S : ProjectiveSetting P ε) :\n +    ∀ (p₁ p₂ : Placement), p₁.IsOpposite p₂ →\n +      ∀ (A : Op (S.ExpandedLocalSpace p₁.side))\n +        (B : Op (S.ExpandedLocalSpace p₂.side)),\n +        S.place p₁ A * S.place p₂ B = S.place p₂ B * S.place p₁ A\n +  | .AA', .BA'', _, A, B => by\n +      classical\n +      rw [place_AA'_eq, place_BA''_eq, ← WinImplications.reindexOp_mul,\n +        ← WinImplications.reindexOp_mul]\n +      simp only [heteroKron_mul, one_mul, mul_one]\n +  | .BA'', .AA', _, A, B => by\n +      classical\n +      rw [place_AA'_eq, place_BA''_eq, ← WinImplications.reindexOp_mul,\n +        ← WinImplications.reindexOp_mul]\n +      simp only [heteroKron_mul, one_mul, mul_one]\n +  | .BB', .AB'', _, A, B => by\n +      classical\n +      rw [place_AB''_eq, place_BB'_eq, ← WinImplications.reindexOp_mul,\n +        ← WinImplications.reindexOp_mul]\n +      simp only [heteroKron_mul, one_mul, mul_one]\n +  | .AB'', .BB', _, A, B => by\n +      classical\n +      rw [place_AB''_eq, place_BB'_eq, ← WinImplications.reindexOp_mul,\n +        ← WinImplications.reindexOp_mul]\n +      simp only [heteroKron_mul, one_mul, mul_one]\n +  | .AA', .AA', h, _, _ => by simp [Placement.IsOpposite] at h\n +  | .AA', .BB', h, _, _ => by simp [Placement.IsOpposite] at h\n +  | .AA', .AB'', h, _, _ => by simp [Placement.IsOpposite] at h\n +  | .BA'', .BA'', h, _, _ => by simp [Placement.IsOpposite] at h\n +  | .BA'', .BB', h, _, _ => by simp [Placement.IsOpposite] at h\n +  | .BA'', .AB'', h, _, _ => by simp [Placement.IsOpposite] at h\n +  | .BB', .AA', h, _, _ => by simp [Placement.IsOpposite] at h\n +  | .BB', .BA'', h, _, _ => by simp [Placement.IsOpposite] at h\n +  | .BB', .BB', h, _, _ => by simp [Placement.IsOpposite] at h\n +  | .AB'', .AA', h, _, _ => by simp [Placement.IsOpposite] at h\n +  | .AB'', .BA'', h, _, _ => by simp [Placement.IsOpposite] at h\n +  | .AB'', .AB'', h, _, _ => by simp [Placement.IsOpposite] at h\n +\n +/-- A complete measurement on a local expanded space, placed on one of the\n +four register pairs, is a complete measurement on the six-register space. -/\n +def placedMeasurement (S : ProjectiveSetting P ε) (p : Placement) {α : Type*}\n +    [Fintype α] (M : Measurement α (S.ExpandedLocalSpace p.side)) :\n +    Measurement α (SixReg P S.toStrategy.ιA S.toStrategy.ιB) :=\n +  Measurement.ofSumEqOne (fun a => S.place p (M.effect a))\n +    (fun a => S.place_nonneg p (M.pos a))\n +    (by rw [← place_finsetSum, M.sum_eq_one, place_one])\n +\n +/-- The effects of a placed measurement are the placed effects. -/\n +@[simp] theorem placedMeasurement_effect (S : ProjectiveSetting P ε)\n +    (p : Placement) {α : Type*} [Fintype α]\n +    (M : Measurement α (S.ExpandedLocalSpace p.side)) (a : α) :\n +    (S.placedMeasurement p M).effect a = S.place p (M.effect a) := rfl\n +\n +/-- A placed projective measurement is projective. -/\n +theorem placedMeasurement_isProjective (S : ProjectiveSetting P ε)\n +    (p : Placement) {α : Type*} [Fintype α]\n +    (M : Measurement α (S.ExpandedLocalSpace p.side))\n +    (hM : MIPStarRE.QPBT.Measurement.IsProjective M) :\n +    MIPStarRE.QPBT.Measurement.IsProjective (S.placedMeasurement p M) := by\n +  intro a\n +  refine isStarProjection_iff'.2 ⟨?_, ?_⟩\n +  · change S.place p (M.effect a) * S.place p (M.effect a) =\n +      S.place p (M.effect a)\n +    rw [← place_mul, (hM a).isIdempotentElem.eq]\n +  · change star (S.place p (M.effect a)) = S.place p (M.effect a)\n +    rw [Matrix.star_eq_conjTranspose, ← place_conjTranspose,\n +      (hM a).isSelfAdjoint.isHermitian.eq]\n +\n +/-! ## The crosswise exchange of the two EPR pairs -/\n +\n +/-- The involution of the six registers exchanging `A'` with `B''` and `A''`\n +with `B'`, while fixing the strategy registers `A` and `B`. This\n +formalization-only auxiliary is the crosswise exchange of blueprint\n +`lem:qld-placement-transfer`. -/\n +def eprCrossSwap (P : AdmissibleParams) (ιA ιB : Type*) :\n +    SixReg P ιA ιB ≃ SixReg P ιA ιB where\n +  toFun := fun ⟨⟨a, a', a''⟩, b, b', b''⟩ => ((a, (b'', b')), (b, (a'', a')))\n +  invFun := fun ⟨⟨a, a', a''⟩, b, b', b''⟩ => ((a, (b'', b')), (b, (a'', a')))\n +  left_inv := by rintro ⟨⟨a, a', a''⟩, b, b', b''⟩; rfl\n +  right_inv := by rintro ⟨⟨a, a', a''⟩, b, b', b''⟩; rfl\n +\n +/-- The EPR vector is symmetric in its two registers. -/\n +theorem eprState_ofLp_swap {V : Type*} [Fintype V] [DecidableEq V]\n +    [Nonempty V] (x y : V) :\n +    (eprState V).ofLp (x, y) = (eprState V).ofLp (y, x) := by\n +  change (if x = y then (Real.sqrt (Fintype.card V : ℝ) : ℂ)⁻¹ else 0) =\n +    (if y = x then (Real.sqrt (Fintype.card V : ℝ) : ℂ)⁻¹ else 0)\n +  by_cases h : x = y\n +  · simp [h]\n +  · simp [h, Ne.symm h]\n +\n +/-- The crosswise EPR exchange fixes the expanded state. This independently\n +proved invariance uses only the symmetry of the EPR vectors, as in blueprint\n +`lem:qld-placement-transfer`. -/\n +theorem reindexState_eprCrossSwap_psiHat (S : ProjectiveSetting P ε) :\n +    reindexState (eprCrossSwap P S.toStrategy.ιA S.toStrategy.ιB) S.psiHat =\n +      S.psiHat := by\n +  ext i\n +  obtain ⟨⟨a, a', a''⟩, b, b', b''⟩ := i\n +  change S.toStrategy.ψ.ofLp (a, b) * (eprState (PauliRegister P)).ofLp (b'', b') *\n +      (eprState (PauliRegister P)).ofLp (a'', a') =\n +    S.toStrategy.ψ.ofLp (a, b) * (eprState (PauliRegister P)).ofLp (a', a'') *\n +      (eprState (PauliRegister P)).ofLp (b', b'')\n +  rw [eprState_ofLp_swap b'' b', eprState_ofLp_swap a'' a']\n +  ring\n +\n +/-- The cro