ment p (S.pointMeasExp p.side .Z xz.2)) +      (S.placedMeasurement_isProjective p _ (S.pointMeasExp_isProjective _ _ _)) +      (S.placedMeasurement_isProjective p _ (S.pointMeasExp_isProjective _ _ _)) +  refine ⟨CombinedPointsWitness.mk (fun side x z => Q side (x, z)) ?_ ?_ ?_ ?_⟩ +  · intro side x z +    exact hQproj side (x, z) +  · intro p₁ p₂ hopp +    rcases htotal with htot | hε1 +    · exact le_trans (hchain p₁ p₂ hopp).2.2 htot +    · exact le_trans (opFamilyDistSq_uniform_le_four _ _ S.psiHat S.psiHat_norm +        (fun xz => hsqQ p₁ xz) (fun xz => hsqQ p₂ xz)) (hK8 hε1) +  · intro p₁ p₂ hopp +    rcases htotal with htot | hε1 +    · exact le_trans (hchain p₁ p₂ hopp).1 (le_trans hsub1 htot) +    · exact le_trans (opFamilyDistSq_uniform_le_four _ _ S.psiHat S.psiHat_norm +        (fun xz => hsqQ p₁ xz) (fun xz => hsqXZ p₂ xz)) (hK8 hε1) +  · intro p₁ p₂ hopp +    rcases htotal with htot | hε1 +    · exact le_trans (hchain p₁ p₂ hopp).2.1 (le_trans hsub2 htot) +    · exact le_trans (opFamilyDistSq_uniform_le_four _ _ S.psiHat S.psiHat_norm +        (fun xz => hsqQ p₁ xz) (fun xz => hsqZX p₂ xz)) (hK8 hε1)    /-- Register placement distributes over a filtered outcome sum. -/  private theorem place_finset_sum {P : AdmissibleParams} {ε : ℝ} diff --git a/MIPStarRE/QPBT/Combining/Points/Closeness.lean b/MIPStarRE/QPBT/Combining/Points/Closeness.lean new file mode 100644 index 00000000..6fb2a3cb --- /dev/null +++ b/MIPStarRE/QPBT/Combining/Points/Closeness.lean @@ -0,0 +1,301 @@ +import MIPStarRE.QPBT.Combining.Points.Orthonormalization + +/-! +# Closeness estimates for the combined point measurements + +Given projective measurements `Q^{x,z}` on each player's expanded local space +that are close to the sandwich POVMs on the placements where they were +constructed, this file assembles the three conclusions of `lem:qld-4-10` on +every pair of opposite placements by the triangle inequality along +`Q ≈ R ≈ M^Z M^X ≈ M^X M^Z` and the cross-placement consistency of the +ordered products.  It also records the trivial bound `4` on the state-dependent +distance of two square-summable families, used when the test error exceeds +one, and the elementary estimate collapsing the error terms `ε`, `√ε`, and +`(ε + √ε)^{1/4}` into a single power `ε^{1/8}` when `ε ≤ 1`. + +## References + +Paper `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:838-881` +(self-consistency and consistency with `M̂` in the proof of `lem:qld-4-10`), +blueprint `blueprint/src/chapter/ch15_qpbt_combining.tex:803-960`; the route +is explained in `docs/paper-gaps/qpbt_linearity-theorem-quotation.tex`. +-/ + +open scoped BigOperators Matrix MatrixOrder ComplexOrder + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT hiding Measurement +open MIPStarRE.Quantum DistanceCalculus + +noncomputable section + +/-! ## The trivial bound -/ + +/-- A square-summable family of operators has total squared norm at most one on +a unit vector. -/ +theorem sum_norm_apply_sq_le_one {α ι : Type*} [Fintype α] [Fintype ι] +    [DecidableEq ι] (A : α → Op ι) (ψ : EuclideanSpace ℂ ι) (hψ : ‖ψ‖ = 1) +    (hA : ∑ a, (A a)ᴴ * A a ≤ 1) : +    ∑ a, ‖applyOperatorToState (A a) ψ‖ ^ 2 ≤ 1 := by +  have h := sum_norm_mul_apply_le A 1 ψ hA +  simp only [mul_one, WinImplications.applyOperatorToState_one, hψ] at h +  simpa using h + +/-- The state-dependent distance of two square-summable families is at most +`4` on a unit vector, under a uniform distribution. -/ +theorem opFamilyDistSq_uniform_le_four {X α ι : Type*} [Fintype X] [DecidableEq X] +    [Nonempty X] [Fintype α] [Fintype ι] [DecidableEq ι] +    (A B : X → α → Op ι) (ψ : EuclideanSpace ℂ ι) (hψ : ‖ψ‖ = 1) +    (hA : ∀ x, ∑ a, (A x a)ᴴ * A x a ≤ 1) (hB : ∀ x, ∑ a, (B x a)ᴴ * B x a ≤ 1) : +    opFamilyDistSq (uniformDistribution X) A B ψ ≤ 4 := by +  unfold opFamilyDistSq +  calc avgOver (uniformDistribution X) (fun x => +        ∑ a, ‖applyOperatorToState (A x a - B x a) ψ‖ ^ 2) +      ≤ avgOver (uniformDistribution X) (fun _ => (4 : ℝ)) := by +        refine avgOver_mono _ _ _ fun x => ?_ +        have hA' := sum_norm_apply_sq_le_one (A x) ψ hψ (hA x) +        have hB' := sum_norm_apply_sq_le_one (B x) ψ hψ (hB x) +        have hpt : ∀ a, ‖applyOperatorToState (A x a - B x a) ψ‖ ^ 2 ≤ +            2 * ‖applyOperatorToState (A x a) ψ‖ ^ 2 + +              2 * ‖applyOperatorToState (B x a) ψ‖ ^ 2 := by +          intro a +          have hsub : applyOperatorToState (A x a - B x a) ψ = +              applyOperatorToState (A x a) ψ - applyOperatorToState (B x a) ψ := by +            simp [applyOperatorToState] +          rw [hsub] +          have := norm_sub_le (applyOperatorToState (A x a) ψ) +            (applyOperatorToState (B x a) ψ) +          nlinarith [norm_nonneg (applyOperatorToState (A x a) ψ), +            norm_nonneg (applyOperatorToState (B x a) ψ), +            norm_nonneg (applyOperatorToState (A x a) ψ - +              applyOperatorToState (B x a) ψ), +            sq_nonneg (‖applyOperatorToState (A x a) ψ‖ - +              ‖applyOperatorToState (B x a) ψ‖)] +        calc ∑ a, ‖applyOperatorToState (A x a - B x a) ψ‖ ^ 2 +            ≤ ∑ a, (2 * ‖applyOperatorToState (A x a) ψ‖ ^ 2 + +                2 * ‖applyOperatorToState (B x a) ψ‖ ^ 2) := +              Finset.sum_le_sum fun a _ => hpt a +          _ = 2 * ∑ a, ‖applyOperatorToState (A x a) ψ‖ ^ 2 + +                2 * ∑ a, ‖applyOperatorToState (B x a) ψ‖ ^ 2 := by +              rw [Finset.sum_add_distrib, Finset.mul_sum, Finset.mul_sum] +          _ ≤ 4 := by linarith +    _ = 4 := avgOver_uniform_const _ + +/-- The effects of a projective measurement, placed on a register pair, are +square-summable to the identity. -/ +theorem ProjectiveSetting.sum_place_effect_conjTranspose_mul_self_le_one +    {P : AdmissibleParams} {ε : ℝ} (S : ProjectiveSetting P ε) (p : Placement) +    {α : Type*} [Fintype α] (M : Measurement α (S.ExpandedLocalSpace p.side)) +    (hM : MIPStarRE.QPBT.Measurement.IsProjective M) : +    ∑ a, (S.place p (M.effect a))ᴴ * S.place p (M.effect a) ≤ 1 := by +  refine le_of_eq ?_ +  calc ∑ a, (S.place p (M.effect a))ᴴ * S.place p (M.effect a) +      = ∑ a, S.place p (M.effect a) := by +        refine Finset.sum_congr rfl fun a _ => ?_ +        rw [← S.place_conjTranspose, ← S.place_mul, +          (hM a).isSelfAdjoint.isHermitian.eq, (hM a).isIdempotentElem.eq] +    _ = 1 := by rw [← S.place_finsetSum, M.sum_eq_one, S.place_one] + +/-- The products `A_a B_b` of the effects of two projective measurements on a +common space are square-summable to the identity. -/ +theorem sum_mul_conjTranspose_mul_self_eq_one {α β ι : Type*} [Fintype α] +    [Fintype β] [Fintype ι] [DecidableEq ι] +    (A : Measurement α ι) (B : Measurement β ι) +    (hA : MIPStarRE.QPBT.Measurement.IsProjective A) +    (hB : MIPStarRE.QPBT.Measurement.IsProjective B) : +    ∑ ab : α × β, (A.effect ab.1 * B.effect ab.2)ᴴ * (A.effect ab.1 * B.effect ab.2) = +      1 := by +  have hpt : ∀ (a : α) (b : β), +      (A.effect a * B.effect b)ᴴ * (A.effect a * B.effect b) = +        B.effect b * A.effect a * B.effect b := by +    intro a b +    rw [Matrix.conjTranspose_mul, (hA a).isSelfAdjoint.isHermitian.eq, +      (hB b).isSelfAdjoint.isHermitian.eq, Matrix.mul_assoc _ _ (A.effect a * B.effect b), +      ← Matrix.mul_assoc (A.effect a) (A.effect a), (hA a).isIdempotentElem.eq, +      ← Matrix.mul_assoc] +  rw [Fintype.sum_prod_type_right] +  calc ∑ b : β, ∑ a : α, (A.effect a * B.effect b)ᴴ * (A.effect a * B.effect b) +      = ∑ b : β, B.effect b * (∑ a : α, A.effect a) * B.effect b := by +        refine Finset.sum_congr rfl fun b _ => ?_ +        rw [Finset.mul_sum, Finset.sum_mul] +        exact Finset.sum_congr rfl fun a _ => hpt a b +    _ = 1 := by +        simp_rw [A.sum_eq_one, mul_one] +        rw [Finset.sum_congr rfl fun b _ => (hB b).isIdempotentElem.eq] +        exact B.sum_eq_one + +/-- The products `B_b A_a` of the effects of two projective measurements on a +common space, indexed by the pair `(a, b)`, are square-summable to the +identity. -/ +theorem sum_mul_conjTranspose_mul_self_eq_one' {α β ι : Type*} [Fintype α] +    [Fintype β] [Fintype ι] [DecidableEq ι] +    (A : Measurement α ι) (B : Measurement β ι) +    (hA : MIPStarRE.QPBT.Measurement.IsProjective A) +    (hB : MIPStarRE.QPBT.Measurement.IsProjective B) : +    ∑ ab : α × β, (B.effect ab.2 * A.effect ab.1)ᴴ * (B.effect ab.2 * A.effect ab.1) = +      1 := by +  have hpt : ∀ (a : α) (b : β), +      (B.effect b * A.effect a)ᴴ * (B.effect b * A.effect a) = +        A.effect a * B.effect b * A.effect a := by +    intro a b +    rw [Matrix.conjTranspose_mul, (hA a).isSelfAdjoint.isHermitian.eq, +      (hB b).isSelfAdjoint.isHermitian.eq, Matrix.mul_assoc _ _ (B.effect b * A.effect a), +      ← Matrix.mul_assoc (B.effect b) (B.effect b), (hB b).isIdempotentElem.eq, +      ← Matrix.mul_assoc] +  rw [Fintype.sum_prod_type] +  calc ∑ a : α, ∑ b : β, (B.effect b * A.effect a)ᴴ * (B.effect b * A.effect a) +      = ∑ a : α, A.effect a * (∑ b : β, B.effect b) * A.effect a := by +        refine Finset.sum_congr rfl fun a _ => ?_ +        rw [Finset.mul_sum, Finset.sum_mul] +        exact Finset.sum_congr rfl fun b _ => hpt a b +    _ = 1 := by +        simp_rw [B.sum_eq_one, mul_one] +        rw [Finset.sum_congr rfl fun a _ => (hA a).isIdempotentElem.eq] +        exact A.sum_eq_one + +/-! ## The chain of closeness estimates -/ + +namespace ProjectiveSetting + +variable {P : AdmissibleParams} {ε : ℝ} + +/-- The three closeness conclusions of `lem:qld-4-10` for a pair of projective +families close to the placed sandwiches: with `η` the closeness of `Q` to `R` +on every placement, `C₁ √ε` the closeness of `R` to the ordered product, +`C₂ √ε` the commutation error, and `C₃ ε` the cross-placement consistency of +the ordered products, the distances from `Q` on one placement to the two +ordered products and to `Q` on the opposite placement are bounded by explicit +combinations.  Paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:838-881`. -/ +theorem chain_bounds (S : ProjectiveSetting P ε) +    (Q : (side : PlayerSide) → PointPair P → +      Measurement (PauliScalar P × PauliScalar P) (S.ExpandedLocalSpace side)) +    (η C₁ C₂ C₃ : ℝ) +    (hQR : ∀ p : Placement, opFamilyDistSq (uniformDistribution (PointPair P)) +      (fun xz (ab : PauliScalar P × PauliScalar P) => +        S.place p ((Q p.side xz).effect ab)) +      (fun xz ab => S.place p ((S.sandwichPoint p.side xz.1 xz.2).effect ab)) +      S.psiHat ≤ η) +    (h₁ : ∀ p : Placement, opFamilyDistSq (uniformDistribution (PointPair P)) +      (fun xz (ab : PauliScalar P × PauliScalar P) => +        S.place p ((S.sandwichPoint p.side xz.1 xz.2).effect ab)) +      (fun xz ab => S.place p +        ((S.pointMeasExp p.side .Z xz.2).effect ab.2 * +          (S.pointMeasExp p.side .X xz.1).effect ab.1)) +      S.psiHat ≤ C₁ * Real.sqrt ε) +    (h₂ : ∀ p : Placement, opFamilyDistSq (uniformDistribution (PointPair P)) +      (fun xz (ab : PauliScalar P × PauliScalar P) => S.place p +        ((S.pointMeasExp p.side .X xz.1).effect ab.1 * +          (S.pointMeasExp p.side .Z xz.2).effect ab.2)) +      (fun xz ab => S.place p +        ((S.pointMeasExp p.side .Z xz.2).effect ab.2 * +          (S.pointMeasExp p.side .X xz.1).effect ab.1)) +      S.psiHat ≤ C₂ * Real.sqrt ε) +    (h₃ : ∀ p₁ p₂ : Placement, p₁.IsOpposite p₂ → +      opFamilyDistSq (uniformDistribution (PointPair P)) +        (fun xz (ab : PauliScalar P × PauliScalar P) => S.place p₁ +          ((S.pointMeasExp p₁.side .Z xz.2).effect ab.2 * +            (S.pointMeasExp p₁.side .X xz.1).effect ab.1)) +        (fun xz ab => S.place p₂ +          ((S.pointMeasExp p₂.side .X xz.1).effect ab.1 * +            (S.pointMeasExp p₂.side .Z xz.2).effect ab.2)) +        S.psiHat ≤ C₃ * ε) +    (p₁ p₂ : Placement) (hopp : p₁.IsOpposite p₂) : +    opFamilyDistSq (uniformDistribution (PointPair P)) +        (fun xz (ab : PauliScalar P × PauliScalar P) => +          S.place p₁ ((Q p₁.side xz).effect ab)) +        (fun xz ab => S.place p₂ +          ((S.pointMeasExp p₂.side .X xz.1).effect ab.1 * +            (S.pointMeasExp p₂.side .Z xz.2).effect ab.2)) +        S.psiHat ≤ 2 * η + 4 * (C₁ * Real.sqrt ε) + 4 * (C₃ * ε) ∧ +      opFamilyDistSq (uniformDistribution (PointPair P)) +        (fun xz (ab : PauliScalar P × PauliScalar P) => +          S.place p₁ ((Q p₁.side xz).effect ab)) +        (fun xz ab => S.place p₂ +          ((S.pointMeasExp p₂.side .Z xz.2).effect ab.2 * +            (S.pointMeasExp p₂.side .X xz.1).effect ab.1)) +        S.psiHat ≤ 4 * η + 8 * (C₁ * Real.sqrt ε) + 8 * (C₃ * ε) + +          2 * (C₂ * Real.sqrt ε) ∧ +      opFamilyDistSq (uniformDistribution (PointPair P)) +        (fun xz (ab : PauliScalar P × PauliScalar P) => +          S.place p₁ ((Q p₁.side xz).effect ab)) +        (fun xz ab => S.place p₂ ((Q p₂.side xz).effect ab)) +        S.psiHat ≤ 12 * η + 20 * (C₁ * Real.sqrt ε) + 16 * (C₃ * ε) + +          4 * (C₂ * Real.sqrt ε) := by +  -- `R_1 ≈ M^X M^Z` on the opposite placement +  have hRXZ := opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P)) +    _ _ _ S.psiHat _ _ (h₁ p₁) (h₃ p₁ p₂ hopp) +  -- `Q_1 ≈ M^X M^Z` on the opposite placement +  have hQXZ := opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P)) +    _ _ _ S.psiHat _ _ (hQR p₁) hRXZ +  -- `Q_1 ≈ M^Z M^X` on the opposite placement +  have hQZX := opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P)) +    _ _ _ S.psiHat _ _ hQXZ (h₂ p₂) +  -- `M^Z M^X ≈ Q_2` on the opposite placement +  have hZXQ : opFamilyDistSq (uniformDistribution (PointPair P)) +      (fun xz (ab : PauliScalar P × PauliScalar P) => S.place p₂ +        ((S.pointMeasExp p₂.side .Z xz.2).effect ab.2 * +          (S.pointMeasExp p₂.side .X xz.1).effect ab.1)) +      (fun xz ab => S.place p₂ ((Q p₂.side xz).effect ab)) +      S.psiHat ≤ 2 * η + 2 * (C₁ * Real.sqrt ε) := by +    rw [opFamilyDistSq_symm] +    exact opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P)) +      _ _ _ S.psiHat _ _ (hQR p₂) (h₁ p₂) +  have hQQ := opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P)) +    _ _ _ S.psiHat _ _ hQZX hZXQ +  refine ⟨by linarith, by linarith, by linarith⟩ + +end ProjectiveSetting + +/-! ## Collapsing the error terms into one power -/ + +/-- For `0 ≤ ε ≤ 1`, the error terms `ε`, `√ε`, and `(C₀ (ε + √ε))^{1/4}` +with `C₀ ≥ 1` are all bounded by multiples of `ε^{1/8}`. -/ +theorem error_terms_le_rpow_eighth {ε C₀ : ℝ} (hε : 0 ≤ ε) (hε1 : ε ≤ 1) +    (hC₀ : 1 ≤ C₀) : +    ε ≤ Real.rpow ε (1 / 8 : ℝ) ∧ Real.sqrt ε ≤ Real.rpow ε (1 / 8 : ℝ) ∧ +      Real.rpow (C₀ * (ε + Real.sqrt ε)) (1 / 4 : ℝ) ≤ +        2 * C₀ * Real.rpow ε (1 / 8 : ℝ) := by +  rcases eq_or_lt_of_le hε with h0 | hpos +  · subst h0 +    have h8 : Real.rpow (0 : ℝ) (1 / 8 : ℝ) = 0 := Real.zero_rpow (by norm_num) +    have h4 : Real.rpow (C₀ * (0 + Real.sqrt 0)) (1 / 4 : ℝ) = 0 := by +      rw [Real.sqrt_zero, add_zero, mul_zero] +      exact Real.zero_rpow (by norm_num) +    rw [h8, h4, Real.sqrt_zero] +    refine ⟨le_rfl, le_rfl, ?_⟩ +    positivity +  · have hsqrt : Real.sqrt ε = Real.rpow ε (1 / 2 : ℝ) := Real.sqrt_eq_rpow ε +    have hε1' : Real.rpow ε 1 = ε := Real.rpow_one ε +    have hmono : ∀ y z : ℝ, z ≤ y → Real.rpow ε y ≤ Real.rpow ε z := fun y z hyz => +      Real.rpow_le_rpow_of_exponent_ge hpos hε1 hyz +    refine ⟨?_, ?_, ?_⟩ +    · exact le_of_eq_of_le hε1'.symm (hmono 1 (1 / 8) (by norm_num)) +    · rw [hsqrt] +      exact hmono (1 / 2) (1 / 8) (by norm_num) +    · have hsum : ε + Real.sqrt ε ≤ 2 * Real.sqrt ε := by +        have : ε ≤ Real.sqrt ε := by +          rw [hsqrt] +          exact le_of_eq_of_le hε1'.symm (hmono 1 (1 / 2) (by norm_num)) +        linarith +      have hC : 0 ≤ 2 * C₀ := by linarith +      calc Real.rpow (C₀ * (ε + Real.sqrt ε)) (1 / 4 : ℝ) +          ≤ Real.rpow (2 * C₀ * Real.sqrt ε) (1 / 4 : ℝ) := by +            apply Real.rpow_le_rpow (by positivity) _ (by norm_num) +            nlinarith [Real.sqrt_nonneg ε] +        _ = Real.rpow (2 * C₀) (1 / 4 : ℝ) * Real.rpow ε (1 / 8 : ℝ) := by +            change (2 * C₀ * Real.sqrt ε) ^ (1 / 4 : ℝ) = +              (2 * C₀) ^ (1 / 4 : ℝ) * ε ^ (1 / 8 : ℝ) +            rw [Real.mul_rpow hC (Real.sqrt_nonneg ε), Real.sqrt_eq_rpow, +              ← Real.rpow_mul hε] +            norm_num +        _ ≤ 2 * C₀ * Real.rpow ε (1 / 8 : ℝ) := by +            refine mul_le_mul_of_nonneg_right ?_ (Real.rpow_nonneg hε _) +            calc Real.rpow (2 * C₀) (1 / 4 : ℝ) ≤ Real.rpow (2 * C₀) 1 := +                  Real.rpow_le_rpow_of_exponent_le (by linarith) (by norm_num) +              _ = 2 * C₀ := Real.rpow_one _ + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/Points/Commutation.lean b/MIPStarRE/QPBT/Combining/Points/Commutation.lean new file mode 100644 index 00000000..29de3421 --- /dev/null +++ b/MIPStarRE/QPBT/Combining/Points/Commutation.lean @@ -0,0 +1,457 @@ +import MIPStarRE.QPBT.Combining.Points.Placement + +/-! +# Approximate commutation of the field-valued expanded point measurements + +The approximate commutation of `lem:qld-comm-cons` is stated for the binary +refinements `M^{(Point,W),u,r}_b` of the expanded point measurements.  The +combined point measurements of `lem:qld-4-10` are built here directly from the +`F_q`-valued measurements `M^{(Point,W),u}_a`, so the commutation estimate is +transferred to them.  The transfer is exact: since +`M^{(Point,X),x}_a = E_r (-1)^{tr(ar)} X^r(x)` and +`M^{(Point,Z),z}_b = E_s (-1)^{tr(bs)} Z^s(z)`, the commutator of the two +measurement effects is the Fourier transform, in the outcome pair `(a, b)`, +of the commutators of the expanded observables, and Parseval's identity for +the additive characters of `F_q` turns the sum over `(a, b)` of the squared +norms into the average over `(r, s)` of the squared norms of the observable +commutators.  No factor depending on `q` is lost. + +## Main results + +* `sum_norm_sum_smul_sq_of_orthogonal`: Parseval's identity for an orthogonal +  system of coefficients. +* `sum_fixedCharacter_mul`: Fourier cancellation for the fixed trace character. +* `expPoint_comm`: the field-valued expanded point measurements approximately +  commute on every register placement, with the error of +  `lem:qld-comm-cons`. + +## References + +The commutation estimate for the binary refinements is item 2 of +`lem:qld-comm-cons`, blueprint +`blueprint/src/chapter/ch14_qpbt_observables.tex:1139-1210`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:466-505`; the +Fourier form of the point effects is `def:expanded-point-measurement`, paper +lines 384--418.  The role of the transfer in the proof of `lem:qld-4-10` is +explained in `docs/paper-gaps/qpbt_linearity-theorem-quotation.tex`. +-/ + +open scoped BigOperators Matrix MatrixOrder ComplexOrder + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT hiding Measurement +open MIPStarRE.Quantum +open MIPStarRE.LDT.Preliminaries + +noncomputable section + +/-- A pair of points, one for the `X` basis and one for the `Z` basis.  This +is the question pair `(x, z)` of `lem:qld-4-10`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:689-709`. -/ +abbrev PointPair (P : AdmissibleParams) := +  (Fin P.m → PauliScalar P) × (Fin P.m → PauliScalar P) + +/-! ## Parseval's identity for an orthogonal system of coefficients -/ + +/-- Formalization-only auxiliary for `lem:qld-4-10`: if the coefficient +vectors `i ↦ c j i`, `j` ranging over a finite set, are orthogonal with common +squared norm `N`, then the squared norms of the weighted sums +`∑ i, c j i • v i` add up to `N` times the squared norms of the `v i`. -/ +theorem sum_norm_sum_smul_sq_of_orthogonal {I J E : Type*} [Fintype I] +    [DecidableEq I] [Fintype J] [NormedAddCommGroup E] [InnerProductSpace ℂ E] +    (c : J → I → ℂ) (N : ℝ) +    (horth : ∀ i i', ∑ j, (starRingEnd ℂ) (c j i) * c j i' = +      if i = i' then (N : ℂ) else 0) +    (v : I → E) : +    ∑ j, ‖∑ i, c j i • v i‖ ^ 2 = N * ∑ i, ‖v i‖ ^ 2 := by +  have hnorm : ∀ x : E, ‖x‖ ^ 2 = (inner ℂ x x).re := fun x => by +    simpa using (inner_self_eq_norm_sq (𝕜 := ℂ) x).symm +  have hj : ∀ j, ‖∑ i, c j i • v i‖ ^ 2 = +      (∑ i, ∑ i', ((starRingEnd ℂ) (c j i) * c j i') * +        inner ℂ (v i) (v i')).re := by +    intro j +    rw [hnorm, sum_inner] +    simp only [inner_sum, inner_smul_left, inner_smul_right] +    congr 1 +    refine Finset.sum_congr rfl fun i _ => Finset.sum_congr rfl fun i' _ => ?_ +    ring +  have hsum : ∑ j, ∑ i, ∑ i', ((starRingEnd ℂ) (c j i) * c j i') * +      inner ℂ (v i) (v i') = ∑ i, (N : ℂ) * inner ℂ (v i) (v i) := by +    rw [Finset.sum_comm] +    refine Finset.sum_congr rfl fun i _ => ?_ +    rw [Finset.sum_comm] +    calc ∑ i', ∑ j, ((starRingEnd ℂ) (c j i) * c j i') * inner ℂ (v i) (v i') +        = ∑ i', (∑ j, (starRingEnd ℂ) (c j i) * c j i') * +            inner ℂ (v i) (v i') := by +          refine Finset.sum_congr rfl fun i' _ => ?_ +          rw [Finset.sum_mul] +      _ = ∑ i', (if i = i' then (N : ℂ) else 0) * inner ℂ (v i) (v i') := by +          refine Finset.sum_congr rfl fun i' _ => ?_ +          rw [horth] +      _ = (N : ℂ) * inner ℂ (v i) (v i) := by +          simp [ite_mul] +  calc ∑ j, ‖∑ i, c j i • v i‖ ^ 2 +      = (∑ j, ∑ i, ∑ i', ((starRingEnd ℂ) (c j i) * c j i') * +          inner ℂ (v i) (v i')).re := by +        rw [Complex.re_sum] +        exact Finset.sum_congr rfl fun j _ => hj j +    _ = (∑ i, (N : ℂ) * inner ℂ (v i) (v i)).re := by rw [hsum] +    _ = N * ∑ i, ‖v i‖ ^ 2 := by +        rw [Complex.re_sum, Finset.mul_sum] +        refine Finset.sum_congr rfl fun i _ => ?_ +        rw [Complex.re_ofReal_mul, ← hnorm] + +/-! ## The fixed trace character -/ + +section Characters + +variable {P : AdmissibleParams} + +/-- The phase induced by the fixed binary trace is an additive character. +Paper `references/qpbt-paper/04_preliminaries.tex:1052-1081`. -/ +theorem fixedCharacter_mul (x y : PauliScalar P) : +    phaseSign (fixedBinTrace P.model x) * phaseSign (fixedBinTrace P.model y) = +      phaseSign (fixedBinTrace P.model (x + y)) := by +  rw [fixedBinTrace, map_add, phaseSign_eq_ffChar, phaseSign_eq_ffChar, +    phaseSign_eq_ffChar] +  exact ((ZMod.stdAddChar (N := 2)).map_add_eq_mul _ _).symm + +/-- The fixed trace character is even: negation acts trivially on the binary +trace. -/ +theorem fixedCharacter_neg (x : PauliScalar P) : +    phaseSign (fixedBinTrace P.model (-x)) = +      phaseSign (fixedBinTrace P.model x) := by +  rw [fixedBinTrace, map_neg, ZMod.neg_eq_self_mod_two] + +/-- Fourier cancellation for the fixed trace character: the character sums to +the field size at `0` and to zero elsewhere.  This is `lem:cancellation` for +the one-dimensional space, blueprint +`blueprint/src/chapter/ch11_qpbt_algebra.tex:686`, paper +`references/qpbt-paper/04_preliminaries.tex:1124-1132`. -/ +theorem sum_fixedCharacter_mul (c : PauliScalar P) : +    ∑ a : PauliScalar P, phaseSign (fixedBinTrace P.model (a * c)) = +      if c = 0 then (Fintype.card (PauliScalar P) : ℂ) else 0 := by +  have h : (𝔼 r : PauliScalar P, phaseSign (fixedBinTrace P.model (r * c))) = +      if c = 0 then (1 : ℂ) else 0 := by +    simpa only [fixedBinTrace, phaseSign_eq_ffChar, +      MIPStarRE.LDT.Preliminaries.ffChar_apply] using +      (fourier_fact_scalar (p := 2) (F := PauliScalar P) c) +  rw [Finset.expect_eq_sum_div_card] at h +  have hcard : (Fintype.card (PauliScalar P) : ℂ) ≠ 0 := +    Nat.cast_ne_zero.mpr Fintype.card_ne_zero +  rw [Finset.card_univ, div_eq_iff hcard] at h +  rw [h] +  split_ifs <;> simp + +/-- Orthogonality of two fixed trace characters. -/ +theorem sum_fixedCharacter_mul_fixedCharacter (r r' : PauliScalar P) : +    ∑ a : PauliScalar P, phaseSign (fixedBinTrace P.model (a * r)) * +        phaseSign (fixedBinTrace P.model (a * r')) = +      if r = r' then (Fintype.card (PauliScalar P) : ℂ) else 0 := by +  have hterm : ∀ a : PauliScalar P, +      phaseSign (fixedBinTrace P.model (a * r)) * +          phaseSign (fixedBinTrace P.model (a * r')) = +        phaseSign (fixedBinTrace P.model (a * (r' - r))) := by +    intro a +    rw [← fixedCharacter_neg (a * r), fixedCharacter_mul] +    congr 2 +    ring +  simp_rw [hterm, sum_fixedCharacter_mul] +  by_cases h : r = r' +  · simp [h] +  · rw [if_neg h, if_neg] +    intro h' +    exact h (sub_eq_zero.mp h').symm + +/-- The two-dimensional character system `(a, b) ↦ χ(a r) χ(b s)` is orthogonal +with common squared norm `q ^ 2`. -/ +theorem sum_pairCharacter_mul_pairCharacter +    (rs rs' : PauliScalar P × PauliScalar P) : +    ∑ ab : PauliScalar P × PauliScalar P, +        (starRingEnd ℂ) (phaseSign (fixedBinTrace P.model (ab.1 * rs.1)) * +            phaseSign (fixedBinTrace P.model (ab.2 * rs.2))) * +          (phaseSign (fixedBinTrace P.model (ab.1 * rs'.1)) * +            phaseSign (fixedBinTrace P.model (ab.2 * rs'.2))) = +      if rs = rs' then +        (((Fintype.card (PauliScalar P) : ℝ) ^ 2 : ℝ) : ℂ) else 0 := by +  have hstar : ∀ t : ZMod 2, (starRingEnd ℂ) (phaseSign t) = phaseSign t := by +    intro t +    rw [← Complex.star_def] +    exact star_phaseSign t +  simp_rw [map_mul, hstar] +  rw [Fintype.sum_prod_type] +  calc ∑ a : PauliScalar P, ∑ b : PauliScalar P, +        phaseSign (fixedBinTrace P.model (a * rs.1)) * +            phaseSign (fixedBinTrace P.model (b * rs.2)) * +          (phaseSign (fixedBinTrace P.model (a * rs'.1)) * +            phaseSign (fixedBinTrace P.model (b * rs'.2))) +      = (∑ a : PauliScalar P, phaseSign (fixedBinTrace P.model (a * rs.1)) * +            phaseSign (fixedBinTrace P.model (a * rs'.1))) * +          ∑ b : PauliScalar P, phaseSign (fixedBinTrace P.model (b * rs.2)) * +            phaseSign (fixedBinTrace P.model (b * rs'.2)) := by +        rw [Finset.sum_mul_sum] +        refine Finset.sum_congr rfl fun a _ => Finset.sum_congr rfl fun b _ => ?_ +        ring +    _ = _ := by +        rw [sum_fixedCharacter_mul_fixedCharacter, +          sum_fixedCharacter_mul_fixedCharacter] +        by_cases h1 : rs.1 = rs'.1 <;> by_cases h2 : rs.2 = rs'.2 +        · rw [if_pos h1, if_pos h2, if_pos (Prod.ext h1 h2)] +          push_cast +          ring +        · rw [if_pos h1, if_neg h2, if_neg (fun h => h2 (congrArg Prod.snd h))] +          simp +        · rw [if_neg h1, if_pos h2, if_neg (fun h => h1 (congrArg Prod.fst h))] +          simp +        · rw [if_neg h1, if_neg h2, if_neg (fun h => h1 (congrArg Prod.fst h))] +          simp + +end Characters + +/-! ## Fourier form of the point effects and of their commutator -/ + +/-- A uniform operator average is the normalized sum. -/ +theorem averageOperatorOverDistribution_uniform_eq_inv_card_smul_sum +    {α ι : Type*} [Fintype α] [DecidableEq α] [Nonempty α] +    [Fintype ι] [DecidableEq ι] (f : α → Op ι) : +    averageOperatorOverDistribution (uniformDistribution α) f = +      (Fintype.card α : ℂ)⁻¹ • ∑ a, f a := by +  ext i j +  simp only [averageOperatorOverDistribution, uniformDistribution, +    Distribution.uniformOnFinset, Finset.mem_univ, if_true, Matrix.sum_apply, +    Matrix.smul_apply, Complex.real_smul, smul_eq_mul, +    Finset.card_univ, one_div, Complex.ofReal_inv, Complex.ofReal_natCast] +  rw [Finset.mul_sum] + +namespace ProjectiveSetting + +variable {P : AdmissibleParams} {ε : ℝ} + +/-- The Fourier form of an expanded point effect as a normalized character +sum of the expanded observables.  This is the first display of +`def:expanded-point-measurement`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:384-418`. -/ +theorem expPointOp_eq_inv_card_smul_sum (S : ProjectiveSetting P ε) +    (side : PlayerSide) (W : PauliKind) (u : Fin P.m → PauliScalar P) +    (a : PauliScalar P) : +    S.expPointOp side W u a = +      (Fintype.card (PauliScalar P) : ℂ)⁻¹ • +        ∑ r, phaseSign (fixedBinTrace P.model (a * r)) • S.expObs side W r u := by +  unfold expPointOp +  rw [averageOperatorOverDistribution_uniform_eq_inv_card_smul_sum] + +/-- Formalization-only auxiliary: the product of two normalized weighted sums +is the normalized double sum of the weighted products, indexed by pairs. -/ +theorem smul_sum_mul_smul_sum {ι K : Type*} [Fintype K] [Fintype ι] +    (c : ℂ) (α β : K → ℂ) (X Z : K → Op ι) : +    (c • ∑ r, α r • X r) * (c • ∑ s, β s • Z s) = +      (c * c) • ∑ rs : K × K, (α rs.1 * β rs.2) • (X rs.1 * Z rs.2) := by +  rw [Fintype.sum_prod_type, smul_mul_smul_comm, Finset.sum_mul_sum] +  congr 1 +  refine Finset.sum_congr rfl fun r _ => Finset.sum_congr rfl fun s _ => ?_ +  rw [smul_mul_smul_comm] + +/-- Formalization-only auxiliary: the product of two normalized weighted sums +in the opposite order, indexed by the same pairs. -/ +theorem smul_sum_mul_smul_sum_swap {ι K : Type*} [Fintype K] [Fintype ι] +    (c : ℂ) (α β : K → ℂ) (X Z : K → Op ι) : +    (c • ∑ s, β s • Z s) * (c • ∑ r, α r • X r) = +      (c * c) • ∑ rs : K × K, (α rs.1 * β rs.2) • (Z rs.2 * X rs.1) := by +  rw [Fintype.sum_prod_type_right, smul_mul_smul_comm, Finset.sum_mul_sum] +  congr 1 +  refine Finset.sum_congr rfl fun s _ => Finset.sum_congr rfl fun r _ => ?_ +  rw [smul_mul_smul_comm, mul_comm (β s)] + +/-- The commutator of two field-valued point effects is the Fourier transform +of the commutators of the expanded observables. -/ +theorem expPointOp_commutator_eq (S : ProjectiveSetting P ε) (side : PlayerSide) +    (x z : Fin P.m → PauliScalar P) (a b : PauliScalar P) : +    S.expPointOp side .X x a * S.expPointOp side .Z z b - +        S.expPointOp side .Z z b * S.expPointOp side .X x a = +      ((Fintype.card (PauliScalar P) : ℂ)⁻¹ * +          (Fintype.card (PauliScalar P) : ℂ)⁻¹) • +        ∑ rs : PauliScalar P × PauliScalar P, +          (phaseSign (fixedBinTrace P.model (a * rs.1)) * +              phaseSign (fixedBinTrace P.model (b * rs.2))) • +            (S.expObs side .X rs.1 x * S.expObs side .Z rs.2 z - +              S.expObs side .Z rs.2 z * S.expObs side .X rs.1 x) := by +  rw [expPointOp_eq_inv_card_smul_sum, expPointOp_eq_inv_card_smul_sum, +    smul_sum_mul_smul_sum, smul_sum_mul_smul_sum_swap, ← smul_sub, +    ← Finset.sum_sub_distrib] +  congr 1 +  refine Finset.sum_congr rfl fun rs _ => ?_ +  rw [smul_sub] + +/-- Formalization-only auxiliary: an operator applied to a state is linear in +the operator over finite sums. -/ +theorem applyOperatorToState_finsetSum {ι γ : Type*} [Fintype ι] [DecidableEq ι] +    (s : Finset γ) (M : γ → Op ι) (ψ : EuclideanSpace ℂ ι) : +    applyOperatorToState (∑ x ∈ s, M x) ψ = +      ∑ x ∈ s, applyOperatorToState (M x) ψ := by +  unfold applyOperatorToState +  simp only [map_sum, LinearMap.sum_apply] + +/-- Parseval transfer, pointwise in the point pair: the summed squared norms of +the placed commutators of the field-valued point effects equal the average over +`(r, s)` of the squared norms of the placed commutators of the expanded +observables. -/ +theorem sum_norm_place_expPointOp_commutator_sq (S : ProjectiveSetting P ε) +    (p : Placement) (x z : Fin P.m → PauliScalar P) : +    ∑ ab : PauliScalar P × PauliScalar P, +        ‖applyOperatorToState (S.place p +          (S.expPointOp p.side .X x ab.1 * S.expPointOp p.side .Z z ab.2 - +            S.expPointOp p.side .Z z ab.2 * S.expPointOp p.side .X x ab.1)) +          S.psiHat‖ ^ 2 = +      avgOver (uniformDistribution (PauliScalar P × PauliScalar P)) +        (fun rs => ‖applyOperatorToState (S.place p +          (S.expObs p.side .X rs.1 x * S.expObs p.side .Z rs.2 z - +            S.expObs p.side .Z rs.2 z * S.expObs p.side .X rs.1 x)) +          S.psiHat‖ ^ 2) := by +  set v : PauliScalar P × PauliScalar P → +      EuclideanSpace ℂ (SixReg P S.toStrategy.ιA S.toStrategy.ιB) := +    fun rs => applyOperatorToState (S.place p +      (S.expObs p.side .X rs.1 x * S.expObs p.side .Z rs.2 z - +        S.expObs p.side .Z rs.2 z * S.expObs p.side .X rs.1 x)) S.psiHat +  set c : ℂ := (Fintype.card (PauliScalar P) : ℂ)⁻¹ +  have hpt : ∀ ab : PauliScalar P × PauliScalar P, +      applyOperatorToState (S.place p +          (S.expPointOp p.side .X x ab.1 * S.expPointOp p.side .Z z ab.2 - +            S.expPointOp p.side .Z z ab.2 * S.expPointOp p.side .X x ab.1)) +          S.psiHat = +        (c * c) • ∑ rs : PauliScalar P × PauliScalar P, +          (phaseSign (fixedBinTrace P.model (ab.1 * rs.1)) * +              phaseSign (fixedBinTrace P.model (ab.2 * rs.2))) • v rs := by +    intro ab +    rw [expPointOp_commutator_eq, place_smul, place_finsetSum, +      WinImplications.applyOperatorToState_smul_op, applyOperatorToState_finsetSum] +    congr 1 +    refine Finset.sum_congr rfl fun rs _ => ?_ +    rw [place_smul, WinImplications.applyOperatorToState_smul_op] +  have hparseval := sum_norm_sum_smul_sq_of_orthogonal +    (fun (ab rs : PauliScalar P × PauliScalar P) => +      phaseSign (fixedBinTrace P.model (ab.1 * rs.1)) * +        phaseSign (fixedBinTrace P.model (ab.2 * rs.2))) +    ((Fintype.card (PauliScalar P) : ℝ) ^ 2) +    (fun rs rs' => sum_pairCharacter_mul_pairCharacter rs rs') v +  have hq : (0 : ℝ) < (Fintype.card (PauliScalar P) : ℝ) := by +    exact_mod_cast Fintype.card_pos +  have hcnorm : ‖c * c‖ = ((Fintype.card (PauliScalar P) : ℝ) ^ 2)⁻¹ := by +    simp only [c, norm_mul, norm_inv, Complex.norm_natCast] +    rw [sq, mul_inv] +  calc ∑ ab : PauliScalar P × PauliScalar P, +        ‖applyOperatorToState (S.place p +          (S.expPointOp p.side .X x ab.1 * S.expPointOp p.side .Z z ab.2 - +            S.expPointOp p.side .Z z ab.2 * S.expPointOp p.side .X x ab.1)) +          S.psiHat‖ ^ 2 +      = ∑ ab : PauliScalar P × PauliScalar P, +          ‖c * c‖ ^ 2 * ‖∑ rs : PauliScalar P × PauliScalar P, +            (phaseSign (fixedBinTrace P.model (ab.1 * rs.1)) * +              phaseSign (fixedBinTrace P.model (ab.2 * rs.2))) • v rs‖ ^ 2 := by +        refine Finset.sum_congr rfl fun ab _ => ?_ +        rw [hpt, norm_smul, mul_pow] +    _ = ‖c * c‖ ^ 2 * (((Fintype.card (PauliScalar P) : ℝ) ^ 2) * +          ∑ rs, ‖v rs‖ ^ 2) := by +        rw [← Finset.mul_sum, hparseval] +    _ = avgOver (uniformDistribution (PauliScalar P × PauliScalar P)) +          (fun rs => ‖v rs‖ ^ 2) := by +        rw [avgOver_uniform_eq_inv_card_mul_sum, Fintype.card_prod, hcnorm] +        push_cast +        field_simp + +/-- The field-valued expanded point measurements approximately commute on each +of the four register placements, with the error of item 2 of +`lem:qld-comm-cons`.  The estimate is transferred from the binary refinements +of the source by the Parseval identity, without loss in the field size.  Paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:466-505`, +blueprint `blueprint/src/chapter/ch14_qpbt_observables.tex:1139-1210`; the +role of this form in the proof of `lem:qld-4-10` is explained in +`docs/paper-gaps/qpbt_linearity-theorem-quotation.tex`. -/ +theorem expPoint_comm : +    ∃ C : ℝ, 1 ≤ C ∧ +      ∀ (P : AdmissibleParams) (ε : ℝ) (S : ProjectiveSetting P ε) +        (p : Placement), +        opFamilyDistSq (uniformDistribution (PointPair P)) +          (fun xz (ab : PauliScalar P × PauliScalar P) => S.place p +            ((S.pointMeasExp p.side .X xz.1).effect ab.1 * +              (S.pointMeasExp p.side .Z xz.2).effect ab.2)) +          (fun xz ab => S.place p +            ((S.pointMeasExp p.side .Z xz.2).effect ab.2 * +              (S.pointMeasExp p.side .X xz.1).effect ab.1)) +          S.psiHat ≤ C * Real.sqrt ε := by +  obtain ⟨C, hC, h⟩ := exists_twistedCommutator_avg_le +  refine ⟨C, hC, ?_⟩ +  intro P ε S p +  have hε : (0 : ℝ) ≤ ε := by +    have hv := WinImplications.strategy_value_le_one S.toStrategy +    have hw := S.win +    linarith +  have hnorm : ∀ (x z : Fin P.m → PauliScalar P) +      (rs : PauliScalar P × PauliScalar P), +      ‖applyOperatorToState (S.place p +          (S.expObs p.side .X rs.1 x * S.expObs p.side .Z rs.2 z - +            S.expObs p.side .Z rs.2 z * S.expObs p.side .X rs.1 x)) +          S.psiHat‖ ^ 2 = +        ‖applyOperatorToState +          (S.placeStrategySide p.side (S.twistedCommutator p.side (x, z, rs.1, rs.2))) +          S.toStrategy.ψ‖ ^ 2 := by +    intro x z rs +    rw [expObs_commutator S p.side (x, z, rs.1, rs.2), +      norm_place_heteroKron_psiHat S p _ _ (tauX_mul_tauZ_isometry P (x, z, rs.1, rs.2))] +  have hfamily : opFamilyDistSq (uniformDistribution (PointPair P)) +      (fun xz (ab : PauliScalar P × PauliScalar P) => S.place p +        ((S.pointMeasExp p.side .X xz.1).effect ab.1 * +          (S.pointMeasExp p.side .Z xz.2).effect ab.2)) +      (fun xz ab => S.place p +        ((S.pointMeasExp p.side .Z xz.2).effect ab.2 * +          (S.pointMeasExp p.side .X xz.1).effect ab.1)) +      S.psiHat = +      avgOver (uniformDistribution (PauliTuple P)) (fun ω => +        ‖applyOperatorToState +          (S.placeStrategySide p.side (S.twistedCommutator p.side ω)) +          S.toStrategy.ψ‖ ^ 2) := by +    unfold opFamilyDistSq +    calc avgOver (uniformDistribution (PointPair P)) (fun xz => +          ∑ ab : PauliScalar P × PauliScalar P, +            ‖applyOperatorToState (S.place p +                ((S.pointMeasExp p.side .X xz.1).effect ab.1 * +                  (S.pointMeasExp p.side .Z xz.2).effect ab.2) - +              S.place p ((S.pointMeasExp p.side .Z xz.2).effect ab.2 * +                (S.pointMeasExp p.side .X xz.1).effect ab.1)) S.psiHat‖ ^ 2) +        = avgOver (uniformDistribution (PointPair P)) (fun xz => +            avgOver (uniformDistribution (PauliScalar P × PauliScalar P)) +              (fun rs => ‖applyOperatorToState +                (S.placeStrategySide p.side +                  (S.twistedCommutator p.side (xz.1, xz.2, rs.1, rs.2))) +                S.toStrategy.ψ‖ ^ 2)) := by +          refine avgOver_congr _ _ _ fun xz => ?_ +          rw [← avgOver_congr _ _ _ (hnorm xz.1 xz.2), +            ← sum_norm_place_expPointOp_commutator_sq S p xz.1 xz.2] +          refine Finset.sum_congr rfl fun ab _ => ?_ +          rw [place_sub] +          rfl +      _ = avgOver (uniformDistribution (PointPair P × (PauliScalar P × PauliScalar P))) +            (fun q => ‖applyOperatorToState +              (S.placeStrategySide p.side +                (S.twistedCommutator p.side (q.1.1, q.1.2, q.2.1, q.2.2))) +              S.toStrategy.ψ‖ ^ 2) := +          (avgOver_uniform_prod (fun (xz : PointPair P) +            (rs : PauliScalar P × PauliScalar P) => ‖applyOperatorToState +              (S.placeStrategySide p.side +                (S.twistedCommutator p.side (xz.1, xz.2, rs.1, rs.2))) +              S.toStrategy.ψ‖ ^ 2)).symm +      _ = avgOver (uniformDistribution (PauliTuple P)) (fun ω => +            ‖applyOperatorToState +              (S.placeStrategySide p.side (S.twistedCommutator p.side ω)) +              S.toStrategy.ψ‖ ^ 2) := by +          rw [avgOver_uniform_equiv (Equiv.prodAssoc (Fin P.m → PauliScalar P) +            (Fin P.m → PauliScalar P) (PauliScalar P × PauliScalar P))] +          rfl +  rw [hfamily] +  exact h P ε S p.side hε + +end ProjectiveSetting + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/Points/Consistency.lean b/MIPStarRE/QPBT/Combining/Points/Consistency.lean new file mode 100644 index 00000000..b6c433fe --- /dev/null +++ b/MIPStarRE/QPBT/Combining/Points/Consistency.lean @@ -0,0 +1,428 @@ +import MIPStarRE.QPBT.Combining.Points.Sandwich + +/-! +# Self-consistency of the sandwich POVM + +The sandwich POVM `R^{x,z}_{a,b} = M^Z_b M^X_a M^Z_b` of +`MIPStarRE/QPBT/Combining/Points/Sandwich.lean` is approximately self-consistent +between opposite register placements.  The source establishes this by a +Cauchy--Schwarz chain (displays `eq:qld-rw-self-cons-1` to +`eq:qld-rw-self-cons-4`); here an exact identity is used instead.  Writing +`P_1, P_2` for the two placements of an operator `P`, +`W_b = (M^Z_b)_1 (M^Z_b)_2`, and `D^W_c = (M^W_c)_1 - (M^W_c)_2`, the +consistency defect of the two placed sandwiches equals +`(1/2) ∑_b ‖D^Z_b ψ‖^2 + (1/2) ∑_{a,b} ‖D^X_a W_b ψ‖^2`, +by two applications of the identity +`∑_c ⟨w, P_c Q_c w⟩ = ‖w‖^2 - (1/2) ∑_c ‖(P_c - Q_c) w‖^2` for projective +measurements.  The second sum is then bounded by the self-consistency of `M^X` +and the commutators on the two placements, since +`D^X_a W_b = W_b D^X_a + (M^Z_b)_2 K^1_{a,b} - (M^Z_b)_1 K^2_{a,b}`, where +`K^i_{a,b}` is the placed commutator of `M^X_a` and `M^Z_b`. + +## Main results + +* `sandwich_overlap_identity`: the exact expression of the overlap of two +  placed sandwiches. +* `sandwich_defect_pointwise_le`: the pointwise bound on the consistency +  defect of the sandwich for a fixed point pair. +* `ProjectiveSetting.sandwichDefectBound`, +  `ProjectiveSetting.sandwich_offDiagonal_le_sandwichDefectBound`, and +  `ProjectiveSetting.avg_sandwichDefectBound_le`: the bound as a function of +  the point pair, the pointwise estimate, and the average. + +## References + +Paper `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:743-790`, +blueprint `blueprint/src/chapter/ch15_qpbt_combining.tex:851-880` +(`lem:qld-4-10`, first step); the identity route is explained in +`docs/paper-gaps/qpbt_linearity-theorem-quotation.tex`. +-/ + +open scoped BigOperators Matrix MatrixOrder ComplexOrder + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT hiding Measurement +open MIPStarRE.Quantum DistanceCalculus + +noncomputable section + +/-! ## Quadratic-form identities -/ + +/-- The quadratic form of `Wᴴ M W` in `ψ` is the quadratic form of `M` in +`W ψ`. -/ +theorem stateQForm_conjTranspose_mul_mul {ι : Type*} [Fintype ι] [DecidableEq ι] +    (ψ : EuclideanSpace ℂ ι) (W M : Op ι) : +    stateQForm ψ (Wᴴ * M * W) = stateQForm (applyOperatorToState W ψ) M := by +  unfold stateQForm +  rw [applyOperatorToState_mul', applyOperatorToState_mul'] +  congr 1 +  change inner ℂ ψ (Matrix.toEuclideanLin Wᴴ _) = +    inner ℂ (Matrix.toEuclideanLin W ψ) _ +  rw [Matrix.toEuclideanLin_conjTranspose_eq_adjoint, LinearMap.adjoint_inner_right] + +/-- The squared norm of `W ψ` is the quadratic form of `Wᴴ W`. -/ +theorem norm_applyOperatorToState_sq_eq_stateQForm {ι : Type*} [Fintype ι] +    [DecidableEq ι] (ψ : EuclideanSpace ℂ ι) (W : Op ι) : +    ‖applyOperatorToState W ψ‖ ^ 2 = stateQForm ψ (Wᴴ * W) := +  MagicSquareRigidity.norm_applyOperatorToState_sq W ψ + +/-- For two projective measurements, the diagonal overlap in a vector `w` is +the squared norm of `w` minus half the summed squared distances.  This is the +identity behind `fact:agreement` for projective families, blueprint +`blueprint/src/chapter/ch12_qpbt_games.tex:260-272`. -/ +theorem sum_stateQForm_mul_eq_of_projective {α ι : Type*} [Fintype α] +    [Fintype ι] [DecidableEq ι] +    (A B : Measurement α ι) (w : EuclideanSpace ℂ ι) +    (hA : MIPStarRE.QPBT.Measurement.IsProjective A) +    (hB : MIPStarRE.QPBT.Measurement.IsProjective B) : +    ∑ a, stateQForm w (A.effect a * B.effect a) = +      ‖w‖ ^ 2 - +        (1 / 2) * ∑ a, ‖applyOperatorToState (A.effect a - B.effect a) w‖ ^ 2 := by +  classical +  rw [point_distance_eq_two_defect_of_projective A B w hA hB, point_defect_eq] +  ring + +/-- An effect of a projective measurement is a contraction. -/ +theorem norm_applyOperatorToState_proj_effect_le {α ι : Type*} [Fintype α] +    [Fintype ι] [DecidableEq ι] (M : Measurement α ι) +    (hM : MIPStarRE.QPBT.Measurement.IsProjective M) (a : α) +    (v : EuclideanSpace ℂ ι) : +    ‖applyOperatorToState (M.effect a) v‖ ≤ ‖v‖ := by +  refine MagicSquareRigidity.norm_applyOperatorToState_le ?_ v +  rw [(hM a).isSelfAdjoint.isHermitian.eq, (hM a).isIdempotentElem.eq] +  exact measurement_effect_le_one M a + +/-- The effects of a projective measurement are square-summable to the +identity. -/ +theorem sum_effect_conjTranspose_mul_self_le_one_of_projective {α ι : Type*} +    [Fintype α] [Fintype ι] [DecidableEq ι] (M : Measurement α ι) +    (hM : MIPStarRE.QPBT.Measurement.IsProjective M) : +    ∑ a, (M.effect a)ᴴ * M.effect a ≤ 1 := by +  refine le_of_eq ?_ +  calc ∑ a, (M.effect a)ᴴ * M.effect a = ∑ a, M.effect a := by +        refine Finset.sum_congr rfl fun a _ => ?_ +        rw [(hM a).isSelfAdjoint.isHermitian.eq, (hM a).isIdempotentElem.eq] +    _ = 1 := M.sum_eq_one + +/-! ## The overlap of two placed sandwiches -/ + +section Abstract + +variable {α β ι : Type*} [Fintype α] [Fintype β] [Fintype ι] [DecidableEq ι] + +/-- Formalization-only auxiliary for `lem:qld-4-10`: the product of the two +placed sandwiches is `W_bᴴ (X_1 X_2) W_b` with `W_b = Z_1 Z_2`, whenever the +operators of the two placements commute. -/ +theorem sandwich_mul_sandwich_eq (X₁ X₂ : Measurement α ι) (Z₁ Z₂ : Measurement β ι) +    (hXZ : ∀ a b, X₁.effect a * Z₂.effect b = Z₂.effect b * X₁.effect a) +    (hZX : ∀ a b, Z₁.effect b * X₂.effect a = X₂.effect a * Z₁.effect b) +    (hZZ : ∀ b, Z₁.effect b * Z₂.effect b = Z₂.effect b * Z₁.effect b) +    (a : α) (b : β) : +    (Z₁.effect b * X₁.effect a * Z₁.effect b) * +        (Z₂.effect b * X₂.effect a * Z₂.effect b) = +      (Z₁.effect b * Z₂.effect b)ᴴ * (X₁.effect a * X₂.effect a) * +        (Z₁.effect b * Z₂.effect b) := by +  rw [Matrix.conjTranspose_mul, measurement_effect_hermitian, +    measurement_effect_hermitian] +  simp only [Matrix.mul_assoc] +  rw [(show Commute (Z₁.effect b) (Z₂.effect b) from hZZ b).left_comm +      (X₂.effect a * Z₂.effect b), +    (show Commute (X₁.effect a) (Z₂.effect b) from hXZ a b).left_comm, +    (show Commute (Z₁.effect b) (Z₂.effect b) from hZZ b).left_comm, +    (show Commute (Z₁.effect b) (X₂.effect a) from hZX a b).left_comm] + +omit [DecidableEq ι] in +/-- Formalization-only auxiliary for `lem:qld-4-10`: the decomposition of +`(X_1 - X_2) Z_1 Z_2` into `Z_1 Z_2 (X_1 - X_2)` and the two commutator +terms. -/ +theorem sub_mul_mul_eq_add_commutators (X₁ X₂ Z₁ Z₂ : Op ι) +    (hXZ : X₁ * Z₂ = Z₂ * X₁) (hZX : Z₁ * X₂ = X₂ * Z₁) +    (hZZ : Z₁ * Z₂ = Z₂ * Z₁) : +    (X₁ - X₂) * (Z₁ * Z₂) = +      Z₁ * Z₂ * (X₁ - X₂) + Z₂ * (X₁ * Z₁ - Z₁ * X₁) - +        Z₁ * (X₂ * Z₂ - Z₂ * X₂) := by +  simp only [sub_mul, mul_sub, Matrix.mul_assoc] +  rw [(show Commute Z₂ X₁ from hXZ.symm).left_comm Z₁, ← hZZ, +    (show Commute Z₂ Z₁ from hZZ.symm).left_comm X₁, +    (show Commute Z₁ X₂ from hZX).left_comm Z₂] +  abel + +/-- The overlap of the two placed sandwiches, exactly: with +`W_b = Z_1(b) Z_2(b)`, +`∑_{a,b} ⟨ψ, R_1(a,b) R_2(a,b) ψ⟩ = ‖ψ‖^2 - (1/2) ∑_b ‖(Z_1(b) - Z_2(b)) ψ‖^2 +  - (1/2) ∑_{a,b} ‖(X_1(a) - X_2(a)) W_b ψ‖^2`. +This replaces the Cauchy--Schwarz chain of displays +`eq:qld-rw-self-cons-1` to `eq:qld-rw-self-cons-4`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:743-790`. -/ +theorem sandwich_overlap_identity (ψ : EuclideanSpace ℂ ι) +    (X₁ X₂ : Measurement α ι) (Z₁ Z₂ : Measurement β ι) +    (hX₁ : MIPStarRE.QPBT.Measurement.IsProjective X₁) +    (hX₂ : MIPStarRE.QPBT.Measurement.IsProjective X₂) +    (hZ₁ : MIPStarRE.QPBT.Measurement.IsProjective Z₁) +    (hZ₂ : MIPStarRE.QPBT.Measurement.IsProjective Z₂) +    (hXZ : ∀ a b, X₁.effect a * Z₂.effect b = Z₂.effect b * X₁.effect a) +    (hZX : ∀ a b, Z₁.effect b * X₂.effect a = X₂.effect a * Z₁.effect b) +    (hZZ : ∀ b, Z₁.effect b * Z₂.effect b = Z₂.effect b * Z₁.effect b) : +    ∑ ab : α × β, stateQForm ψ +        ((Z₁.effect ab.2 * X₁.effect ab.1 * Z₁.effect ab.2) * +          (Z₂.effect ab.2 * X₂.effect ab.1 * Z₂.effect ab.2)) = +      ‖ψ‖ ^ 2 - +        (1 / 2) * ∑ b, ‖applyOperatorToState (Z₁.effect b - Z₂.effect b) ψ‖ ^ 2 - +        (1 / 2) * ∑ ab : α × β, ‖applyOperatorToState (X₁.effect ab.1 - X₂.effect ab.1) +          (applyOperatorToState (Z₁.effect ab.2 * Z₂.effect ab.2) ψ)‖ ^ 2 := by +  have hW : ∀ b, ‖applyOperatorToState (Z₁.effect b * Z₂.effect b) ψ‖ ^ 2 = +      stateQForm ψ (Z₁.effect b * Z₂.effect b) := by +    intro b +    rw [norm_applyOperatorToState_sq_eq_stateQForm, Matrix.conjTranspose_mul, +      measurement_effect_hermitian, measurement_effect_hermitian] +    congr 1 +    rw [Matrix.mul_assoc, ← Matrix.mul_assoc (Z₁.effect b) (Z₁.effect b), +      (hZ₁ b).isIdempotentElem.eq, hZZ b, ← Matrix.mul_assoc, +      (hZ₂ b).isIdempotentElem.eq] +  have hstep : ∀ ab : α × β, stateQForm ψ +      ((Z₁.effect ab.2 * X₁.effect ab.1 * Z₁.effect ab.2) * +        (Z₂.effect ab.2 * X₂.effect ab.1 * Z₂.effect ab.2)) = +      stateQForm (applyOperatorToState (Z₁.effect ab.2 * Z₂.effect ab.2) ψ) +        (X₁.effect ab.1 * X₂.effect ab.1) := by +    intro ab +    rw [sandwich_mul_sandwich_eq X₁ X₂ Z₁ Z₂ hXZ hZX hZZ, +      stateQForm_conjTranspose_mul_mul] +  have hWsum : ∑ b, ‖applyOperatorToState (Z₁.effect b * Z₂.effect b) ψ‖ ^ 2 = +      ‖ψ‖ ^ 2 - +        (1 / 2) * ∑ b, ‖applyOperatorToState (Z₁.effect b - Z₂.effect b) ψ‖ ^ 2 := by +    simp_rw [hW] +    exact sum_stateQForm_mul_eq_of_projective Z₁ Z₂ ψ hZ₁ hZ₂ +  calc ∑ ab : α × β, stateQForm ψ +        ((Z₁.effect ab.2 * X₁.effect ab.1 * Z₁.effect ab.2) * +          (Z₂.effect ab.2 * X₂.effect ab.1 * Z₂.effect ab.2)) +      = ∑ b, ∑ a, stateQForm (applyOperatorToState (Z₁.effect b * Z₂.effect b) ψ) +          (X₁.effect a * X₂.effect a) := by +        simp_rw [hstep] +        exact Fintype.sum_prod_type_right _ +    _ = ∑ b, (‖applyOperatorToState (Z₁.effect b * Z₂.effect b) ψ‖ ^ 2 - +          (1 / 2) * ∑ a, ‖applyOperatorToState (X₁.effect a - X₂.effect a) +            (applyOperatorToState (Z₁.effect b * Z₂.effect b) ψ)‖ ^ 2) := by +        refine Finset.sum_congr rfl fun b _ => ?_ +        exact sum_stateQForm_mul_eq_of_projective X₁ X₂ _ hX₁ hX₂ +    _ = _ := by +        rw [Finset.sum_sub_distrib, ← Finset.mul_sum, hWsum, +          Fintype.sum_prod_type_right] + +/-- The pointwise bound on the consistency defect of the placed sandwiches: +in terms of the distances `D^Z`, `D^X` of the two placements and the placed +commutators `K^1`, `K^2`, +`‖ψ‖^2 - ∑_{a,b} ⟨ψ, R_1 R_2 ψ⟩ ≤ (1/2) D^Z + (3/2) (D^X + K^1 + K^2)`. -/ +theorem sandwich_defect_pointwise_le (ψ : EuclideanSpace ℂ ι) +    (X₁ X₂ : Measurement α ι) (Z₁ Z₂ : Measurement β ι) +    (hX₁ : MIPStarRE.QPBT.Measurement.IsProjective X₁) +    (hX₂ : MIPStarRE.QPBT.Measurement.IsProjective X₂) +    (hZ₁ : MIPStarRE.QPBT.Measurement.IsProjective Z₁) +    (hZ₂ : MIPStarRE.QPBT.Measurement.IsProjective Z₂) +    (hXZ : ∀ a b, X₁.effect a * Z₂.effect b = Z₂.effect b * X₁.effect a) +    (hZX : ∀ a b, Z₁.effect b * X₂.effect a = X₂.effect a * Z₁.effect b) +    (hZZ : ∀ b, Z₁.effect b * Z₂.effect b = Z₂.effect b * Z₁.effect b) : +    ‖ψ‖ ^ 2 - ∑ ab : α × β, stateQForm ψ +        ((Z₁.effect ab.2 * X₁.effect ab.1 * Z₁.effect ab.2) * +          (Z₂.effect ab.2 * X₂.effect ab.1 * Z₂.effect ab.2)) ≤ +      (1 / 2) * ∑ b, ‖applyOperatorToState (Z₁.effect b - Z₂.effect b) ψ‖ ^ 2 + +        (3 / 2) * ((∑ a, ‖applyOperatorToState (X₁.effect a - X₂.effect a) ψ‖ ^ 2) + +          (∑ ab : α × β, ‖applyOperatorToState +            (X₁.effect ab.1 * Z₁.effect ab.2 - +              Z₁.effect ab.2 * X₁.effect ab.1) ψ‖ ^ 2) + +          ∑ ab : α × β, ‖applyOperatorToState +            (X₂.effect ab.1 * Z₂.effect ab.2 - +              Z₂.effect ab.2 * X₂.effect ab.1) ψ‖ ^ 2) := by +  rw [sandwich_overlap_identity ψ X₁ X₂ Z₁ Z₂ hX₁ hX₂ hZ₁ hZ₂ hXZ hZX hZZ] +  -- the pointwise decomposition of `(X_1 - X_2) W_b ψ` +  have hpt : ∀ ab : α × β, +      ‖applyOperatorToState (X₁.effect ab.1 - X₂.effect ab.1) +          (applyOperatorToState (Z₁.effect ab.2 * Z₂.effect ab.2) ψ)‖ ^ 2 ≤ +        3 * (‖applyOperatorToState (Z₂.effect ab.2 * +              (X₁.effect ab.1 - X₂.effect ab.1)) ψ‖ ^ 2 + +          ‖applyOperatorToState +            (X₁.effect ab.1 * Z₁.effect ab.2 - +              Z₁.effect ab.2 * X₁.effect ab.1) ψ‖ ^ 2 + +          ‖applyOperatorToState +            (X₂.effect ab.1 * Z₂.effect ab.2 - +              Z₂.effect ab.2 * X₂.effect ab.1) ψ‖ ^ 2) := by +    intro ab +    obtain ⟨a, b⟩ := ab +    rw [← applyOperatorToState_mul', sub_mul_mul_eq_add_commutators _ _ _ _ +      (hXZ a b) (hZX a b) (hZZ b)] +    have hlin : applyOperatorToState +        (Z₁.effect b * Z₂.effect b * (X₁.effect a - X₂.effect a) + +          Z₂.effect b * (X₁.effect a * Z₁.effect b - Z₁.effect b * X₁.effect a) - +          Z₁.effect b * (X₂.effect a * Z₂.effect b - Z₂.effect b * X₂.effect a)) ψ = +        applyOperatorToState (Z₁.effect b) +            (applyOperatorToState (Z₂.effect b * (X₁.effect a - X₂.effect a)) ψ) + +          applyOperatorToState (Z₂.effect b) (applyOperatorToState +            (X₁.effect a * Z₁.effect b - Z₁.effect b * X₁.effect a) ψ) - +          applyOperatorToState (Z₁.effect b) (applyOperatorToState +            (X₂.effect a * Z₂.effect b - Z₂.effect b * X₂.effect a) ψ) := by +      rw [← applyOperatorToState_mul', ← applyOperatorToState_mul', +        ← applyOperatorToState_mul', Matrix.mul_assoc] +      unfold applyOperatorToState +      simp only [map_add, map_sub, LinearMap.add_apply, LinearMap.sub_apply] +    rw [hlin] +    set u := applyOperatorToState (Z₁.effect b) +      (applyOperatorToState (Z₂.effect b * (X₁.effect a - X₂.effect a)) ψ) +    set v := applyOperatorToState (Z₂.effect b) (applyOperatorToState +      (X₁.effect a * Z₁.effect b - Z₁.effect b * X₁.effect a) ψ) +    set w := applyOperatorToState (Z₁.effect b) (applyOperatorToState +      (X₂.effect a * Z₂.effect b - Z₂.effect b * X₂.effect a) ψ) +    have hu : ‖u‖ ≤ ‖applyOperatorToState +        (Z₂.effect b * (X₁.effect a - X₂.effect a)) ψ‖ := +      norm_applyOperatorToState_proj_effect_le Z₁ hZ₁ b _ +    have hv : ‖v‖ ≤ ‖applyOperatorToState +        (X₁.effect a * Z₁.effect b - Z₁.effect b * X₁.effect a) ψ‖ := +      norm_applyOperatorToState_proj_effect_le Z₂ hZ₂ b _ +    have hw : ‖w‖ ≤ ‖applyOperatorToState +        (X₂.effect a * Z₂.effect b - Z₂.effect b * X₂.effect a) ψ‖ := +      norm_applyOperatorToState_proj_effect_le Z₁ hZ₁ b _ +    have htri : ‖u + v - w‖ ≤ ‖u‖ + ‖v‖ + ‖w‖ := +      le_trans (norm_sub_le (u + v) w) (add_le_add (norm_add_le u v) (le_refl ‖w‖)) +    have hsq : ‖u + v - w‖ ^ 2 ≤ 3 * (‖u‖ ^ 2 + ‖v‖ ^ 