n (congrFun M.sum_eq_one (i, k₀)) (j, k₀)) + +@[simp] theorem compressAt_effect +    {Outcome I κ : Type*} +    [Fintype Outcome] [Fintype I] [DecidableEq I] +    [Fintype κ] [DecidableEq κ] +    (k₀ : κ) (M : MIPStarRE.Quantum.Measurement Outcome (I × κ)) (a : Outcome) : +    (M.compressAt k₀).effect a = +      (M.effect a).submatrix (fun i => (i, k₀)) (fun i => (i, k₀)) := +  rfl + +/-- Restricting a POVM to a fixed ancillary coordinate commutes with +deterministic relabeling of its outcomes. -/ +theorem compressAt_postprocess +    {A B I κ : Type*} +    [Fintype A] [DecidableEq A] [Fintype B] [DecidableEq B] +    [Fintype I] [DecidableEq I] [Fintype κ] [DecidableEq κ] +    (k₀ : κ) (M : MIPStarRE.Quantum.Measurement A (I × κ)) (f : A → B) : +    (M.postprocess f).compressAt k₀ = (M.compressAt k₀).postprocess f := by +  classical +  apply MIPStarRE.Quantum.Measurement.ext +  intro b +  ext i j +  simp only [compressAt_effect, MIPStarRE.Quantum.Measurement.postprocess_effect, +    Matrix.submatrix_apply, Matrix.sum_apply] + +end MIPStarRE.Quantum.Measurement + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT MIPStarRE.Quantum + +namespace Measurement + +/-- Compressing the completed one-measurement Naimark dilation at its +distinguished `none` coordinate recovers the original POVM. -/ +theorem compressAt_dilatedMeasurement +    {A I : Type} [Fintype A] [DecidableEq A] +    [Fintype I] [DecidableEq I] +    (a₀ : A) (M : MIPStarRE.Quantum.Measurement A I) : +    (dilatedMeasurement a₀ M).compressAt none = M := by +  apply MIPStarRE.Quantum.Measurement.ext +  intro a +  ext i j +  exact dilatedMeasurement_compression a₀ a M i j + +end Measurement + +/-- Ground-slice compression preserves exactly the off-diagonal consistency +defect when the bipartite state is padded at the same two ancillary +coordinates. This is an equality of POVM correlations and does not assert that +the compressed measurements are projective. -/ +theorem consistencyDefect_padState_compressAt +    {X Outcome I J κA κB : Type*} +    [Fintype X] [DecidableEq X] +    [Fintype Outcome] [DecidableEq Outcome] +    [Fintype I] [DecidableEq I] [Fintype J] [DecidableEq J] +    [Fintype κA] [DecidableEq κA] [Fintype κB] [DecidableEq κB] +    (μ : Distribution X) +    (MA : X → MIPStarRE.Quantum.Measurement Outcome (I × κA)) +    (MB : X → MIPStarRE.Quantum.Measurement Outcome (J × κB)) +    (a₀ : κA) (b₀ : κB) (ψ : EuclideanSpace ℂ (I × J)) : +    consistencyDefect μ +        (fun x a => heteroKron ((MA x).effect a) 1) +        (fun x a => heteroKron 1 ((MB x).effect a)) +        (padState a₀ b₀ ψ) = +      consistencyDefect μ +        (fun x a => heteroKron (((MA x).compressAt a₀).effect a) 1) +        (fun x a => heteroKron 1 (((MB x).compressAt b₀).effect a)) +        ψ := by +  unfold consistencyDefect +  apply avgOver_congr +  intro x +  apply Finset.sum_congr rfl +  intro a _ +  apply Finset.sum_congr rfl +  intro b _ +  by_cases hab : a = b +  · simp [hab] +  · simp only [hab, if_false] +    change vectorQForm (padState a₀ b₀ ψ) +        (heteroKron ((MA x).effect a) 1 * heteroKron 1 ((MB x).effect b)) = +      vectorQForm ψ +        (heteroKron (((MA x).compressAt a₀).effect a) 1 * +          heteroKron 1 (((MB x).compressAt b₀).effect b)) +    simpa only [heteroKron_mul, Matrix.mul_one, Matrix.one_mul] using +      stateQForm_padState a₀ b₀ ψ +        (((MA x).compressAt a₀).effect a) +        (((MB x).compressAt b₀).effect b) +        ((MA x).effect a) ((MB x).effect b) +        (fun i j => rfl) (fun i j => rfl) + +end MIPStarRE.QPBT diff --git a/local/briefs/340-ground-slice-povm-compression.md b/local/briefs/340-ground-slice-povm-compression.md new file mode 100644 index 00000000..b202fcaa --- /dev/null +++ b/local/briefs/340-ground-slice-povm-compression.md @@ -0,0 +1,37 @@ +# Issue 340: ground-slice POVM compression + +## Objective + +Provide the reusable fixed-coordinate compression needed to pull POVMs from a +Naimark-padded local space back to the original player space. Package the exact +transport of `consistencyDefect` across `padState` so direct low-degree +soundness bounds can be reused without an additional error term. + +## Mathematical contract + +For a POVM on `I × κ` and `k₀ : κ`, restrict each effect to the principal block +indexed by `i ↦ (i, k₀)`. Positivity follows from +`Matrix.PosSemidef.submatrix`, while completeness follows by evaluating the +original sum-to-identity equation on that block. The construction must commute +with deterministic outcome postprocessing. + +For two such POVM families and a bipartite state padded at `a₀` and `b₀`, every +off-diagonal term in `consistencyDefect` is unchanged by compression. The proof +uses `heteroKron_mul` and `stateQForm_padState` term by term. + +## Source and boundaries + +This is formalization-only infrastructure for the Naimark steps in the first +paragraph of paper `lem:qld-4-7`, +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1279-1289`. +It does not prove the source lemma, preserve projectivity under compression, or +introduce a producer or passing-value assumption. In particular, it uses one +fixed ancillary coordinate rather than the existing normalized average over +all diagonal blocks. + +## Validation + +- Type-check `MIPStarRE/QPBT/Games/MeasurementCompression.lean`. +- Scan the changed Lean file for proof holes and prohibited bypasses. +- Verify only documentation and aggregate imports changed outside the new +  module. diff --git a/local/briefs/346-direct-k-one-soundness-any-strategy.md b/local/briefs/346-direct-k-one-soundness-any-strategy.md new file mode 100644 index 00000000..f87ec955 --- /dev/null +++ b/local/briefs/346-direct-k-one-soundness-any-strategy.md @@ -0,0 +1,45 @@ +# Issue 346: arbitrary-strategy direct soundness at k = 1 + +## Objective + +Remove the projectivity premise from the formalization-only directly indexed +low-degree soundness route at simultaneity parameter `1`. Return the two +polynomial-tuple PO